      expect(File('lib/screens/wallet_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.payments'));
      expect(File('lib/screens/marketplace_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.marketplace'));
      expect(File('lib/screens/public_feed_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.publicFeed'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('ParentalRestriction.servers'));
      expect(File('lib/payments/payment_service.dart').readAsStringSync(),
          contains('parental_locked'));
    });
  });

  group('Call clarity and voice-channel media', () {
    test('tuneOpus turns on FEC, DTX and the 64k ceiling without wrecking '
        'the SDP', () {
      const sdp = 'v=0\r\n'
          'm=audio 9 UDP/TLS/RTP/SAVPF 111 103\r\n'
          'a=rtpmap:111 opus/48000/2\r\n'
          'a=fmtp:111 minptime=10;useinbandfec=0\r\n'
          'a=rtpmap:103 ISAC/16000\r\n';
      final tuned = CallQuality.tuneOpus(sdp);
      expect(tuned, contains('a=rtpmap:111 opus/48000/2'),
          reason: 'the rtpmap line must survive intact');
      expect(tuned, contains('useinbandfec=1'));
      expect(tuned, contains('usedtx=1'));
      expect(tuned, contains('maxaveragebitrate=64000'));
      expect(tuned, contains('minptime=10'),
          reason: 'params the platform negotiated are kept');
      expect(RegExp('useinbandfec').allMatches(tuned).length, 1,
          reason: 'a stale value is replaced, not stacked');

      // No fmtp line at all: one is added after the rtpmap, whole-line.
      const bare = 'a=rtpmap:96 opus/48000/2\r\na=rtpmap:97 ISAC/16000\r\n';
      final added = CallQuality.tuneOpus(bare);
      expect(added, contains('a=rtpmap:96 opus/48000/2\r\na=fmtp:96 '));
      expect(added, contains('a=rtpmap:97 ISAC/16000'));

      // No Opus: nothing to tune, nothing touched.
      const noOpus = 'a=rtpmap:96 VP8/90000\r\n';
      expect(CallQuality.tuneOpus(noOpus), noOpus);
    });

    test('for any pair exactly one side dials', () {
      expect(RoomMedia.initiates('15550001111', '15550002222'),
          isNot(RoomMedia.initiates('15550002222', '15550001111')),
          reason: 'both devices computing the same rule is what prevents '
              'the two-Alices race');
      expect(RoomMedia.initiates('15550001111', '15550001111'), isFalse);
      // Numberless codes and phone digits compare fine too.
      expect(RoomMedia.initiates('001234567890', '15550001111'),
          isNot(RoomMedia.initiates('15550001111', '001234567890')));
    });

    test('the mesh follows presence: joiners connect, leavers drop', () {
      final diff = RoomMedia.diffPeers(
          {'a', 'b', 'c'}, {'b', 'c', 'd'});
      expect(diff.add, {'d'});
      expect(diff.drop, {'a'});
      final none = RoomMedia.diffPeers({'a'}, {'a'});
      expect(none.add, isEmpty);
      expect(none.drop, isEmpty);
    });

    test('room signaling is sealed, live-only, and actually wired', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // The sender seals like call signaling and never queues: a room offer
      // replayed hours later would dial a room the sender already left.
      final sendBody = relay.substring(relay.indexOf('sendRoomSignal'),
          relay.indexOf('onRoomSignal'));
      expect(sendBody, contains('_sealSignalPair'));
      expect(sendBody, isNot(contains('_mailboxPut')));
      expect(relay, contains("event: 'vrtc'"));
      // The room's screen drives real media, not just presence flags.
      final screens = File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('.joinRoom(widget.communityId'));
      expect(screens, contains('.leaveRoom()'));
      expect(screens, contains('toggleScreenShare'));
      expect(screens, contains('enableCamera'));
      // And startup binds the two together.
      final mainSrc = File('lib/main.dart').readAsStringSync();
      expect(mainSrc, contains('RoomMedia.instance.send'));
      expect(mainSrc, contains('onRoomSignal'));
      expect(mainSrc, contains('RoomMedia.instance.bind()'));
      // The 1:1 call runs the same clarity profile.
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('CallQuality.micConstraints'));
      expect(media, contains('CallQuality.tuneOpus'));
    });

    test('the adaptive bitrate backs off hard and recovers slowly', () {
      final abr =
          AdaptiveBitrate(floor: 250000, ceiling: 2500000, start: 1200000);
      // Real loss: multiplicative decrease, and the change is reported so
      // the caller re-applies it to the senders.
      expect(abr.sample(0.10), isTrue);
      expect(abr.rate, 840000);
      expect(abr.sample(0.10), isTrue);
      expect(abr.rate, lessThan(840000));
      // It can be beaten down only to the floor.
      for (var i = 0; i < 20; i++) {
        abr.sample(0.5);
      }
      expect(abr.rate, 250000);
      expect(abr.sample(0.5), isFalse,
          reason: 'at the floor there is nothing left to change');
      // Clean windows earn additive raises, capped at the ceiling.
      expect(abr.sample(0.0), isTrue);
      expect(abr.rate, 350000);
      for (var i = 0; i < 100; i++) {
        abr.sample(0.0);
      }
      expect(abr.rate, 2500000);
      // The gray zone between thresholds changes nothing.
      expect(abr.sample(0.03), isFalse);
    });

    test('quality bars are the worse of loss and latency', () {
      // Loss alone called a 500 ms link perfect; a phone call at 500 ms is
      // not a good phone call.
      expect(CallMedia.qualityFor(0.0), 3);
      expect(CallMedia.qualityFor(0.0, rttMs: 500), 1);
      expect(CallMedia.qualityFor(0.0, rttMs: 300), 2);
      expect(CallMedia.qualityFor(0.10, rttMs: 50), 1,
          reason: 'good latency cannot buy back heavy loss');
      expect(CallMedia.qualityFor(0.03, rttMs: 300), 2);
    });

    test('a dead link redials itself — on both call shapes', () {
      // 1:1: CallMedia asks, CallService restarts, and only the original
      // caller does — a failure both ends see must not collide offers.
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('onNeedsIceRestart'));
      expect(media, contains("'iceRestart': true"));
      final service = File('lib/state/call_service.dart').readAsStringSync();
      expect(service, contains('restartIce'));
      expect(service, contains('CallDirection.outgoing'),
          reason: 'exactly one side may redial');
      expect(File('lib/main.dart').readAsStringSync(),
          contains('onNeedsIceRestart'));
      // Mesh: the pair's initiator redials its own dead leg.
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('_restartPeer'));
      expect(room, contains("'iceRestart': true"));
      // And a TCP TURN path exists for UDP-swallowing networks.
      expect(media, contains('transport=tcp'));
    });

    test('the speaking ring is voice, with a hold against flicker', () {
      expect(CallQuality.audible(0.2), isTrue);
      expect(CallQuality.audible(0.001), isFalse,
          reason: 'noise floor must not light the ring');
      expect(CallQuality.audible(null), isFalse);
      // The room reads real levels when media is live and says so.
      final screens =
          File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('amSpeaking'));
      expect(screens, contains('isSpeaking(o.digits)'));
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('audioLevel'));
      expect(room, contains('_speechHold'),
          reason: 'the gap between two words must not flicker the ring');
    });

    test('iOS gets a real call audio session, and rooms play out loud', () {
      // The knob most WebRTC apps forget: Apple's own voice pipeline under
      // WebRTC's, earpiece for voice calls, speaker for video and rooms.
      final quality = File('lib/state/call_quality.dart').readAsStringSync();
      expect(quality, contains('setAppleAudioIOMode'));
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('configureAudioSession(speaker: video)'),
          reason: 'a voice call belongs on the earpiece, video on speaker');
      expect(media, contains('configureAudioSession(speaker: true)'),
          reason: 'a camera turning on mid-call moves to the speaker');
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('configureAudioSession(speaker: speaker)'),
          reason: 'the room routes by what it is serving');
      expect(room, contains('speaker: true'),
          reason: 'a voice channel held to the ear is a phone call '
              'pretending — channels are speaker-first');
      // Each mesh leg adapts its own bitrate; the room reports its worst
      // link in words instead of silently degrading.
      expect(room, contains('_abrByPeer'));
      expect(room, contains('roomQuality'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('poor connection'));
    });

    test('the call check names the missing path instead of guessing', () {
      (String, bool) v(CallProbe p) => CallSelfTest.verdictFor(
          supported: true, probe: p, error: null);
      // The everything-works case says so and blames nothing.
      final ok = v(const CallProbe(micOk: true, host: 2, srflx: 1, relay: 2));
      expect(ok.$2, isFalse);
      expect(ok.$1, contains('can connect'));
      // No relay is THE "calls sometimes fail" diagnosis: fine on Wi-Fi,
      // dead between two phones on cellular.
      final noRelay =
          v(const CallProbe(micOk: true, host: 2, srflx: 1, relay: 0));
      expect(noRelay.$2, isTrue);
      expect(noRelay.$1, contains('cellular'));
      expect(noRelay.$1, contains('TURN'));
      // A dead mic outranks the network: a call without one is text.
      final noMic =
          v(const CallProbe(micOk: false, host: 2, srflx: 1, relay: 2));
      expect(noMic.$2, isTrue);
      expect(noMic.$1.toLowerCase(), contains('microphone'));
      // No sockets at all is its own sentence, not a TURN complaint.
      final dead = v(const CallProbe(micOk: true, host: 0, srflx: 0, relay: 0));
      expect(dead.$2, isTrue);
      expect(dead.$1, contains('socket'));

      // And the candidate classifier reads real ICE lines.
      expect(
          CallSelfTest.candidateType(
              'candidate:1 1 udp 2122260223 192.168.1.5 54321 typ host'),
          'host');
      expect(
          CallSelfTest.candidateType(
              'candidate:2 1 udp 1686052607 88.1.2.3 6000 typ srflx '
              'raddr 192.168.1.5 rport 54321'),
          'srflx');
      expect(
          CallSelfTest.candidateType(
              'candidate:3 1 udp 41885439 44.5.6.7 3478 typ relay '
              'raddr 88.1.2.3 rport 6000'),
          'relay');
      expect(CallSelfTest.candidateType(null), isNull);

      // The whole report runs from an injected probe — no network.
      CallSelfTest.debugProbe = () async =>
          const CallProbe(micOk: true, host: 1, srflx: 1, relay: 0);
      addTearDown(() => CallSelfTest.debugProbe = null);
      // And the settings screen offers it next to the push check.
      expect(File('lib/screens/settings_screen.dart').readAsStringSync(),
          contains('Check call setup'));
    });

    test('mesh renegotiation cannot glare: only the initiator offers', () {
      final room = File('lib/state/room_media.dart').readAsStringSync();
      // The non-initiator asks for a round instead of offering into a
      // possible head-on collision; one round renegotiates both directions.
      expect(room, contains("kind: 'renegreq'"));
      final reneg = room.substring(room.indexOf('Future<void> _renegotiate'));
      expect(reneg.substring(0, reneg.indexOf('try {')),
          contains('initiates(_myDigits, digits)'),
          reason: 'the role check must come before any offer is created');
      // And a share that moves no frames stops itself in rooms too, with
      // the badge coming back off for everyone.
      expect(room, contains('_verifyShareMovesFrames'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('_onShareFailure'));
    });

    test('the mesh has a stated ceiling, and every device picks the same '
        'room', () {
      // Under the cap: everyone connects to everyone.
      expect(RoomMedia.legsFor({'2', '3'}, '1'), {'2', '3'});
      // Over it: the first eight by digit-sort mesh; the rest are presence
      // only — and every member computes the SAME subset, or each phone
      // would connect to a different eight.
      final present = {for (var i = 2; i <= 10; i++) '$i'.padLeft(2, '0')};
      final legs = RoomMedia.legsFor(present, '01');
      expect(legs.length, RoomMedia.maxRoomSize - 1);
      expect(legs, isNot(contains('10')),
          reason: 'the sorted overflow member stays presence-only');
      // A member outside the first eight holds no legs at all rather than
      // half a room.
      expect(RoomMedia.legsFor({for (var i = 1; i <= 9; i++) '0$i'}, '99'),
          isEmpty);
      // And the join path refuses a full room BEFORE presence lists a
      // member nobody can hear.
      final screens =
          File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('full for voice'));
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('maxRoomSize'));
    });

    test('a stalled call points at the diagnosis instead of spinning', () {
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('connectStalled'));
      final screen = File('lib/screens/call_screen.dart').readAsStringSync();
      expect(screen, contains('Check call setup'),
          reason: '"Connecting…" forever must name the tool that explains '
              'it');
    });

    test('a bad call leaves a trace in the log', () {
      final rec = callmodel.CallRecord(
        id: 'q1',
        user: MockData.contacts().first,
        time: DateTime(2026, 1, 1),
        type: callmodel.CallType.voice,
        direction: callmodel.CallDirection.incoming,
