    test('group calls finally carry sound: the mesh follows the roster', () {
      // The roster→mesh mapping is pure: joined members and nobody else.
      final ada = MockData.contacts()[0];
      final grace = MockData.contacts()[1];
      final c = CallSession(
        callId: 'gc1',
        peer: ada,
        video: false,
        direction: CallDirection.outgoing,
        status: CallStatus.connected,
        members: [
          GroupCallMember(ada, GroupCallMemberState.joined),
          GroupCallMember(grace, GroupCallMemberState.ringing),
        ],
      );
      final digits = CallService.joinedDigits(c);
      expect(digits, {ada.phone.replaceAll(RegExp(r'\D'), '')},
          reason: 'someone still ringing has no leg to connect');

      // The lifecycle drives the mesh: joins open it, updates re-aim it,
      // every way out closes it — and only ITS room, never a voice channel
      // joined since.
      final service = File('lib/state/call_service.dart').readAsStringSync();
      expect(service, contains('_startGroupMedia'));
      expect(service, contains('updateCallPeers'));
      expect(service, contains('leaveCall'));
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains("'gc|"));
      final leaveBody = room.substring(room.indexOf('Future<void> leaveCall'));
      expect(leaveBody.substring(0, leaveBody.indexOf('}')),
          contains('roomIdForCall'),
          reason: 'a group call ending must not tear down a voice channel');
      // Mute reaches whichever transport is live, and the roster shows a
      // member\'s video only when their leg really carries pictures.
      final screen = File('lib/screens/call_screen.dart').readAsStringSync();
      expect(screen, contains('RoomMedia.instance.setMuted'));
      expect(screen, contains('getVideoTracks().isNotEmpty'),
          reason: 'an audio-only stream keeps the avatar, not a black box');
    });

    test('fetched TURN credentials reach every call, and never break one',
        () {
      // The parser takes exactly the function\'s shape and nothing else.
      final good = TurnService.parseIceServers(jsonEncode({
        'iceServers': [
          {
            'urls': ['turn:relay.example.com:443'],
            'username': 'u',
            'credential': 'c',
          },
          {'urls': 'stun:stun.example.com'},
        ],
        'ttlSeconds': 1800,
      }));
      expect(good.servers.length, 2);
      expect(good.servers.first['username'], 'u');
      expect(good.ttlSeconds, 1800);
      // Malformed answers yield nothing, never a throw — the fetch may
      // only ever ADD servers.
      expect(TurnService.parseIceServers('not json').servers, isEmpty);
      expect(TurnService.parseIceServers('{"iceServers": "x"}').servers,
          isEmpty);
      expect(
          TurnService.parseIceServers(jsonEncode({
            'iceServers': [
              {'username': 'no-urls'}
            ]
          })).servers,
          isEmpty,
          reason: 'a server without urls is not a server');

      // Fetched relays are tried BEFORE the dead public one.
      final merged = CallMedia.mergeIce({
        'iceServers': [
          {'urls': 'stun:old'}
        ]
      }, [
        {'urls': 'turn:fresh', 'username': 'u', 'credential': 'c'}
      ]);
      final list = merged['iceServers'] as List;
      expect((list.first as Map)['urls'], 'turn:fresh');
      expect(list.length, 2);
      expect(
          CallMedia.mergeIce(const {'iceServers': []}, const []),
          const {'iceServers': []},
          reason: 'nothing fetched leaves the config untouched');

      // Every surface asks for the RESOLVED config — the 1:1 call, the
      // mesh, and the self-test that verifies the fix it recommends.
      expect(File('lib/state/call_media.dart').readAsStringSync(),
          contains('resolvedRtcConfig()'));
      expect(File('lib/state/room_media.dart').readAsStringSync(),
          contains('resolvedRtcConfig()'));
      final diag =
          File('lib/state/call_diagnostics.dart').readAsStringSync();
      expect(diag, contains('resolvedRtcConfig()'));
      expect(diag, contains('TurnService.invalidate'),
          reason: '"run it again" after setting secrets must mean again');
      expect(diag, contains('docs/turn_setup.md'),
          reason: 'the red relay row must name its own fix');
      // The function exists, covers both credential sources, and has a
      // paste copy so it can actually be deployed.
      final fn = File('supabase/functions/turn-credentials/index.ts')
          .readAsStringSync();
      expect(fn, contains('METERED_DOMAIN'));
      expect(fn, contains('TURN_SHARED_SECRET'));
      expect(fn, contains('HMAC'),
          reason: 'coturn credentials are minted server-side');
      expect(
          File('docs/edge_functions_paste/turn-credentials.ts').existsSync(),
          isTrue);
    });

    test('hold silences BOTH directions and tells the other side', () {
      final media = File('lib/state/call_media.dart').readAsStringSync();
      // renderer.muted is a web semantic — on the phone remote audio plays
      // through the audio session regardless, which is why hold used to
      // mute you and leave them perfectly audible.
      expect(media, contains('getAudioTracks().forEach((t) => t.enabled = !held)'));
      final service = File('lib/state/call_service.dart').readAsStringSync();
      expect(service, contains("'hold': CallMedia.instance.onHold.value"),
          reason: 'a hold that only acts locally leaves the peer talking '
              'into an unexplained void');
      expect(service, contains('peerOnHold'));
      final screen = File('lib/screens/call_screen.dart').readAsStringSync();
      expect(screen, contains('They put you on hold'));
      expect(screen, contains('CallService.instance.setHold'),
          reason: 'the button must go through the announcing path');
    });

    test('pull-to-refresh on the marketplace asks every server for its '
        'listings', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // The ask is broadcast per server; each member answers with what THEY
      // authored — complete coverage without n-fold duplicates — and the
      // answer path is membership-checked and rate-limited.
      expect(relay, contains('requestFeedCatchup'));
      expect(relay, contains("event: 'fbcat'"));
      expect(relay, contains('applyFbcat'));
      expect(relay, contains('authoredOnly: true'));
      final fbcat = relay.substring(relay.indexOf('void applyFbcat'));
      expect(fbcat.substring(0, fbcat.indexOf('applySkreq')),
          contains('members.any'),
          reason: 'a non-member must not be able to drain the feed');
      final market =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(market, contains('PullToRefresh'));
      expect(market, contains('requestFeedCatchup'));
    });

    test('server posts get a durable sealed copy — and chats never do', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // Stored under the community SECRET, not a sender-key chain: chain
      // keys die on use, and a stored listing must open for any member on
      // any day.
      final store = relay.substring(relay.indexOf('_storeCommunityPost('));
      expect(store.substring(0, store.indexOf('sendFeedPost')),
          contains('E2eCrypto.encrypt(secret'));
      // Post → upsert; delete → row dies; fetch feeds the normal arrival
      // path on start AND on pull-to-refresh.
      expect(relay, contains('_storeCommunityPost(community, post)'));
      expect(relay, contains('_deleteCommunityPost(communityId, postId)'));
      expect(relay, contains('fetchCommunityPosts'));
      final del = relay.substring(relay.indexOf('Future<void> sendFeedDelete'));
      expect(del.substring(0, del.indexOf(';')), isNot(contains('mailbox')));
      // The one thing that must never gain a durable server copy: the
      // messages table name does not exist, and the store function only
      // ever takes a FeedPost.
      expect(relay, isNot(contains("'messages'")));
      expect(store, contains('FeedPost post'));
      // And the SQL ships + is exercised by the gate.
      expect(File('docs/community_posts.sql').existsSync(), isTrue);
      expect(File('tool/check_sql.sh').readAsStringSync(),
          contains('community_posts.sql'));
    });

    test('the call screen can say whether the relay is carrying the call', () {
      // The selection order the pure picker must honor: the transport's
      // chosen pair, then a nominated succeeded pair, then any succeeded.
      List<(String, String, Map<dynamic, dynamic>)> reports(
              {String? selectedId}) =>
          [
            ('local-candidate', 'lc_host', {'candidateType': 'host'}),
            ('local-candidate', 'lc_relay', {'candidateType': 'relay'}),
            (
              'candidate-pair',
              'pair_direct',
              {'state': 'succeeded', 'localCandidateId': 'lc_host'}
            ),
            (
              'candidate-pair',
              'pair_relay',
              {
                'state': 'succeeded',
                'nominated': true,
                'localCandidateId': 'lc_relay'
              }
            ),
            if (selectedId != null)
              ('transport', 't1', {'selectedCandidatePairId': selectedId}),
          ];
      expect(CallMedia.selectedLocalType(reports(selectedId: 'pair_direct')),
          'host', reason: 'the transport\'s word outranks nomination');
      expect(CallMedia.selectedLocalType(reports()), 'relay',
          reason: 'without a transport report, the nominated pair decides');
      expect(CallMedia.selectedLocalType(const []), isNull);
      // And the screen says it, in words a person can act on.
      expect(File('lib/screens/call_screen.dart').readAsStringSync(),
          contains('via relay'));
    });

    test('a missed hang-up cannot zombie the call', () {
      final service = File('lib/state/call_service.dart').readAsStringSync();
      // The far side's 'end' is queued to the mailbox; a dead media link
      // fetches it NOW instead of at the next app-open, and a link still
      // dead after the restart window ends the call locally.
      final watchdog = service.substring(service.indexOf('onMediaState'));
      final body = watchdog.substring(0, watchdog.indexOf('restartIce'));
      expect(body, contains('fetchMailbox'));
      expect(body, contains('end();'));
      expect(File('lib/main.dart').readAsStringSync(),
          contains('onMediaState'));
    });

    test('a number the directory has never heard of gets an invite, not a '
        'chat', () async {
      // Unknown is not "no": with no session (this test env) the check must
      // answer null and the caller must fail OPEN.
      Session.instance.user.value = null;
      expect(await AccountService.instance.isOnApp('15550009999'), isNull);
      // Both blind number entries route through the one gate.
      expect(File('lib/screens/new_chat_screen.dart').readAsStringSync(),
          contains('allowChatWithNumber'));
      expect(File('lib/screens/people_screen.dart').readAsStringSync(),
          contains('allowChatWithNumber'));
      final prompt =
          File('lib/widgets/invite_prompt.dart').readAsStringSync();
      expect(prompt, contains('onApp != false'),
          reason: 'only a confident "not on the app" blocks — null allows');
      expect(prompt, contains('Copy invite'));
    });
  });

  group('Ads', () {
    test('ads exist only where the world can already see', () {
      // The two public surfaces carry the slot; nothing else may. Chats,
      // calls and servers are the promise — an ad inside a conversation
      // is the app breaking its own word.
      expect(File('lib/screens/public_feed_screen.dart').readAsStringSync(),
          contains('AdBannerSlot'));
      expect(File('lib/screens/marketplace_screen.dart').readAsStringSync(),
          contains('AdBannerSlot'));
