  group('Listing options (brand, was-price) and the form\'s shape', () {
    test('a listing carries a brand and a was-price, and both survive json',
        () {
      FeedStore.instance.resetForTest();
      addTearDown(FeedStore.instance.resetForTest);
      final listing = FeedStore.instance.addListing(
        'c1',
        title: 'City bike',
        priceCents: 12000,
        category: 'Sports',
        brand: 'Trek',
        prevPriceCents: 20000,
      );
      expect(listing.listingBrand, 'Trek');
      expect(listing.prevPriceCents, 20000,
          reason: 'shown struck through, because it is above the ask');
      final back = FeedPost.fromJson(listing.toJson());
      expect(back.listingBrand, 'Trek');
      expect(back.prevPriceCents, 20000);

      // A "was" at or below the ask is not a discount and is dropped.
      final noDrop = FeedStore.instance.addListing(
        'c1',
        title: 'Lamp',
        priceCents: 2000,
        category: 'Furniture',
        prevPriceCents: 1500,
      );
      expect(noDrop.prevPriceCents, 0);

      // Editing keeps the brand unless a new one is given, and marking
      // sold (a copyWith path) must not lose it either.
      FeedStore.instance.updateListing(listing.id,
          title: 'City bike', priceCents: 12000, category: 'Sports');
      expect(FeedStore.instance.postById(listing.id)!.listingBrand, 'Trek');
      FeedStore.instance.setListingSold(listing.id, true);
      expect(FeedStore.instance.postById(listing.id)!.listingBrand, 'Trek');
    });

    test('search finds the field, not just the prose', () {
      final bike = FeedPost(
        id: 'l1',
        communityId: 'c1',
        authorName: 'Ada',
        authorUsername: 'ada',
        time: DateTime(2026),
        text: 'City bike\nFreshly tuned.',
        priceCents: 12000,
        listingBrand: 'Trek',
        listingPlace: 'Downtown',
      );
      expect(listingMatchesQuery(bike, 'trek'), isTrue,
          reason: 'the brand is what a buyer types');
      expect(listingMatchesQuery(bike, 'downtown'), isTrue,
          reason: 'so is the pickup area');
      expect(listingMatchesQuery(bike, 'bike'), isTrue);
      expect(listingMatchesQuery(bike, 'kayak'), isFalse);
      expect(listingMatchesQuery(bike, '  '), isTrue,
          reason: 'blank matches everything');
    });

    test('an offer opens the chat typed and ready, never sent unread', () {
      final bike = FeedPost(
        id: 'l1',
        communityId: 'c1',
        authorName: 'Ada',
        authorUsername: 'ada',
        time: DateTime(2026),
        text: 'City bike\nFreshly tuned.',
        priceCents: 12000,
        listingOffers: true,
      );
      expect(offerOpener(bike, 9000),
          'Would you take \$90 for "City bike"? (asking \$120)');
      // The button exists only where the seller invited it, and never on
      // something already sold.
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(src,
          contains('if (listing.listingOffers && !listing.listingSold)'));
      expect(src, contains('makeOffer(context, listing)'));
      // Seeded as a DRAFT through the same seller-chat path — the opener
      // rides setDraft, so nothing is sent until the person hits send.
      expect(src, contains('store.setDraft(chat.id, opener)'));
    });

    test('the price filter has honest edges, and free means zero', () {
      FeedPost priced(int cents) => FeedPost(
            id: 'p$cents',
            communityId: 'c1',
            authorName: 'A',
            authorUsername: 'a',
            time: DateTime(2026),
            text: 'x',
            priceCents: cents,
          );
      expect(listingInPriceRange(priced(5000), minCents: 2500), isTrue);
      expect(listingInPriceRange(priced(5000), maxCents: 2500), isFalse);
      expect(
          listingInPriceRange(priced(2500), minCents: 2500, maxCents: 2500),
          isTrue,
          reason: 'the bounds are inclusive');
      expect(listingInPriceRange(priced(0), maxCents: 2500), isTrue,
          reason: 'free sits under every ceiling');
      expect(listingInPriceRange(priced(0), minCents: 100), isFalse,
          reason: 'and over no floor');
      // The grid really applies it, and the sheet really offers it.
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(src, contains('listingInPriceRange(l,'));
      expect(src, contains("Text('PRICE',"));
    });

    test('more-like-this stays in the category and skips the sold', () {
      FeedPost item(String id, String cat,
              {bool sold = false, int day = 1}) =>
          FeedPost(
            id: id,
            communityId: 'c1',
            authorName: 'A',
            authorUsername: 'a',
            time: DateTime(2026, 1, day),
            text: id,
            priceCents: 100,
            listingCategory: cat,
            listingSold: sold,
          );
      final self = item('self', 'Sports');
      final all = [
        self,
        item('a', 'Sports', day: 3),
        item('b', 'Sports', day: 2),
        item('sold', 'Sports', sold: true),
        item('other', 'Furniture'),
      ];
      expect(moreLikeThis(all, self).map((l) => l.id), ['a', 'b'],
          reason: 'same category, newest first, never itself or the sold');
      expect(moreLikeThis([self], self), isEmpty,
          reason: 'an honest gap beats padding with the unrelated');
    });

    test('a forwarded listing reads as a listing, not a blob', () {
      final bike = FeedPost(
        id: 'l1',
        communityId: 'c1',
        authorName: 'Ada',
        authorUsername: 'ada',
        time: DateTime(2026),
        text: 'City bike\nFreshly tuned.',
        priceCents: 12000,
        listingBrand: 'Trek',
        listingCondition: 'Good',
        listingPlace: 'Downtown',
      );
      final text = listingShareText(bike);
      expect(text.split('\n').first, 'City bike — \$120');
      expect(text, contains('Trek · Good · Downtown'));
      expect(text, contains('Freshly tuned.'));
      // And the detail screen offers the door.
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(src, contains('ForwardScreen(text: listingShareText(listing))'));
    });

    test('recently viewed remembers, dedupes, caps, and survives deletion',
        () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(store.resetForTest);
      for (var i = 1; i <= 10; i++) {
        store.addListing('c1',
            title: 'Item $i', priceCents: 100 * i, category: 'Sports');
      }
      final ids = store.listings().map((l) => l.id).toList();
      for (final id in ids) {
        store.noteViewed(id);
      }
      expect(store.recentlyViewed().length, FeedStore.maxRecentlyViewed,
          reason: 'a shelf, not an archive');
      // Re-viewing moves to the front rather than duplicating.
      store.noteViewed(ids[3]);
      expect(store.recentlyViewed().first.id, ids[3]);
      expect(
          store.recentlyViewed().where((l) => l.id == ids[3]).length, 1);
      // A deleted listing quietly leaves the shelf.
      store.deletePost(ids[3]);
      expect(store.recentlyViewed().any((l) => l.id == ids[3]), isFalse);
    });

    test('price drops surface only for saved, unsold, still-cheaper', () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(store.resetForTest);
      final saved = store.addListing('c1',
          title: 'Bike', priceCents: 10000, category: 'Sports');
      final unsaved = store.addListing('c1',
          title: 'Lamp', priceCents: 5000, category: 'Furniture');
      store.toggleSaved(saved.id);
      expect(store.savedPriceDrops(), isEmpty,
          reason: 'no drop has happened yet');

      // The price drops (updateListing keeps the old ask as history).
      store.updateListing(saved.id,
          title: 'Bike', priceCents: 8000, category: 'Sports');
      store.updateListing(unsaved.id,
          title: 'Lamp', priceCents: 4000, category: 'Furniture');
      expect(store.savedPriceDrops().map((l) => l.id), [saved.id],
          reason: 'only the saved one is anybody\'s news');

      // Sold kills the banner — a discount on the unbuyable is noise.
      store.setListingSold(saved.id, true);
      expect(store.savedPriceDrops(), isEmpty);

      // And the screen draws the banner and the shelf.
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(src, contains('savedPriceDrops()'));
      expect(src, contains("'Recently viewed'"));
      expect(src, contains('noteViewed(listing.id)'));
    });

    test('the form is chapters now, and the new fields are on it', () {
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      for (final section in [
        "'Photos & video'",
        "'What it is'",
        "'The price'",
        "'The handoff'",
        "'Description'",
      ]) {
        expect(src, contains('_section($section)'),
            reason: 'the $section chapter must exist');
      }
      expect(src, contains("'Brand (optional)'"));
      expect(src, contains("'Was (optional)'"));
      // The was-price is a CREATE-time field only: on an edit it would
      // fight the automatic price-drop history.
      expect(src, contains('if (widget.existing == null) ...['));
      // And the card says the brand.
      expect(src, contains('listing.listingBrand'));
    });
  });

  group('Custom bubble color', () {
    Color outgoingBubbleColor(WidgetTester tester) {
      final containers = tester.widgetList<Container>(
        find.descendant(
          of: find.byType(MessageBubble),
          matching: find.byType(Container),
        ),
      );
      final bubble = containers.firstWhere(
        (c) => c.decoration is BoxDecoration &&
            (c.decoration as BoxDecoration).color != null,
      );
      return (bubble.decoration as BoxDecoration).color!;
    }

    testWidgets('anyone can pick and reset a bubble color — no paywall',
        (tester) async {
      AppState.setVerified(false); // no longer gated
      await tester.pumpWidget(
        const MaterialApp(home: ChatsSettingsScreen()),
      );
      await tester.pumpAndSettle();

      // The perk is free now: no lock, no upgrade copy.
      expect(find.text('Chat bubble color'), findsOneWidget);
      expect(find.text('An Okay Pro perk'), findsNothing);
      expect(find.byIcon(Icons.lock_outline), findsNothing);

      await tester.tap(find.text('Chat bubble color'));
      await tester.pumpAndSettle();

      // The picker sheet opens.
      expect(find.text('Bubble color'), findsOneWidget);
      // Tap the Pro purple swatch (third in the palette).
      final swatch = find.descendant(
        of: find.byType(BottomSheet),
        matching: find.byType(GestureDetector),
      );
      await tester.tap(swatch.at(2));
      await tester.pumpAndSettle();
      expect(AppState.bubbleColor.value, const Color(0xFF7A5CFF));

      // Reopen and reset to default.
      await tester.tap(find.text('Chat bubble color'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Reset to default green'));
      await tester.pumpAndSettle();
      expect(AppState.bubbleColor.value, isNull);
    });

    testWidgets('outgoing bubble honors the custom color', (tester) async {
      AppState.bubbleColor.value = const Color(0xFFEB4B7E);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'm1',
                text: 'hello',
                time: DateTime(2020, 1, 1, 10),
                isMe: true,
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      expect(outgoingBubbleColor(tester), const Color(0xFFEB4B7E));
    });

    testWidgets('incoming bubble ignores the custom color', (tester) async {
      AppState.bubbleColor.value = const Color(0xFFEB4B7E);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'm2',
                text: 'hi there',
                time: DateTime(2020, 1, 1, 10),
                isMe: false,
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      expect(outgoingBubbleColor(tester), isNot(const Color(0xFFEB4B7E)));
    });
  });

  group('Chat list filters', () {
    Future<void> pumpTab(WidgetTester tester) async {
      // The chip bar is hidden by default; reveal it for these tests.
      ChatsTab.filtersVisible.value = true;
      await tester.pumpWidget(
        const MaterialApp(home: Scaffold(body: ChatsTab())),
      );
      await tester.pumpAndSettle();
    }

    testWidgets('filter chips are hidden by default', (tester) async {
      await tester.pumpWidget(
        const MaterialApp(home: Scaffold(body: ChatsTab())),
      );
      await tester.pumpAndSettle();
      // No chip row until it's toggled on from the menu.
      expect(find.text('Unread'), findsNothing);
      expect(find.text('Groups'), findsNothing);
      // The chat list is still shown, unfiltered.
      expect(find.text('Bob Carter'), findsOneWidget);
    });

    testWidgets('overflow menu toggles the filter chips', (tester) async {
      await tester.pumpWidget(const OkayMessagingApp());
      await tester.pumpAndSettle();
      expect(find.text('Unread'), findsNothing);

      await tester.tap(find.byIcon(Icons.more_vert));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Filter chats'));
      await tester.pumpAndSettle();
      expect(find.text('Unread'), findsOneWidget);

      // The menu now offers to hide them again.
      await tester.tap(find.byIcon(Icons.more_vert));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Hide filters'));
      await tester.pumpAndSettle();
      expect(find.text('Unread'), findsNothing);
    });

    test('ChatFilter.matches applies the right predicate', () {
      final store = ChatStore.instance;
      final group = store.chatById('c_dev')!; // Team Standup, unread 5
      final read = store.chatById('c_bob')!; // no unread, 1:1
      expect(ChatFilter.all.matches(read), isTrue);
      expect(ChatFilter.unread.matches(group), isTrue);
      expect(ChatFilter.unread.matches(read), isFalse);
      expect(ChatFilter.groups.matches(group), isTrue);
      expect(ChatFilter.groups.matches(read), isFalse);
      expect(ChatFilter.favorites.matches(read), isFalse);
    });

    testWidgets('Favourites chip appears only after favouriting',
        (tester) async {
      await pumpTab(tester);
      expect(find.text('All'), findsOneWidget);
      expect(find.text('Unread'), findsOneWidget);
      expect(find.text('Groups'), findsOneWidget);
      expect(find.text('Favourites'), findsNothing);

      ChatStore.instance.toggleFavorite('c_alice');
      await tester.pumpAndSettle();
      expect(find.text('Favourites'), findsOneWidget);
    });

    testWidgets('Unread filter shows only unread chats', (tester) async {
      await pumpTab(tester);
      expect(find.text('Bob Carter'), findsOneWidget);

      await tester.tap(find.text('Unread'));
      await tester.pumpAndSettle();

      expect(find.text('Team Standup'), findsOneWidget); // unread 5
      expect(find.text('Bob Carter'), findsNothing); // read
    });

    testWidgets('Groups filter shows only group chats', (tester) async {
      await pumpTab(tester);
      await tester.tap(find.text('Groups'));
      await tester.pumpAndSettle();

      expect(find.text('Team Standup'), findsOneWidget);
      expect(find.text('Alice Bennett'), findsNothing);
    });

    testWidgets('Favourites filter shows only favourited chats',
        (tester) async {
      ChatStore.instance.toggleFavorite('c_bob');
      await pumpTab(tester);
      await tester.tap(find.text('Favourites'));
      await tester.pumpAndSettle();

      expect(find.text('Bob Carter'), findsOneWidget);
      expect(find.text('Alice Bennett'), findsNothing);
    });

    test('isFavorite survives a JSON roundtrip', () {
      final store = ChatStore.instance;
      store.toggleFavorite('c_alice');
      final snapshot = jsonDecode(jsonEncode(store.toJson()))
          as Map<String, dynamic>;
      store.reset();
      store.hydrate(snapshot);
      expect(store.chatById('c_alice')!.isFavorite, isTrue);
      expect(store.chatById('c_bob')!.isFavorite, isFalse);
    });
  });

  group('Pinned messages (multi-pin)', () {
    test('pins several messages and enforces the free limit', () {
      final store = ChatStore.instance;
      store.pinMessage('c_alice', 'm1');
      store.pinMessage('c_alice', 'm2');
      store.pinMessage('c_alice', 'm2b');
      final chat = store.chatById('c_alice')!;
      expect(chat.pinnedMessageIds, ['m1', 'm2', 'm2b']);
      expect(chat.pinnedMessageId, 'm2b'); // latest
      expect(chat.isPinnedMessage('m2'), isTrue);
      // At the free limit (3): non-Pro blocked, Pro not.
      expect(store.canPinMore('c_alice', isPro: false), isFalse);
      expect(store.canPinMore('c_alice', isPro: true), isTrue);
    });

