      // Before this a reply four levels down rendered as a sentence answering
      // nothing, with one line naming its parent and no way to read it.
      FeedStore.instance.resetForTest();
      addTearDown(FeedStore.instance.resetForTest);
      final store = FeedStore.instance;
      final root = store.add('c1', 'the very first thing');
      final mid = store.add('c1', 'a reply in the middle', parentId: root.id);
      final leaf = store.add('c1', 'the deep one', parentId: mid.id);

      await t.pumpWidget(MaterialApp(home: FeedPostScreen(postId: leaf.id)));
      await t.pump();
      await t.pump(const Duration(milliseconds: 300));

      expect(find.text('the deep one'), findsOneWidget);
      expect(find.text('a reply in the middle'), findsOneWidget,
          reason: 'the immediate parent is missing from the thread');
      expect(find.text('the very first thing'), findsOneWidget,
          reason: 'the chain stopped short of the root');
    });

    test('the public thread does the same, root first and loop-proof', () {
      final store = PublicFeedStore.instance;
      addTearDown(store.resetForTest);
      PublicPost mk(String id, {String? replyTo}) => PublicPost(
          id: id,
          authorUsername: 'ada',
          body: id,
          replyTo: replyTo,
          createdAt: DateTime.now());
      PublicFeedStore.debugLoadOverride = () async => [
            mk('root'),
            mk('a', replyTo: 'root'),
            mk('b', replyTo: 'a'),
            mk('self', replyTo: 'self'),
          ];
      return store.load().then((_) {
        expect(store.ancestorsOf('b').map((p) => p.id), ['root', 'a']);
        expect(store.ancestorsOf('root'), isEmpty);
        expect(store.ancestorsOf('self'), isEmpty,
            reason: 'a post that is its own parent must not spin');
        // A parent that never loaded stops the chain rather than faking one.
        expect(store.ancestorsOf('missing'), isEmpty);
      });
    });

    test('a thread knows the conversation above it, and cannot loop', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      final root = store.add('c1', 'the first thing');
      final a = store.add('c1', 'answering that', parentId: root.id);
      final b = store.add('c1', 'answering the answer', parentId: a.id);

      // Root first, so the chain reads top-to-bottom like the screen draws it.
      expect(store.ancestorsOf(b.id).map((p) => p.id), [root.id, a.id]);
      expect(store.ancestorsOf(a.id).map((p) => p.id), [root.id]);
      expect(store.ancestorsOf(root.id), isEmpty);

      // A parent id rides the relay from somebody else's device, so a row
      // pointing at itself is one malformed message away. Unbounded, the walk
      // up would hang the thread screen rather than draw it.
      store.addRemote(FeedPost(
        id: 'loop',
        communityId: 'c1',
        authorName: 'Mallory',
        authorUsername: 'mallory',
        time: DateTime.now(),
        text: 'me again',
        parentId: 'loop',
      ));
      expect(store.ancestorsOf('loop'), isEmpty,
          reason: 'a post that is its own parent must not spin');

      // A mutual pair is the same trap one step further out.
      store.addRemote(FeedPost(
          id: 'p1',
          communityId: 'c1',
          authorName: 'M',
          authorUsername: 'm',
          time: DateTime.now(),
          text: 'a',
          parentId: 'p2'));
      store.addRemote(FeedPost(
          id: 'p2',
          communityId: 'c1',
          authorName: 'M',
          authorUsername: 'm',
          time: DateTime.now(),
          text: 'b',
          parentId: 'p1'));
      final pair = store.ancestorsOf('p1');
      expect(pair.length, lessThanOrEqualTo(FeedStore.maxThreadDepth));
      expect(pair.map((p) => p.id).toSet().length, pair.length,
          reason: 'the chain repeated a post, so it went round the loop');
    });

    test('an alert can be deleted, and a person can be silenced', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      final mine = store.add('c1', 'my original post');
      FeedPost from(String id, String who, {String? parent, String text = ''}) =>
          FeedPost(
              id: id,
              communityId: 'c1',
              authorName: who,
              authorUsername: who.toLowerCase(),
              time: DateTime.now(),
              text: text,
              parentId: parent);

      store.addRemote(from('r1', 'Grace', parent: mine.id, text: 'nice'));
      store.addRemote(from('r2', 'Hana', parent: mine.id, text: 'agreed'));
      expect(store.notifications, hasLength(2));

      // Deleting one leaves the other alone.
      store.dismissNotification('r1');
      expect(store.notifications.map((n) => n.id), ['r2']);

      // Muting is about what happens NEXT: the alert already there stays,
      // because sweeping the list would read as the app deleting history.
      expect(store.toggleNotificationMute('hana'), isTrue);
      expect(store.notificationsMuted('Hana'), isTrue,
          reason: 'case must not decide whether somebody is muted');
      expect(store.notifications, hasLength(1),
          reason: 'muting is not a delete');

      // A new interaction from them raises nothing at all.
      store.addRemote(from('r3', 'Hana', parent: mine.id, text: 'and again'));
      expect(store.notifications.map((n) => n.id), ['r2'],
          reason: 'a muted account still raised an alert');

      // Somebody unmuted still gets through.
      store.addRemote(from('r4', 'Grace', parent: mine.id, text: 'hello'));
      expect(store.notifications.map((n) => n.id), ['r4', 'r2']);

      // Unmuting restores them.
      expect(store.toggleNotificationMute('hana'), isFalse);
      store.addRemote(from('r5', 'Hana', parent: mine.id, text: 'back'));
      expect(store.notifications.first.id, 'r5');

      store.clearNotifications();
      expect(store.notifications, isEmpty);
    });

    test('a silenced person stays silenced across a restart', () async {
      // The mute is written under its own key. A save/load pair that disagreed
      // about that name would lose it on every launch, and the only symptom
      // would be alerts quietly coming back.
      SharedPreferences.setMockInitialValues({});
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      store.toggleNotificationMute('hana');
      // _save() is fire-and-forget; let it reach the (mock) prefs.
      await Future<void>.delayed(Duration.zero);

      store.resetForTest();
      expect(store.notificationsMuted('hana'), isFalse,
          reason: 'resetForTest must not leak a mute into the next test');
      await store.load();
      expect(store.notificationsMuted('hana'), isTrue,
          reason: 'the mute did not survive a restart');
    });

    test('feed notifications fire for replies, mentions, and reposts', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      // 'you' owns this post (default profile has no username → 'you').
      final mine = store.add('c1', 'my original post');

      FeedPost remote(String id, {String? parent, String text = '',
              String? repostOf}) =>
          FeedPost(
              id: id,
              communityId: 'c1',
              authorName: 'Grace',
              authorUsername: 'grace',
              time: DateTime.now(),
              text: text,
              parentId: parent,
              repostOfId: repostOf);

      // A reply to my post notifies me, pointing at the reply's thread.
      store.addRemote(remote('r1', parent: mine.id, text: 'nice one'));
      // A repost of my post notifies me, pointing at the original.
      store.addRemote(
          remote('rp_${mine.id}_by_grace', repostOf: mine.id));
      // An @you mention notifies me.
      store.addRemote(remote('m1', text: 'hey @you look at this'));
      // Someone else's unrelated post does NOT.
      store.addRemote(remote('x1', text: 'just talking to myself'));

      final notes = store.notifications;
      expect(notes, hasLength(3));
      expect(notes.map((n) => n.type).toSet(), {
        FeedNotificationType.reply,
        FeedNotificationType.repost,
        FeedNotificationType.mention,
      });
      expect(
          notes
              .firstWhere((n) => n.type == FeedNotificationType.repost)
              .threadPostId,
          mine.id);
      expect(store.unseenNotificationCount, 3);

      // Dedup: the same event arriving twice doesn't double-count.
      store.addRemote(remote('r1', parent: mine.id, text: 'nice one'));
      expect(store.notifications, hasLength(3));

      // Marking seen clears the badge but keeps the history.
      store.markNotificationsSeen();
      expect(store.unseenNotificationCount, 0);
      expect(store.notifications, hasLength(3));

      // The pure detector never fires on your own echoed post.
      expect(
          FeedStore.notificationFor(mine,
              myUsername: 'you', myPostIds: {mine.id}),
          isNull);
    });

    test('like notifications carry the liker and dedupe', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      final mine = store.add('c1', 'like this');
      expect(store.postById(mine.id)!.likes, 0);

      // Grace likes my post: counter moves and I'm notified.
      store.applyRemoteLike(mine.id,
          liked: true, likerName: 'Grace', likerUsername: 'grace');
      expect(store.postById(mine.id)!.likes, 1);
      final note = store.notifications.first;
      expect(note.type, FeedNotificationType.like);
      expect(note.actorName, 'Grace');
      expect(note.threadPostId, mine.id);

      // A replayed like (mailbox / reconnect) can't double the count.
      store.applyRemoteLike(mine.id,
          liked: true, likerName: 'Grace', likerUsername: 'grace');
      expect(store.postById(mine.id)!.likes, 1);
      expect(store.notifications.where((n) => n.type == FeedNotificationType.like),
          hasLength(1));

      // Unlike takes the count back down.
      store.applyRemoteLike(mine.id,
          liked: false, likerName: 'Grace', likerUsername: 'grace');
      expect(store.postById(mine.id)!.likes, 0);

      // Liking someone else's post notifies no one here.
      final theirs = FeedPost(
          id: 'p_theirs',
          communityId: 'c1',
          authorName: 'Bob',
          authorUsername: 'bob',
          time: DateTime.now(),
          text: 'not mine');
      store.addRemote(theirs);
      final before = store.notifications.length;
      store.applyRemoteLike('p_theirs',
          liked: true, likerName: 'Cara', likerUsername: 'cara');
      expect(store.postById('p_theirs')!.likes, 1);
      expect(store.notifications.length, before); // no self-notification
    });

    test('threads nest, mentions autocomplete, authors resolve', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      final root = store.add('c1', 'root post');
      store.reply(root.id, 'first reply');
      final reply = store.repliesTo(root.id).single;
      // Reply to the reply: it threads under the reply, not the root.
      store.reply(reply.id, 'nested reply');
      expect(store.repliesTo(reply.id).single.text, 'nested reply');
      expect(store.repliesTo(root.id), hasLength(1));
      expect(store.postById(reply.id)!.replies, 1);

      // A reply carries a GIF (or photo data: URI) in the same field a
      // timeline post does, so the cards render it with no extra path.
      store.reply(reply.id, 'with a gif', gifUrl: 'https://g.example/x.gif');
      expect(store.repliesTo(reply.id).last.gifUrl, 'https://g.example/x.gif');

      // Mention prefix extraction from the composer text.
      expect(activeMentionPrefix('hey @gra'), 'gra');
      expect(activeMentionPrefix('hey @'), '');
      expect(activeMentionPrefix('no mention here'), isNull);
      expect(activeMentionPrefix('email a@b already done '), isNull);

      // Candidate matching: prefix, dedupe, never "you", capped at five.
      final known = ['grace', 'Graham', 'grace', 'you', 'bob', 'g1', 'g2',
        'g3', 'g4'];
      expect(mentionMatches('gra', known), ['grace', 'Graham']);
      expect(mentionMatches('g', known), hasLength(5));
      expect(mentionMatches('zz', known), isEmpty);

      // Author names resolve from their posts for the person sheet.
      expect(store.authorNameFor(root.authorUsername), isNotNull);
      expect(store.authorNameFor('nobody'), isNull);
      expect(store.usernamesFor('c1'), isNot(contains('you')));
    });

    test('deleted posts stay deleted through backup replays', () {
      FeedStore.instance.resetForTest();
      final store = FeedStore.instance;
      final post = store.add('c1', 'delete me');
      store.reply(post.id, 'a reply');
      // A backup snapshot taken BEFORE the delete...
      final staleBackup = store.exportPosts();

      store.deletePost(post.id);
      expect(store.postsFor('c1'), isEmpty);

      // ...must not resurrect the post when it replays after the delete —
      // this was the "when I delete post it comes back" bug.
      store.hydratePosts(staleBackup);
      expect(store.postById(post.id), isNull);
      expect(store.postsFor('c1'), isEmpty);
      // Nor can a stale relay copy bring it back.
      store.addRemote(FeedPost(
          id: post.id,
          communityId: 'c1',
          authorName: 'Me',
          authorUsername: 'you',
          time: DateTime.now(),
          text: 'delete me'));
      expect(store.postById(post.id), isNull);

      // Repost slots are the exception: un-repost then re-repost reuses
      // the deterministic id legitimately.
      final keeper = store.add('c1', 'reshare me');
      store.toggleRepost(keeper.id);
      store.toggleRepost(keeper.id); // un-repost (tombstones the slot)
      store.toggleRepost(keeper.id); // re-repost revives it
      final entryId = FeedStore.repostEntryId(
          keeper.id, AppState.profile.value.username);
      expect(store.postById(entryId), isNotNull);
    });

