  group('Channel typing', () {
    setUp(ChannelTypingStore.instance.resetForTest);
    tearDown(ChannelTypingStore.instance.resetForTest);

    test('the label reads naturally as more people join in', () {
      final typing = ChannelTypingStore.instance;
      expect(typing.labelFor('ch1'), isNull);
      typing.noteRemote(channelId: 'ch1', digits: '1', name: 'Ada');
      expect(typing.labelFor('ch1'), 'Ada is typing…');
      typing.noteRemote(channelId: 'ch1', digits: '2', name: 'Grace');
      expect(typing.labelFor('ch1'), 'Ada and Grace are typing…');
      typing.noteRemote(channelId: 'ch1', digits: '3', name: 'Zoe');
      expect(typing.labelFor('ch1'), '3 people are typing…');
      // Another channel is unaffected.
      expect(typing.labelFor('ch2'), isNull);
    });

    test('typing stops showing on its own', () {
      final typing = ChannelTypingStore.instance;
      typing.noteRemote(channelId: 'ch1', digits: '1', name: 'Ada');
      expect(typing.labelFor('ch1'), isNotNull);
      typing.expireNow(
          DateTime.now().add(ChannelTypingStore.linger * 2));
      expect(typing.labelFor('ch1'), isNull);
    });

    test('local pings are throttled, and sending resets the throttle', () {
      final typing = ChannelTypingStore.instance;
      var pings = 0;
      typing.onTyping = (_, __) => pings++;
      typing.noteLocalTyping('c1', 'ch1');
      typing.noteLocalTyping('c1', 'ch1');
      typing.noteLocalTyping('c1', 'ch1');
      expect(pings, 1, reason: 'a keystroke each would flood the bus');

      typing.clearLocal('ch1');
      typing.noteLocalTyping('c1', 'ch1');
      expect(pings, 2);
    });

    test('a nameless ping still reads as somebody', () {
      final typing = ChannelTypingStore.instance;
      typing.noteRemote(channelId: 'ch1', digits: '1', name: '');
      expect(typing.labelFor('ch1'), 'Someone is typing…');
      // An empty sender is ignored entirely — it can't be attributed.
      typing.noteRemote(channelId: 'ch2', digits: '', name: 'Ghost');
      expect(typing.labelFor('ch2'), isNull);
    });
  });

  group('Subscription entitlement', () {
    // Apple bills an auto-renewable subscription monthly whether or not the
    // app is ever opened, so a local "+30 days" would drift the moment a
    // renewal, cancellation, or refund happened elsewhere. The server's answer
    // is what counts; these cover the client half of adopting it.
    setUp(() => SharedPreferences.setMockInitialValues({}));

    test('the server can grant, extend, and revoke a plan', () async {
      final storage = StorageStore.instance;
      addTearDown(storage.resetForTest);
      storage.resetForTest();
      expect(storage.isPaid, isFalse);
      expect(storage.activeGb, StorageStore.freeGb);

      final renewal = DateTime.now().add(const Duration(days: 30));
      await storage.applyServerEntitlement(
          active: true, gb: 50, expiresAt: renewal);
      expect(storage.isPaid, isTrue);
      expect(storage.activeGb, 50);

      // A renewal moves the date out without another purchase.
      final next = DateTime.now().add(const Duration(days: 60));
      await storage.applyServerEntitlement(
          active: true, gb: 50, expiresAt: next);
      expect(storage.daysLeft, greaterThan(30));

      // A refund ends it immediately, even mid-period.
      await storage.applyServerEntitlement(active: false, gb: 0);
      expect(storage.isPaid, isFalse);
      expect(storage.activeGb, StorageStore.freeGb);
    });

    test('an expiry already past leaves the account on the free tier',
        () async {
      final storage = StorageStore.instance;
      addTearDown(storage.resetForTest);
      storage.resetForTest();
      await storage.applyServerEntitlement(
          active: true,
          gb: 30,
          expiresAt: DateTime.now().subtract(const Duration(days: 1)));
      expect(storage.isPaid, isFalse);
      expect(storage.activeGb, StorageStore.freeGb);
      // Still remembered, so the screen offers "renew" rather than "subscribe".
      expect(storage.selectedGb, 30);
    });

    test('entitlement JSON survives the round trip', () {
      final e = Entitlement.fromJson(const {
        'active': true,
        'gb': 20,
        'expiresAt': '2030-01-01T00:00:00Z',
        'productId': 'com.okaymessaging.storage.gb20.monthly',
      });
      expect(e.active, isTrue);
      expect(e.gb, 20);
      expect(e.expiresAt!.toUtc().year, 2030);
      expect(Entitlement.fromJson(const {}).active, isFalse);
      expect(Entitlement.fromJson(const {'active': true, 'gb': 10}).expiresAt,
          isNull);
    });

    test('every purchasable size has a product id the server can price back',
        () {
      // gbForProduct() in _shared/iap.ts parses the size back out of the id.
      // If the two ever disagree a purchase would validate to 0 GB.
      final pattern = RegExp(r'\.storage\.gb(\d+)\.monthly$');
      for (final gb in StorageStore.sizes) {
        final id = StorePurchases.storageProductId(gb);
        final m = pattern.firstMatch(id);
        expect(m, isNotNull, reason: '$id is not in the form the server parses');
        expect(int.parse(m!.group(1)!), gb);
      }
      // Tips must NOT parse as storage — they grant no entitlement.
      for (final tip in StorePurchases.tipProducts) {
        expect(pattern.hasMatch(tip.id), isFalse);
      }
      final intent = File('docs/edge_functions_paste/payments-create-intent.ts')
          .readAsStringSync();
      expect(intent.contains('stripeAccount:'), isTrue,
          reason: 'transfers must be direct charges on the recipient account');
      expect(intent.contains('transfer_data'), isFalse,
          reason: 'transfer_data would route the money through the platform');
    });

    test('a business description ships with a URL Stripe will accept', () {
      // business_profile.url is required and a description does not reliably
      // stand in for it — the account looped on that exact requirement. An
      // individual has no website, so the platform's page is the default.
      final src = File('docs/edge_functions_paste/payments-connect-fields.ts')
          .readAsStringSync();
      expect(src.contains('url?: string'), isTrue,
          reason: 'the submission must be able to carry a URL');
      expect(src.contains('"SITE_URL"'), isTrue,
          reason: 'a configured site wins');
      expect(src.contains('/functions/v1/pages'), isTrue,
          reason: 'else the project\'s own landing page stands in');
    });

    test('the debit card form validates before Stripe has to', () {
      // Stripe's own Visa-debit test number is Luhn-valid; a transposed
      // digit is not — caught on the device, with the field highlighted.
      expect(ConnectValidation.cardNumber('4000 0566 5566 5556'), isNull);
      expect(ConnectValidation.cardNumber('4000 0566 5566 5557'), isNotNull);
      expect(ConnectValidation.cardNumber('123'), isNotNull);
      expect(ConnectValidation.cardCvc('123'), isNull);
      expect(ConnectValidation.cardCvc('12345'), isNotNull);
      final now = DateTime(2026, 8);
      expect(ConnectValidation.cardExpiry(12, 30, now: now), isNull,
          reason: 'two-digit years are how cards print them');
      expect(ConnectValidation.cardExpiry(7, 2026, now: now), isNotNull,
          reason: 'last month is expired');
      expect(ConnectValidation.cardExpiry(8, 2026, now: now), isNull,
          reason: 'a card expiring this month still works');
      expect(ConnectValidation.cardExpiry(13, 2027, now: now), isNotNull);

      // "Add a debit card" opens the card form now — it used to open
      // Payment controls, which has no card in it anywhere.
      final wallet =
          File('lib/screens/wallet_screen.dart').readAsStringSync();
      expect(wallet.contains('AddDebitCardScreen('), isTrue);
      // And the server accepts only a token, never a number.
      final fn = File('docs/edge_functions_paste/payments-connect-fields.ts')
          .readAsStringSync();
      expect(fn.contains('cardToken'), isTrue);
      expect(fn.contains('card_must_be_tokenised'), isTrue);
    });

    test('a fresh debit card waits, and a churned one is locked', () {
      // The takeover safeguard: the server's verdict rides the quote and
      // the client's instant-button gate honours it. The policy arithmetic
      // itself is executed by card_policy_test.mjs in check_functions.
      Map<String, dynamic> base() => {
            'onboarded': true,
            'chargesEnabled': true,
            'payoutsEnabled': true,
            'hasDebitCard': true,
            'instantAvailable': 5000,
            'country': 'CA',
          };
      final held = WalletStatus.fromJson(
          {...base(), 'cardHoldBusinessDaysLeft': 3});
      expect(held.cardHoldDaysLeft, 3);
      expect(held.canCashOutInstantly, isFalse,
          reason: 'a held card must not offer the instant button');
      final locked =
          WalletStatus.fromJson({...base(), 'cardLocked': true});
      expect(locked.canCashOutInstantly, isFalse);
      // An older deployment that says nothing invents no hold.
      expect(WalletStatus.fromJson(base()).canCashOutInstantly, isTrue);

      // Both refusals have words, and both paste copies enforce the rules —
      // a hold only the app knows about is a hold a curl request skips.
      expect(const PayoutOutcome(ok: false, error: 'card_hold').message,
          contains('7 business days'));
      expect(
          const PayoutOutcome(ok: false, error: 'card_changes_locked')
              .message,
          contains('30 days'));
      final payout = File('docs/edge_functions_paste/payments-payout.ts')
          .readAsStringSync();
      expect(payout.contains('card_hold'), isTrue);
      expect(payout.contains('card_changes_locked'), isTrue);
      final fields =
          File('docs/edge_functions_paste/payments-connect-fields.ts')
              .readAsStringSync();
      expect(fields.contains('payment_card_events'), isTrue);
      expect(fields.contains('card_changes_locked'), isTrue);

      // And the card is judged by name BEFORE it is attached: the same
      // rules the sending card passes (judgeCard — executed by
      // cardholder_test.mjs), against the name Stripe read off the ID.
      expect(fields.contains('judgeCard'), isTrue,
          reason: 'the payout card must be name-checked before attach');
      expect(fields.contains('card_name_mismatch'), isTrue);
      expect(fields.contains('card_prepaid'), isTrue);
      final screen = File('lib/screens/add_debit_card_screen.dart')
          .readAsStringSync();
      expect(screen.contains("'Name on the card'"), isTrue,
          reason: 'without the field there is no name to check');
      expect(screen.contains('card_name_mismatch'), isTrue,
          reason: 'the refusal needs words on the screen it lands on');
    });

    test('a changed direct deposit waits 7 business days too', () {
      // The other half of the drain: redirect where the money lands, wait
      // for the schedule. A change pauses automatic payouts, refuses manual
      // ones, and the wallet says why with a number.
      final s = WalletStatus.fromJson(const {
        'onboarded': true,
        'chargesEnabled': true,
        'payoutsEnabled': true,
        'bankLast4': '6789',
        'bankHoldBusinessDaysLeft': 4,
      });
      expect(s.bankLast4, '6789');
      expect(s.bankHoldDaysLeft, 4);
      expect(const PayoutOutcome(ok: false, error: 'bank_hold').message,
          contains('7 business days'));

      // The paste copies enforce it — the pause, the hold, the churn lock,
      // the restore — or a curl request walks around all of it.
      final fields =
          File('docs/edge_functions_paste/payments-connect-fields.ts')
              .readAsStringSync();
      expect(fields.contains('"bank"'), isTrue,
          reason: 'bank changes must be recorded in the ledger');
      expect(fields.contains('bank_changes_locked'), isTrue);
      expect(fields.contains('interval: "manual"'), isTrue,
          reason: 'a change must pause the automatic schedule');
      final payout = File('docs/edge_functions_paste/payments-payout.ts')
          .readAsStringSync();
      expect(payout.contains('bank_hold'), isTrue);
      final status = File('docs/edge_functions_paste/payments-status.ts')
          .readAsStringSync();
      expect(status.contains('bankHoldBusinessDaysLeft'), isTrue,
          reason: 'the wallet reads its verdicts from payments-status');
      expect(status.contains('cardHoldBusinessDaysLeft'), isTrue,
          reason: 'the card verdicts ride the same status payload');
      expect(status.contains('interval: "daily"'), isTrue,
          reason: 'the pause must end when the hold does');
      // A first bank account is onboarding, not a change: only a CHANGE is
      // recorded and held, so signing up never starts frozen.
      expect(fields.contains('const isChange = oldBanks.length > 0'), isTrue);
    });

    test('a no-progress onboarding round says so instead of redrawing', () {
      // Same asks back, no errors, not complete: the silent loop — worded.
      final stalled = ConnectRequirements.stalledMessage(
        before: {'business_profile.product_description',
            'individual.relationship.title'},
        after: {'business_profile.product_description',
            'individual.relationship.title'},
        complete: false,
        hasErrors: false,
      );
      expect(stalled, contains('payments-connect-fields'));
      // Any real movement is not a stall: fewer asks, new asks, done, or an
      // error that already speaks for itself.
      expect(
          ConnectRequirements.stalledMessage(
              before: {'a', 'b'},
              after: {'a'},
              complete: false,
              hasErrors: false),
          isNull);
      expect(
          ConnectRequirements.stalledMessage(
              before: {'a'},
              after: {'a', 'external_account'},
              complete: false,
              hasErrors: false),
          isNull);
      expect(
          ConnectRequirements.stalledMessage(
              before: {'a'}, after: {}, complete: true, hasErrors: false),
          isNull);
      expect(
          ConnectRequirements.stalledMessage(
              before: {'a'}, after: {'a'}, complete: false, hasErrors: true),
          isNull);
    });

    test('the business section always ships an mcc with the description', () {
      // Stripe wants business_profile.mcc and no form can ask a person for
      // a merchant category code; without one sent alongside, the business
      // section came back after every submit, forever.
      final src =
          File('lib/screens/native_onboarding_screen.dart').readAsStringSync();
      final collapsed = src.replaceAll(RegExp(r'\s+'), ' ');
      expect(collapsed.contains("'mcc': '4829'"), isTrue,
          reason: 'the description alone leaves business_profile.mcc due');
      expect(
          collapsed.contains(
              "if (needs.contains(ConnectField.business)) ...{"),
          isTrue,
          reason: 'the mcc must ride the same condition as the description');
    });

    test('the tips store check names the broken link, not a generic failure',
        () {
      // No store at all (web, signed-out device).
      expect(
          StorePurchases.tipsCheckVerdict(const StoreQueryResult(
              storeReachable: false, notOffered: ['a'])),
          contains('isn\'t reachable'));
      // Everything on sale: the products are fine, say so.
      expect(
          StorePurchases.tipsCheckVerdict(const StoreQueryResult(
              storeReachable: true, onSale: {'a': '\$2.99'})),
          contains('on sale'));
      // Nothing on sale points at the account — the Paid Apps agreement is
      // the first thing to check, and the verdict must say it.
      final none = StorePurchases.tipsCheckVerdict(const StoreQueryResult(
          storeReachable: true, notOffered: ['a', 'b']));
      expect(none, contains('Paid Applications'));
      expect(none, contains('Ready to Submit'));
      // A partial answer is an ID mismatch, and the verdict names the ids.
      expect(
          StorePurchases.tipsCheckVerdict(const StoreQueryResult(
              storeReachable: true,
              onSale: {'a': '\$2.99'},
              notOffered: ['com.okaymessaging.tip.snack'])),
          contains('com.okaymessaging.tip.snack'));
    });
  });

  group('Sync and replay safety', () {
    setUp(() => SharedPreferences.setMockInitialValues({}));

    test('a like replayed after a restart is still counted once', () async {
      final store = FeedStore.instance;
      store.resetForTest();
      final post = store.add('c1', 'likeable');
      store.applyRemoteLike(post.id,
          liked: true, likerName: 'Grace', likerUsername: 'grace');
      expect(store.postById(post.id)!.likes, 1);
      await Future<void>.delayed(const Duration(milliseconds: 50));

      // Restart: memory cleared, state reloaded from disk.
      store.resetForTest();
      await store.load();
      expect(store.postById(post.id)!.likes, 1);

      // The same mailbox row comes back because its DELETE never landed.
      store.applyRemoteLike(post.id,
          liked: true, likerName: 'Grace', likerUsername: 'grace');
      expect(store.postById(post.id)!.likes, 1,
          reason: 'the who-liked-it guard has to survive the restart');
    });

    test('sparks tally money once each, survive replays, and notify the author',
        () async {
      final store = FeedStore.instance;
      store.resetForTest();
      // My own post ('you'), so the incoming spark raises an alert.
      final post = store.add('c1', 'sparkable');
      final notesBefore = store.notifications.length;

      store.applyRemoteSpark(post.id,
          sparkId: 'z1', cents: 2100, sparkerName: 'Grace',
          sparkerUsername: 'grace');
      var p = store.postById(post.id)!;
      expect(p.sparks, 1);
      expect(p.sparkCents, 2100);
      expect(store.notifications.length, notesBefore + 1);
      expect(store.notifications.first.preview, '\$21.00');

      // A replayed event (mailbox row whose delete failed) counts nothing…
      store.applyRemoteSpark(post.id,
          sparkId: 'z1', cents: 2100, sparkerName: 'Grace',
          sparkerUsername: 'grace');
      expect(store.postById(post.id)!.sparkCents, 2100);
      // …but the same person sparking AGAIN is a new spark, not a replay.
      store.applyRemoteSpark(post.id,
          sparkId: 'z2', cents: 21, sparkerName: 'Grace',
          sparkerUsername: 'grace');
      expect(store.postById(post.id)!.sparks, 2);
      expect(store.postById(post.id)!.sparkCents, 2121);
      await Future<void>.delayed(const Duration(milliseconds: 50));

      // The guard outlives a restart, like the like/vote guards beside it.
      store.resetForTest();
      await store.load();
      store.applyRemoteSpark(post.id,
          sparkId: 'z2', cents: 21, sparkerName: 'Grace',
          sparkerUsername: 'grace');
      expect(store.postById(post.id)!.sparkCents, 2121);

      // My own spark: counted locally and flagged, only after payment.
      store.spark(post.id, 500);
      p = store.postById(post.id)!;
      expect(p.sparked, isTrue);
      expect(p.sparkCents, 2621);

      // The fields (and the author's digits that make sparking addressable)
      // survive the JSON round-trip; legacy posts default to none.
      final back = FeedPost.fromJson(FeedPost(
        id: 'p',
        communityId: 'c1',
        authorName: 'A',
        authorUsername: 'a',
        authorPhone: '15550142',
        time: DateTime(2024),
        text: 't',
        sparks: 3,
        sparkCents: 442,
      ).toJson());
      expect(back.authorPhone, '15550142');
      expect(back.sparks, 3);
      expect(back.sparkCents, 442);
      expect(
          FeedPost.fromJson({
            'id': 'old',
            'communityId': 'c1',
            'time': DateTime(2024).toIso8601String(),
            'text': 'legacy'
          }).sparks,
          0);
      // No digits → no bolt, and your own post is never sparkable.
      expect(canSparkPost(back.copyWith()), isFalse,
          reason: 'payments are not configured in a test build');
      expect(
          canSparkPost(FeedPost(
              id: 'p2',
              communityId: 'c1',
              authorName: 'Me',
              authorUsername: 'you',
              authorPhone: '1234567',
              time: DateTime(2024),
              text: 'mine')),
          isFalse);
    });

    test('muted words and hidden reposts shape both timelines', () async {
      addTearDown(FeedPrefs.instance.resetForTest);
      // The matcher is pure: case-insensitive, and a phrase is a phrase.
      expect(FeedPrefs.hidesText('Big CRYPTO news', ['crypto']), isTrue);
      expect(FeedPrefs.hidesText('cryptic', ['crypto']), isFalse);
      expect(
          FeedPrefs.hidesText('great crypto tips here', ['crypto tips']),
          isTrue);
      expect(FeedPrefs.hidesText('crypto and tips', ['crypto tips']), isFalse);
      expect(FeedPrefs.hidesText('anything', []), isFalse);

      // Server feed: a muted word hides the post; unmuting brings it back.
      final store = FeedStore.instance;
      store.resetForTest();
      store.add('c1', 'the weather is lovely');
      store.add('c1', 'one weird crypto trick');
      await FeedPrefs.instance.muteWord('crypto');
      expect(FeedPrefs.instance.mutedWords, ['crypto']);
      expect(store.postsFor('c1').map((p) => p.text),
          ['the weather is lovely']);
      await FeedPrefs.instance.unmuteWord('crypto');
      expect(store.postsFor('c1'), hasLength(2));
      // Blanks and duplicates don't grow the list.
      expect(await FeedPrefs.instance.muteWord('  '), isFalse);
      await FeedPrefs.instance.muteWord('Spam');
      expect(await FeedPrefs.instance.muteWord('spam'), isFalse);
      await FeedPrefs.instance.unmuteWord('spam');

      // Hide reposts: the repost entry goes, the original stays.
      final original = store.add('c1', 'worth repeating');
      store.toggleRepost(original.id);
      expect(store.postsFor('c1').where((p) => p.repostOfId != null),
          hasLength(1));
      await FeedPrefs.instance.setHideReposts(true);
      expect(store.postsFor('c1').where((p) => p.repostOfId != null),
          isEmpty);
      expect(store.postsFor('c1').any((p) => p.id == original.id), isTrue);

      // The public timeline follows the same rules.
      PublicFeedStore.debugLoadOverride = () async => [
            PublicPost(
                id: 'p1',
                authorUsername: 'ada',
                authorName: 'Ada',
                body: 'hello world',
                createdAt: DateTime.now()),
            PublicPost(
                id: 'p2',
                authorUsername: 'ada',
                authorName: 'Ada',
                body: 'crypto giveaway',
                createdAt: DateTime.now()),
          ];
      addTearDown(() => PublicFeedStore.debugLoadOverride = null);
      await PublicFeedStore.instance.load();
      await FeedPrefs.instance.muteWord('crypto');
      expect(PublicFeedStore.instance.posts.map((p) => p.id), ['p1']);
    });

    test('the Spark practice bot exists only inside payments test mode', () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(() => PaymentService.instance.testMode.value = false);

      PaymentService.instance.testMode.value = true;
      final bot = store.addSparkBot('c1');
      expect(bot.authorUsername, 'sparkbot');
      expect(store.postsFor('c1').single.id, bot.id);
      // Its post is sparkable: another author, digits present, and test
      // mode counts as configured.
      expect(canSparkPost(bot), isTrue);
      // Summoning again refreshes rather than duplicates.
      store.addSparkBot('c1');
      expect(store.postsFor('c1'), hasLength(1));

      // Sparking it moves the tally and stays on this device (no relay is
      // initialized here — a broadcast attempt would throw).
      store.spark(bot.id, 100);
      expect(store.postById(bot.id)!.sparkCents, 100);
      expect(store.postById(bot.id)!.sparked, isTrue);

      // Test mode off: the bot vanishes from the timeline — a practice
      // fixture must never stand in front of a real feed — and never
      // reaches a joiner's backfill either way.
      PaymentService.instance.testMode.value = false;
      expect(store.postsFor('c1'), isEmpty);
      expect(store.backfillFor('c1'), isEmpty);
    });

    test('a poll vote replayed after a restart is still counted once',
        () async {
      final store = FeedStore.instance;
      store.resetForTest();
      final poll = store.addPoll('c1', 'Q?', ['A', 'B'])!;
      store.applyRemoteVote(poll.id,
          option: 0, previous: -1, voterUsername: 'grace');
      await Future<void>.delayed(const Duration(milliseconds: 50));

      store.resetForTest();
      await store.load();
      expect(store.postById(poll.id)!.pollTotalVotes, 1);
      store.applyRemoteVote(poll.id,
          option: 0, previous: -1, voterUsername: 'grace');
      expect(store.postById(poll.id)!.pollTotalVotes, 1);
    });

    test('a deleted post stays deleted across a restart', () async {
      final store = FeedStore.instance;
      store.resetForTest();
      final post = store.add('c1', 'delete me');
      store.deletePost(post.id);
      await Future<void>.delayed(const Duration(milliseconds: 50));

      store.resetForTest();
      await store.load();
      store.addRemote(post); // a stale relay copy replays it
      expect(store.postById(post.id), isNull);
    });

    test('restoring an older blob never drops what is only on the device',
        () {
      // Every automatic restore merges: the blob is a snapshot from some
      // earlier moment, and pull-to-refresh runs one on every screen.
      final feed = FeedStore.instance;
      feed.resetForTest();
      final old = feed.add('c1', 'already backed up');
      final feedBlob = feed.exportPosts();
      final fresh = feed.add('c1', 'posted while offline');
      feed.hydratePosts(feedBlob);
      expect(feed.postById(old.id), isNotNull);
      expect(feed.postById(fresh.id), isNotNull);

      CommunityStore.instance.resetForTest();
      final oldServer = CommunityStore.instance.createCommunity('Old Guild');
      final serverBlob = CommunityStore.instance.toJsonList();
      final newServer = CommunityStore.instance.createCommunity('New Guild');
      CommunityStore.instance.hydrate(serverBlob);
      final serverIds = {
        for (final c in CommunityStore.instance.communities) c.id
      };
      expect(serverIds, containsAll([oldServer.id, newServer.id]));

      SavedPlacesStore.instance.resetForTest();
      SavedPlacesStore.instance.toggle(const SavedPlace('Old', 1, 1));
      final placeBlob = SavedPlacesStore.instance.exportPlaces();
      SavedPlacesStore.instance.toggle(const SavedPlace('New', 2, 2));
      SavedPlacesStore.instance.hydratePlaces(placeBlob);
      expect({for (final p in SavedPlacesStore.instance.places) p.name},
          containsAll(['Old', 'New']));

      FollowStore.instance.setAll(const ['alreadyfollowed']);
      final followBlob = FollowStore.instance.following.toList();
      FollowStore.instance.toggle('justfollowed');
      FollowStore.instance.mergeAll(followBlob);
      expect(FollowStore.instance.following,
          containsAll(['alreadyfollowed', 'justfollowed']));
    });

    test('a deleted message stays deleted when the mailbox replays it', () {
      AppState.messagesFromContactsOnly.value = false;
      final store = ChatStore.instance;
      store.reset();
      const peer = '+1 555 010 9999';
      store.upsert(const Chat(
        id: 'chat_$peer',
        contact: AppUser(
            id: peer, name: 'Peer', avatarColor: '#111111', phone: peer),
        messages: [],
      ));
      final envelope = <String, dynamic>{
        'id': 'm_replay_1',
        'from': peer,
        'ts': DateTime.now().toUtc().toIso8601String(),
        'text': 'hello there',
      };
      expect(
          RelayService.applyIncoming(envelope, myPhone: '+1 555 010 0000'),
          isTrue);

      store.deleteMessage('chat_$peer', 'm_replay_1');
      expect(store.chatById('chat_$peer')!.messages, isEmpty);

      // The mailbox row's DELETE never landed, so the envelope comes back.
      expect(
          RelayService.applyIncoming(envelope, myPhone: '+1 555 010 0000'),
          isFalse);
      expect(store.chatById('chat_$peer')!.messages, isEmpty);
    });

    test('a deleted conversation does not rebuild itself from the mailbox',
        () {
      AppState.messagesFromContactsOnly.value = false;
      final store = ChatStore.instance;
      store.reset();
      const peer = '+1 555 010 8888';
      store.upsert(const Chat(
        id: 'chat_$peer',
        contact: AppUser(
            id: peer, name: 'Peer2', avatarColor: '#111111', phone: peer),
        messages: [],
      ));
      final envelope = <String, dynamic>{
        'id': 'm_replay_2',
        'from': peer,
        'ts': DateTime.now().toUtc().toIso8601String(),
        'text': 'hi',
      };
      RelayService.applyIncoming(envelope, myPhone: '+1 555 010 0000');
      store.deleteChat('chat_$peer');
      RelayService.applyIncoming(envelope, myPhone: '+1 555 010 0000');
      expect(store.chatById('chat_$peer'), isNull);
    });

    test('delete tombstones survive a save and reload', () {
      final store = ChatStore.instance;
      store.reset();
      final chatId = store.chats.first.id;
      final messageId = store.chatById(chatId)!.messages.first.id;
      store.deleteMessage(chatId, messageId);
      final snapshot = store.toJson();

      store.reset();
      expect(store.isMessageDeleted(messageId), isFalse);
      store.hydrate(snapshot);
      expect(store.isMessageDeleted(messageId), isTrue);
    });

    test('a deleted channel message stays deleted when the bus replays it',
        () {
      final store = CommunityStore.instance;
      store.resetForTest();
      final community = store.createCommunity('Guild');
      final channel = store.byId(community.id)!.channels.first;
      final message = Message(
          id: 'cm_replay', text: 'hi', time: DateTime.now(), isMe: false);
      Channel current() => store
          .byId(community.id)!
          .channels
          .firstWhere((c) => c.id == channel.id);

      store.addRemoteChannelMessage(community.id, channel.id, message);
      expect(current().messages.any((m) => m.id == 'cm_replay'), isTrue);

      store.deleteChannelMessage(community.id, channel.id, 'cm_replay');
      expect(current().messages.any((m) => m.id == 'cm_replay'), isFalse);

      store.addRemoteChannelMessage(community.id, channel.id, message);
      expect(current().messages.any((m) => m.id == 'cm_replay'), isFalse,
          reason: 'a queued copy must not undo the delete');
    });

    test('clearAll is how a restore starts from an empty device', () {
      CommunityStore.instance.resetForTest();
      expect(CommunityStore.instance.communities, isNotEmpty);
      CommunityStore.instance.clearAll();
      expect(CommunityStore.instance.communities, isEmpty);
    });
  });

  group('Screening a public post', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      PublicFeedStore.instance.resetForTest();
    });
    tearDown(() {
      PublicFeedStore.debugScreenOverride = null;
      PublicFeedStore.debugPostOverride = null;
    });

    test('a blocked post never reaches the server, and says why', () async {
      PublicFeedStore.debugScreenOverride = (_) async => {
            'verdict': 'block',
            'category': 'harassment',
            'reason': 'That names a private individual.',
          };
      var inserted = false;
      PublicFeedStore.debugPostOverride = (_) async => inserted = true;

      await expectLater(
        PublicFeedStore.instance.post('...'),
        throwsA(isA<PublicFeedError>().having((e) => e.reason, 'reason',
            'That names a private individual.')),
      );
      expect(inserted, isFalse,
          reason: 'the screen runs before anything is written');
    });

    test('screening that fails lets the post through', () async {
      // FAILS OPEN ON PURPOSE. No API key, no network, function not deployed —
      // none of those are somebody's fault, and none of them should cost them
      // their post. The override returning null is what every one of those
      // paths produces.
      PublicFeedStore.debugScreenOverride = (_) async => null;
      var inserted = false;
      PublicFeedStore.debugPostOverride = (_) async => inserted = true;

      await PublicFeedStore.instance.post('an ordinary post');
      expect(inserted, isTrue);
    });

    test('a block with no explanation still gets one', () async {
      // The reason is shown to the person whose post was stopped. A blank one
      // is a door with no sign on it.
      PublicFeedStore.debugScreenOverride =
          (_) async => {'verdict': 'block', 'reason': '  '};
      PublicFeedStore.debugPostOverride = (_) async {};
      await expectLater(
        PublicFeedStore.instance.post('...'),
        throwsA(isA<PublicFeedError>()
            .having((e) => e.reason, 'reason', isNotEmpty)),
      );
    });

    test('a flag is not a block — the post goes up', () async {
      // Only "block" stops anything. A flag means a moderator should look,
      // which happens in their queue, not in the poster's face.
      PublicFeedStore.debugScreenOverride =
          (_) async => {'verdict': 'flag', 'reason': 'Might be spam.'};
      var inserted = false;
      PublicFeedStore.debugPostOverride = (_) async => inserted = true;
      await PublicFeedStore.instance.post('borderline');
      expect(inserted, isTrue);
    });

    test('the screen sees the post before the image is uploaded', () async {
      // A blocked post must leave nothing behind in the bucket.
      var uploaded = false;
      PublicFeedStore.debugUploadOverride = (id, bytes) async {
        uploaded = true;
        return 'x/$id.jpg';
      };
      addTearDown(() => PublicFeedStore.debugUploadOverride = null);
      PublicFeedStore.debugScreenOverride =
          (_) async => {'verdict': 'block', 'reason': 'No.'};
      PublicFeedStore.debugPostOverride = (_) async {};

      await expectLater(
        PublicFeedStore.instance
            .post('...', image: Uint8List.fromList([1, 2, 3])),
        throwsA(isA<PublicFeedError>()),
      );
      expect(uploaded, isFalse,
          reason: 'no orphaned object in the bucket for a post that never ran');
    });
  });

  group('A chat is a chat', () {
    // WHAT WENT WRONG. The bottom bar and sidebar were lifted above every
    // route so no screen would be a dead end. On a phone that put the tab bar
    // inside conversations — which no messenger does, because the tabs belong
    // to the list of chats, not to a chat — and the overlay's loose
    // constraints threw the composer to the top of the screen with the
    // keyboard up. Reverted; these hold the shape it went back to.

    Future<void> openChat(WidgetTester t) async {
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
      await t.tap(find.text('Bob Carter'));
      await t.pumpAndSettle();
    }

    testWidgets('the bottom bar fits the narrowest phone', (t) async {
      // It overflowed by 9 points at 390 — the width of every iPhone from the
      // SE to the 15 — and by more at 320. The suite runs at 800 wide, so
      // nothing said so until a screenshot from a real phone did.
      for (final width in [320.0, 375.0, 390.0, 430.0]) {
        t.view.physicalSize = Size(width, 844);
        t.view.devicePixelRatio = 1.0;
        await t.pumpWidget(const OkayMessagingApp());
        await t.pumpAndSettle();
        final failure = t.takeException();
        expect(failure, isNull, reason: 'the bar overflows at $width: $failure');
        // NOT OVERFLOWING IS NOT ENOUGH. The first fix for the overflow gave
        // every pill an equal fifth of the row, which stopped the overflow and
        // squeezed the selected pill's label down to a single letter — "C" for
        // Chats. A bar that fits and cannot be read is not fixed.
        final label = t.renderObject<RenderBox>(find.text('Chats'));
        expect(label.size.width, greaterThan(30),
            reason: 'the selected label is squeezed at $width');
      }
      addTearDown(t.view.resetPhysicalSize);
    });

    testWidgets('every tab lays out on every phone', (t) async {
      // The suite runs at 800x600. Every layout bug that reached a real phone
      // — the bar overflowing, the composer at the top — was invisible here
      // for exactly that reason. This walks the five destinations at the four
      // widths iPhones actually come in.
      for (final width in [320.0, 375.0, 390.0, 430.0]) {
        t.view.physicalSize = Size(width, 844);
        t.view.devicePixelRatio = 1.0;
        await t.pumpWidget(const OkayMessagingApp());
        await t.pumpAndSettle();
        for (final (i, icon) in const [
          (0, Icons.chat_bubble_outline),
          (1, Icons.groups_outlined),
          (2, Icons.call_outlined),
          (3, Icons.notifications_none),
          (4, Icons.person_outline),
        ]) {
          final pill = find.byIcon(icon);
          if (pill.evaluate().isEmpty) continue; // already the selected one
          await t.tap(pill);
          await t.pumpAndSettle();
          final failure = t.takeException();
          expect(failure, isNull,
              reason: 'tab $i does not lay out at $width: $failure');
        }
      }
      addTearDown(t.view.resetPhysicalSize);
    });

    testWidgets('bookmarks and muted accounts are reachable from Settings',
        (t) async {
      // They came off the newsfeed's bar, then off the sidebar. Settings is
      // the third home and has to actually work: bookmarks nobody can open
      // are notes nobody reads, and a muted list nobody can reach is a mute
      // nobody can undo.
      SharedPreferences.setMockInitialValues({});
      final prevProfile = AppState.profile.value;
      addTearDown(() => AppState.profile.value = prevProfile);
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Me', avatarColor: '#000000', username: 'me');

      for (final (tile, screen) in [
        ('Bookmarks', BookmarksScreen),
        ('Muted accounts', MutedAccountsScreen),
      ]) {
        // Keyed per tile: without it the second pumpWidget reuses the same
        // element tree and the route pushed by the first iteration is still
        // on top, absorbing the tap.
        await t.pumpWidget(MaterialApp(
            key: ValueKey(tile), home: const SettingsScreen()));
        // pump, not pumpAndSettle: the settings hub keeps rebuilding, so a
        // settle never arrives.
        await t.pump();
        expect(find.text(tile), findsOneWidget,
            reason: '$tile is not on the Settings screen');
        // Being in the tree is not being tappable: the second of these sits
        // below the fold on the default test surface.
        await t.ensureVisible(find.text(tile));
        await t.pump();
        await t.tap(find.text(tile));
        await t.pump();
        await t.pump(const Duration(milliseconds: 400));
        expect(find.byType(screen), findsOneWidget,
            reason: '$tile does not open from Settings');
      }
    });

    testWidgets('the drawer destinations lay out, and can be left', (t) async {
      // Everything the sidebar can reach, at the narrowest phone. Each one is
      // opened, checked for a way back, and left again — a screen you can
      // reach and not leave is the bug the whole shell detour was chasing.
      t.view.physicalSize = const Size(320, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);

      for (final tile in [
        'Newsfeed',
        'Maps',
        'Marketplace',
        // Renamed from "Send nearby". Listed here so the rename is checked
        // where it matters — the row somebody actually taps.
        'Okay Drop',
        'Wallet',
        'Settings',
      ]) {
        await t.pumpWidget(const OkayMessagingApp());
        await t.pumpAndSettle();
        await t.tap(find.byTooltip('Open navigation menu'));
        await t.pumpAndSettle();
        // The drawer is a list and now runs past one screen at 320pt, so the
        // last destinations have to be scrolled to — the same thing a person
        // on that phone does. Reaching them is the assertion; fitting them
        // all above the fold never was.
        await t.dragUntilVisible(
          find.text(tile),
          find.byType(ListView).first,
          const Offset(0, -120),
        );
        await t.pumpAndSettle();
        await t.tap(find.text(tile));
        await t.pumpAndSettle();

        final failure = t.takeException();
        expect(failure, isNull, reason: '$tile does not lay out at 320: $failure');

        // pageBack() looks for anything tooltipped "Back", so using it IS the
        // assertion that there is a way out — and it is the right check
        // rather than looking for a BackButton widget, because a full-bleed
        // screen like Maps puts a floating circle over the map instead of an
        // app bar, exactly as every map app does.
        await t.pageBack();
        await t.pumpAndSettle();
        expect(find.byTooltip('Open navigation menu'), findsOneWidget,
            reason: 'leaving $tile lands back on the home screen');
      }
    });

    testWidgets('it has a back arrow and no tab bar', (t) async {
      await openChat(t);
      expect(find.byType(BackButton), findsOneWidget,
          reason: 'a pushed screen goes back the way every app goes back');
      // The tab destinations belong to the home screen. Finding one here means
      // the bar has been let into a conversation again.
      expect(find.text('Communities'), findsNothing);
      expect(find.text('Notifications'), findsNothing);
    });

    testWidgets('the composer is under the conversation, at the bottom',
        (t) async {
      await openChat(t);
      final composer = t.getRect(find.byType(TextField).last);
      final message = t.getRect(find.text('Did you see the game last night?'));
      expect(composer.top, greaterThan(message.bottom),
          reason: 'the composer sits below the messages, not above them');
      expect(composer.bottom, greaterThan(844 - 140),
          reason: 'and within reach of the bottom of the screen');
    });

    testWidgets('the keyboard pushes it up, not to the top', (t) async {
      await openChat(t);
      // The exact state in the bug report: keyboard up, composer at the very
      // top of the screen with the whole conversation blank underneath.
      t.view.viewInsets = const FakeViewPadding(bottom: 336);
      addTearDown(t.view.resetViewInsets);
      await t.tap(find.byType(TextField).last);
      await t.pumpAndSettle();

      final composer = t.getRect(find.byType(TextField).last);
      final message = t.getRect(find.text('Did you see the game last night?'));
      expect(composer.top, greaterThan(message.bottom),
          reason: 'still under the conversation with the keyboard up');
      expect(composer.bottom, closeTo(844 - 336, 24),
          reason: 'it rides the top of the keyboard');
    });
  });

  group('Notes', () {
    setUp(() async {
      SharedPreferences.setMockInitialValues({});
      NotesStore.instance.resetForTest();
      await NotesStore.instance.load();
    });
    tearDown(NotesStore.instance.resetForTest);

    test('the first line is the title, and the rest is the preview', () {
      Note n(String body) => Note(
          id: 'x',
          body: body,
          createdAt: DateTime(2026),
          updatedAt: DateTime(2026));

      expect(n('Milk\nEggs\nBread').title, 'Milk');
      expect(n('Milk\nEggs\nBread').preview, 'Eggs Bread');
      // Leading blank lines are somebody hitting return, not a title.
      expect(n('\n\n  Shopping\nMilk').title, 'Shopping');
      expect(n('\n\n  Shopping\nMilk').preview, 'Milk');
      // One line is all title and no preview, rather than a repeat of itself.
      expect(n('Just this').title, 'Just this');
      expect(n('Just this').preview, '');
      expect(n('   ').title, '');
      expect(n('   ').isEmpty, isTrue);
      // A wall of text does not become the whole row.
      expect(n('x' * 200).title.length, lessThanOrEqualTo(81));
      expect(n('t\n${'y' * 400}').preview.length, lessThanOrEqualTo(141));
    });

    test('an empty note is never saved, and emptying one deletes it',
        () async {
      final store = NotesStore.instance;
      expect(await store.save(body: '   '), isNull,
          reason: 'a blank row is a thing to tidy up later');
      expect(store.count, 0);

      final note = await store.save(body: 'Something');
      expect(note, isNotNull);
      expect(store.count, 1);

      expect(await store.save(id: note!.id, body: ''), isNull);
      expect(store.count, 0, reason: 'emptying it deletes it');
    });

    test('pinned first, then most recently edited', () async {
      final store = NotesStore.instance;
      final a = await store.save(body: 'first');
      await Future<void>.delayed(const Duration(milliseconds: 5));
      final b = await store.save(body: 'second');
      await Future<void>.delayed(const Duration(milliseconds: 5));
      await store.save(body: 'third');

      expect([for (final n in store.notes) n.title], ['third', 'second', 'first']);

      // Editing moves it to the top: the list is what you were last doing.
      await store.save(id: a!.id, body: 'first, edited');
      expect(store.notes.first.title, 'first, edited');

      // A pin outranks recency, which is the whole point of one.
      expect(await store.togglePin(b!.id), isTrue);
      expect(store.notes.first.title, 'second');
      expect(await store.togglePin(b.id), isFalse);
      expect(store.notes.first.title, 'first, edited');
    });

    test('search looks at the whole note, not just the title', () async {
      final store = NotesStore.instance;
      await store.save(body: 'Shopping\nOat milk\nBread');
      await store.save(body: 'Standup\nShip the poll work');

      expect([for (final n in store.search('shopping')) n.title], ['Shopping']);
      expect([for (final n in store.search('OAT')) n.title], ['Shopping'],
          reason: 'case is not the point');
      expect([for (final n in store.search('poll')) n.title], ['Standup'],
          reason: 'a word only in the body still finds it');
      expect(store.search('   ').length, 2, reason: 'empty is everything');
      expect(store.search('nothinghere'), isEmpty);
    });

    test('a restored backup keeps the newer edit of each note', () async {
      final store = NotesStore.instance;
      final mine = await store.save(body: 'mine, edited on this device');
      final exported = store.exportNotes();

      // The same note, edited more recently somewhere else, plus one this
      // device has never seen.
      store.hydrateNotes([
        {
          ...exported.first,
          'body': 'mine, edited later elsewhere',
          'updatedAt': mine!.updatedAt
              .add(const Duration(minutes: 1))
              .toUtc()
              .toIso8601String(),
        },
        {
          'id': 'nt_other',
          'body': 'written on the other device',
          'createdAt': DateTime(2026).toUtc().toIso8601String(),
          'updatedAt': DateTime(2026).toUtc().toIso8601String(),
        },
      ]);
      expect(store.count, 2);
      expect(store.byId(mine.id)!.body, 'mine, edited later elsewhere');

      // And the other way round: an OLDER copy does not overwrite this one.
      store.hydrateNotes([
        {
          ...exported.first,
          'body': 'stale',
          'updatedAt': mine.updatedAt
              .subtract(const Duration(days: 1))
              .toUtc()
              .toIso8601String(),
        },
      ]);
      expect(store.byId(mine.id)!.body, 'mine, edited later elsewhere',
          reason: 'restoring must not throw away newer local work');
    });

    test('notes ride the encrypted backup, and never a table of their own',
        () {
      // Same trade as everything else here: sealed before it leaves, or it
      // does not leave. There is no notes table anywhere in the SQL.
      final sync = File('lib/state/cloud_sync.dart').readAsStringSync();
      expect(sync.contains("'notes': NotesStore.instance.exportNotes()"), isTrue);
      expect(sync.contains('hydrateNotes'), isTrue);

      // `.from(` was the first thing tried here and it matched
      // `Map<String, dynamic>.from(row)` — the import is the honest check.
      final store = File('lib/state/notes_store.dart').readAsStringSync();
      expect(store.contains('supabase'), isFalse,
          reason: 'a note never goes to a table');
      expect(store.contains('Supabase'), isFalse);
      // A TABLE, not the word — "PRIVACY NOTE" in a comment is not a schema.
      // The first version of this check matched those and failed for it.
      final table = RegExp(r'(create table[^;]*|public\.)notes\b',
          caseSensitive: false);
      for (final f in [
        ...Directory('docs').listSync(),
        File('supabase/schema.sql'),
      ]) {
        if (f is File && f.path.endsWith('.sql')) {
          expect(table.hasMatch(f.readAsStringSync()), isFalse,
              reason: '${f.path} has a notes table');
        }
      }
    });

    testWidgets('writing one, finding it, and emptying it', (t) async {
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);

      await t.pumpWidget(const MaterialApp(home: NotesScreen()));
      await t.pumpAndSettle();
      expect(find.text('No notes yet'), findsOneWidget);

      await t.tap(find.widgetWithText(FilledButton, 'Write one'));
      await t.pumpAndSettle();
      await t.enterText(find.byType(TextField).first, 'Shopping\nOat milk');
      // Saved on the way out, not behind a button: a note you have to
      // remember to save is a note you lose.
      await t.pageBack();
      await t.pumpAndSettle();

      expect(find.text('Shopping'), findsOneWidget);
      expect(find.text('Oat milk'), findsOneWidget);
      expect(NotesStore.instance.count, 1);

      // Search narrows the list.
      await t.tap(find.byTooltip('Search notes'));
      await t.pumpAndSettle();
      await t.enterText(find.byType(TextField).first, 'zzz');
      await t.pumpAndSettle();
      expect(find.text('Nothing matches'), findsOneWidget);
      await t.tap(find.byTooltip('Stop searching'));
      await t.pumpAndSettle();
      expect(find.text('Shopping'), findsOneWidget);

      // Emptying it deletes it rather than leaving a blank row.
      await t.tap(find.text('Shopping'));
      await t.pumpAndSettle();
      await t.enterText(find.byType(TextField).first, '');
      await t.pageBack();
      await t.pumpAndSettle();
      expect(NotesStore.instance.count, 0);
      expect(find.text('No notes yet'), findsOneWidget);
    });

    testWidgets('Notes is in the sidebar, with the rest of the apps',
        (t) async {
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
      await t.tap(find.byTooltip('Open navigation menu'));
      await t.pumpAndSettle();
      expect(find.text('Notes'), findsOneWidget);
      await t.tap(find.text('Notes'));
      await t.pumpAndSettle();
      expect(find.text('No notes yet'), findsOneWidget);
      // And it can be left again.
      await t.pageBack();
      await t.pumpAndSettle();
      expect(find.byTooltip('Open navigation menu'), findsOneWidget);
    });
  });

  group('Functions that no signed-in user calls', () {
    /// Functions whose source declares they must run without the gateway's
    /// JWT check, found by their marker rather than by a list here — a third
    /// webhook added later is caught the moment it carries the marker.
    List<String> markedFunctions() => [
          for (final dir in Directory('supabase/functions')
              .listSync()
              .whereType<Directory>())
            if (File('${dir.path}/index.ts').existsSync() &&
                File('${dir.path}/index.ts')
                    .readAsStringSync()
                    .contains('// supabase: verify_jwt = false'))
              dir.path.split('/').last
        ]..sort();

    test('the ones Stripe and Apple POST to are declared JWT-free', () {
      // THIS COST A WEEK OF STRIPE DELIVERIES. Supabase verifies a JWT at the
      // gateway by default; Stripe and Apple authenticate by signing the
      // body and send no Authorization header, so every delivery was answered
      // 401 before the function ran — invisible from inside, because the
      // function never executed to log anything.
      final marked = markedFunctions();
      // `pages` is here for the same reason and not a third party's: a
      // browser opens it — a confirmation link from an email — and a browser
      // carries no Supabase session either.
      expect(marked, ['iap-notify', 'pages', 'payments-webhook'],
          reason: 'a function that a third party POSTs to needs the marker');

      final config = File('supabase/config.toml').readAsStringSync();
      for (final name in marked) {
        expect(config.contains('[functions.$name]\nverify_jwt = false'), isTrue,
            reason: 'config.toml does not turn JWT verification off for '
                '$name, so a CLI deploy would put it back');
      }
    });

    test('and nothing else is', () {
      // The other direction. Every function the app itself calls SHOULD be
      // behind the gateway's check; turning it off for one of those would
      // open it to anyone with the URL.
      final config = File('supabase/config.toml').readAsStringSync();
      final off = RegExp(r'\[functions\.([a-z0-9-]+)\]\s*\nverify_jwt = false')
          .allMatches(config)
          .map((m) => m.group(1)!)
          .toList()
        ..sort();
      expect(off, markedFunctions(),
          reason: 'config.toml exempts a function whose source does not ask '
              'to be exempt');
    });

    test('a signed body is checked before anything is done with it', () {
      // The exemption is only safe because these verify the sender
      // themselves. If that ever stops being true, the open endpoint is the
      // whole attack.
      expect(
          File('supabase/functions/payments-webhook/index.ts')
              .readAsStringSync()
              .contains('stripe.webhooks.constructEventAsync'),
          isTrue);
      expect(
          File('supabase/functions/iap-notify/index.ts')
              .readAsStringSync()
              .contains('verifyAppleJws'),
          isTrue);
    });
  });

  group('A notification when the app is closed', () {
    test('a push carries which conversation it is for, in a form the app '
        'already knows how to open', () {
      // The two halves of a tap: Swift builds a URL from the payload, Dart
      // parses it. They are in different languages and neither compiles the
      // other, so the format is asserted rather than assumed.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      final template = RegExp(r'URL\(string: "(im:[^"]+)"\)')
          .firstMatch(swift)
          ?.group(1);
      expect(template, isNotNull,
          reason: 'the tap handler no longer builds an im: URL');
      final url = template!.replaceAll(r'\(digits)', '15550102222');
      expect(IncomingLinks.imPhone(url), '+15550102222',
          reason: 'a tap would open nothing');

      // And the payload the function sends actually has that field in it.
      final fn = File('supabase/functions/push-send/index.ts').readAsStringSync();
      expect(fn.contains('...(from ? { from } : {})'), isTrue);
      expect(
          File('lib/state/push_service.dart')
              .readAsStringSync()
              .contains("'fromPhone':"),
          isTrue);
    });

    test('a push never carries the message', () {
      // The whole point of this app is that a message body is unreadable off
      // the device. A notification is the one place it would be trivially
      // easy to hand Apple the plaintext.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      final call = RegExp(r'PushService\.instance\.notify\((.*?)\);', dotAll: true)
          .firstMatch(relay)
          ?.group(1);
      expect(call, isNotNull);
      expect(call!.contains('message.text'), isFalse,
          reason: 'the message body would go to Apple in clear text');
      expect(call.contains('message.'), isFalse,
          reason: 'nothing off the message belongs in a push payload');

      // The function forwards a title and a body it is given and nothing it
      // reads out of the database — there is no message table to read.
      final fn = File('supabase/functions/push-send/index.ts').readAsStringSync();
      expect(fn.contains('.from("push_tokens")'), isTrue);
      expect(RegExp(r'\.from\("(?!push_tokens)').hasMatch(fn), isFalse,
          reason: 'push-send reads one table, and it holds device tokens');
    });

    test('a push that lands while the app is open is shown, except in the '
        'chat it belongs to', () {
      // iOS shows NOTHING for a foreground push unless the app says
      // otherwise, so without this somebody on another tab got no hint at all.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift.contains('UNUserNotificationCenter.current().delegate = self'),
          isTrue, reason: 'no delegate means no taps and no foreground alerts');
      expect(swift.contains('willPresent notification'), isTrue);
      expect(swift.contains('completionHandler([.banner, .sound, .badge])'),
          isTrue);
      expect(swift.contains('from == openChatDigits'), isTrue,
          reason: 'a banner over the message you are reading is noise');
      expect(swift.contains('didReceive response'), isTrue);
      expect(swift.contains('AppDelegate.deliverLink(url)'), isTrue,
          reason: 'a tap should land in the chat, not wherever the app was');

      // And Dart keeps the native side told which chat that is.
      final chat = File('lib/screens/chat_screen.dart').readAsStringSync();
      expect(chat.contains('PushService.instance.setOpenChat(widget.chat.contact.phone)'),
          isTrue);
      expect(chat.contains('PushService.instance.setOpenChat(null)'), isTrue,
          reason: 'a stale open chat silences the next banner');
    });

    test('a device token is only ever readable by the device that made it',
        () {
      // Every token in this table is a way to ring somebody's phone. The
      // policy is the row, and the row is only ever yours.
      final sql = File('supabase/schema.sql').readAsStringSync();
      for (final policy in [
        'push_tokens_read_own',
        'push_tokens_upsert_own',
        'push_tokens_update_own',
      ]) {
        expect(sql.contains(policy), isTrue, reason: policy);
      }
      expect(
          RegExp(r"create policy push_tokens_read_own[\s\S]*?"
                  r"using \(phone = \(auth\.jwt\(\) ->> 'phone'\)\)")
              .hasMatch(sql),
          isTrue,
          reason: 'the read policy no longer scopes to your own number');
    });

    test('digits are what a push is addressed by', () {
      expect(PushService.digitsOf('+1 (555) 010-2222'), '15550102222');
      expect(PushService.digitsOf(''), '');
    });
  });

  group('Signing in with an email and a password', () {
    test('a password is checked before a round trip, and only for length', () {
      // Composition rules push people towards Password1! — length is the one
      // that helps. Supabase enforces its own minimum on top.
      expect(AccountService.passwordProblem(''), 'Enter a password.');
      expect(AccountService.passwordProblem('short'),
          contains('${AccountService.minPasswordLength} characters'));
      expect(AccountService.passwordProblem('a' * AccountService.minPasswordLength),
          isNull);
      expect(AccountService.passwordProblem('a whole passphrase here'), isNull);
    });

    testWidgets('the password field appears once an address is typed',
        (t) async {
      // Not behind a "get a code" round trip: somebody who has a password
      // should not have to ask for a code to find the box for it.
      t.view.physicalSize = const Size(500, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      addTearDown(() => debugVerifiedModeOverride = null);
      debugVerifiedModeOverride = true;

      await t.pumpWidget(const MaterialApp(home: PhoneLoginScreen()));
      await t.pumpAndSettle();
      if (find.text('Use a different account').evaluate().isNotEmpty) {
        await t.tap(find.text('Use a different account'));
        await t.pumpAndSettle();
      }
      await t.tap(find.text('Sign in').first);
      await t.pumpAndSettle();
      await t.tap(find.text('Sign in with username or email'));
      await t.pumpAndSettle();

      expect(find.widgetWithText(TextFormField, 'Password'), findsNothing,
          reason: 'a handle has no password here');
      await t.enterText(
          find.widgetWithText(TextFormField, 'Username or email'), 'ada_l');
      await t.pumpAndSettle();
      expect(find.widgetWithText(TextFormField, 'Password'), findsNothing);

      await t.enterText(find.widgetWithText(TextFormField, 'Username or email'),
          'ada@example.com');
      await t.pumpAndSettle();
      expect(find.widgetWithText(TextFormField, 'Password'), findsOneWidget);
      // Empty is still allowed — that is the code route, and it says so.
      expect(find.textContaining('code by email instead'), findsOneWidget);
    });

    testWidgets('the password is hidden until you ask to see it', (t) async {
      t.view.physicalSize = const Size(500, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      addTearDown(() => debugVerifiedModeOverride = null);
      debugVerifiedModeOverride = true;

      await t.pumpWidget(const MaterialApp(home: PhoneLoginScreen()));
      await t.pumpAndSettle();
      if (find.text('Use a different account').evaluate().isNotEmpty) {
        await t.tap(find.text('Use a different account'));
        await t.pumpAndSettle();
      }
      await t.tap(find.text('Sign in').first);
      await t.pumpAndSettle();
      await t.tap(find.text('Sign in with username or email'));
      await t.pumpAndSettle();
      await t.enterText(find.widgetWithText(TextFormField, 'Username or email'),
          'ada@example.com');
      await t.pumpAndSettle();

      TextField field() => t.widget<TextField>(find.descendant(
          of: find.widgetWithText(TextFormField, 'Password'),
          matching: find.byType(TextField)));
      expect(field().obscureText, isTrue);
      await t.tap(find.byTooltip('Show password'));
      await t.pumpAndSettle();
      expect(field().obscureText, isFalse,
          reason: 'a field nobody can read back is one they mistype');
    });

    test('an email on no phone account is refused, not half signed in', () {
      // Messaging identity here IS the number. A session with none is
      // discarded rather than carried into the app — the same contract the
      // emailed-code route has had.
      final src = File('lib/state/account_service.dart').readAsStringSync();
      final body = src.substring(src.indexOf('Future<String?> signInWithPassword'));
      final end = body.indexOf('\n  /// ');
      final fn = end == -1 ? body : body.substring(0, end);
      expect(fn.contains('auth.signOut()'), isTrue,
          reason: 'a phone-less session is left signed in');
      expect(fn.contains('return null'), isTrue);
    });

    test('a password can only be set on an account that exists', () {
      // updateUser needs a live session, which is the point: this is a second
      // door into an account, not a way to make one.
      final src = File('lib/state/account_service.dart').readAsStringSync();
      expect(src.contains('auth.updateUser(UserAttributes(password:'), isTrue);
      // And the place it is offered is the one that holds the address.
      final screen =
          File('lib/screens/account_email_screen.dart').readAsStringSync();
      expect(screen.contains('AccountService.instance.setPassword'), isTrue);
      expect(screen.contains('if (store.isSet) ...['), isTrue,
          reason: 'a password with no address is a credential with no name');
    });
  });

  group('Reading a verdict back from Stripe', () {
    test('identity-status asks Stripe rather than trusting a webhook', () {
      // A dropped webhook used to mean verified-forever-unverified. Stripe
      // verified the person; payments-webhook was rejected at Supabase's
      // door; identity_verifications never moved off "processing"; the app
      // read that as the badge being taken away.
      final src =
          File('supabase/functions/identity-status/index.ts').readAsStringSync();
      expect(src.contains('verificationSessions.retrieve'), isTrue,
          reason: 'the answer still comes only from our own table');
      // And it must fetch the legal name, or payments-create-intent refuses
      // even once the status flips — verified, and still unable to send
      // money, which looks identical to not being verified.
      expect(src.contains('verified_outputs'), isTrue,
          reason: 'a pass without a name leaves payments locked');
      expect(src.contains('verified_name'), isTrue);
      // A stored pass short-circuits, so this does not hit Stripe on every
      // single launch.
      expect(
          src.replaceAll(RegExp(r'\s+'), ' ').contains(
              'if (stored === "verified" && storedName)'),
          isTrue,
          reason: 'every launch would call Stripe');
    });

    testWidgets('a check still being read is not "verification removed"',
        (tester) async {
      // Three different things were one sentence: a pass, a check Stripe is
      // still reading, and an answer that never arrived. Saying "Verification
      // removed" to somebody who has just handed over their passport is the
      // wrong one twice out of three times.
      IdentityVerification.instance.debugSetStatus(IdentityStatus.processing);
      addTearDown(IdentityVerification.instance.resetForTest);
      await tester.pumpWidget(const MaterialApp(home: ScoreScreen()));
      await tester.pumpAndSettle();

      final src = File('lib/screens/score_screen.dart').readAsStringSync();
      expect(src.contains('Still being checked'), isTrue);
      // Without the leading apostrophe: the Dart source escapes it.
      expect(src.contains('reach the server. Nothing changed.'), isTrue,
          reason: 'an outage must not read as the badge being withdrawn');
      // And nothing is taken away except on an explicit cancellation.
      final flat = src.replaceAll(RegExp(r'\s+'), ' ');
      expect(
          flat.contains(
              'if (status == IdentityStatus.canceled) _setVerified(context, false);'),
          isTrue,
          reason: 'a pending or unreachable check still clears the badge');
    });
  });

  group('Money and strangers need a verified account', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      IdentityVerification.instance.resetForTest();
      Session.instance.signInForTest();
    });
    tearDown(IdentityVerification.instance.resetForTest);

    /// The three screens the gate stands in front of, and the words each one
    /// puts on the door.
    const gated = [
      ('Marketplace', MarketplaceScreen()),
      ('Wallet', WalletScreen()),
      ('Okay Drop', NearbyShareScreen()),
    ];

    testWidgets('an unverified account is stopped at all three', (t) async {
      IdentityVerification.debugGateOverride = true;
      for (final (title, screen) in gated) {
        await t.pumpWidget(MaterialApp(key: ValueKey(title), home: screen));
        await t.pumpAndSettle();
        expect(find.text('$title needs a verified account'), findsOneWidget,
            reason: '$title let an unverified account straight in');
        expect(find.text('Get verified'), findsOneWidget, reason: title);
      }
    });

    testWidgets('and let in once the check has passed', (t) async {
      IdentityVerification.debugGateOverride = true;
      IdentityVerification.instance.debugSetStatus(IdentityStatus.verified);
      for (final (title, screen) in gated) {
        await t.pumpWidget(MaterialApp(key: ValueKey(title), home: screen));
        await t.pumpAndSettle();
        expect(find.text('$title needs a verified account'), findsNothing,
            reason: '$title still gated a verified account');
      }
    });

    testWidgets('a check still being read says so, and does not ask again',
        (t) async {
      // Sending somebody back round a flow they have just finished is how an
      // app reads as broken.
      IdentityVerification.debugGateOverride = true;
      IdentityVerification.instance.debugSetStatus(IdentityStatus.processing);
      await t.pumpWidget(const MaterialApp(home: WalletScreen()));
      await t.pumpAndSettle();
      expect(find.textContaining('still being read'), findsOneWidget);
      expect(find.text('Get verified'), findsNothing);
    });

    testWidgets('a build with no server does not lock a door with no key',
        (t) async {
      // identity-start is an Edge Function. Where there is none, nobody can
      // ever verify — so gating would take three features away for good.
      IdentityVerification.debugGateOverride = false;
      for (final (title, screen) in gated) {
        await t.pumpWidget(MaterialApp(key: ValueKey(title), home: screen));
        await t.pumpAndSettle();
        expect(find.text('$title needs a verified account'), findsNothing,
            reason: '$title gated a build that cannot verify anybody');
      }
    });

    testWidgets('the owner walks through the two gates that are ours to waive',
        (t) async {
      // A rule enforcing itself against the person who set it. The marketplace
      // and Okay Drop need nothing from outside the app, so running the app
      // is enough.
      IdentityVerification.debugGateOverride = true;
      PlatformModeration.instance.debugSet(role: PlatformRole.owner);
      addTearDown(PlatformModeration.instance.resetForTest);
      for (final (title, screen) in [
        ('Marketplace', const MarketplaceScreen()),
        ('Okay Drop', const NearbyShareScreen()),
      ]) {
        await t.pumpWidget(MaterialApp(key: ValueKey(title), home: screen));
        await t.pumpAndSettle();
        expect(find.text('$title needs a verified account'), findsNothing,
            reason: '$title still gated the owner');
        expect(find.text('Even you need this one'), findsNothing, reason: title);
      }
    });

    testWidgets('and is still held at the wallet, which is not ours to waive',
        (t) async {
      // Every payment carries the verified legal name on the Stripe intent and
      // the capture gate checks against it: `payments-create-intent` returns
      // identity_required without one whoever is asking. Opening this for an
      // owner would trade an explanation for a 403 three taps later.
      IdentityVerification.debugGateOverride = true;
      PlatformModeration.instance.debugSet(role: PlatformRole.owner);
      addTearDown(PlatformModeration.instance.resetForTest);
      await t.pumpWidget(const MaterialApp(home: WalletScreen()));
      await t.pumpAndSettle();
      expect(find.text('Even you need this one'), findsOneWidget);
      // And it says why, because "needs a verified account" reads as a bug to
      // the person who owns the account.
      expect(find.textContaining('cannot supply a name'), findsOneWidget);
      expect(find.text('Get verified'), findsOneWidget);
    });

    test('a padlock is only drawn on a row that is actually shut', () {
      // The hint mirrors the gate's own flag. A padlock on a row that opens is
      // a worse lie than no padlock, so the two have to be set together.
      final src = File('lib/screens/home_screen.dart').readAsStringSync();
      final held = RegExp(r'_GateHint\(\)').allMatches(src).length;
      // The wallet holds both gates. The marketplace (browse-only) and Okay
      // Drop (two phones and a radio) both open for a numberless account,
      // so they carry the numberlessMayPass form; Maps opened outright and
      // carries no hint at all.
      expect(held, 1, reason: 'the wallet row stopped showing its padlock');
      expect(RegExp(r'numberlessMayPass: true').allMatches(src).length, 2,
          reason: 'the marketplace and Okay Drop rows must drop the phone '
              'padlock — both open for a numberless account');

      // The one row only the phone gate shuts: Newsfeed (its RLS insert
      // needs a session). Servers dropped both padlock and gate — the
      // community bus rides the same anon-key transports as chat, so the
      // gate's reason stopped being true. The second match is inside
      // _GateHint, which is how a row behind BOTH gates shows one padlock
      // instead of two.
      expect(RegExp(r'PhoneOnlyHint\(\)').allMatches(src).length, 2,
          reason: 'a phone-gated row lost its padlock, or gained one it '
              'cannot back up');
    });

    test('the gate is on the screens, not on the buttons that open them', () {
      // A drawer row is one way in; a deep link, a listing in a chat and a
      // share sheet are others, and a gate on the row is a gate on one.
      for (final path in [
        'lib/screens/marketplace_screen.dart',
        'lib/screens/wallet_screen.dart',
        'lib/screens/nearby_share_screen.dart',
      ]) {
        expect(File(path).readAsStringSync().contains('VerifiedGate('), isTrue,
            reason: path);
      }
      // The same rule for the phone gate, on everything a username-only
      // account cannot use. Chat is not in this list, and that is the point:
      // broadcast and the mailbox are both reachable with the anon key, so
      // messages work for an account with no session at all.
      for (final path in [
        'lib/screens/wallet_screen.dart',
        'lib/screens/public_feed_screen.dart',
      ]) {
        expect(File(path).readAsStringSync().contains('PhoneGate('), isTrue,
            reason: '$path is reachable without a phone number');
      }
      // Servers OPENED for numberless accounts, deliberately: the
      // community bus is sealed broadcast + the anon-key mailbox + the
      // sealed post store — the same transports numberless chat already
      // rides — so the old gate locked people out of rooms their posts
      // could technically reach. This pin keeps it open.
      expect(
          File('lib/screens/communities.dart')
              .readAsStringSync()
              .contains('PhoneGate('),
          isFalse,
          reason: 'servers work without a session; the gate must not '
              'quietly return');
      // Chat, calls, browsing the marketplace, the map, Okay Drop and the
      // Alerts tab all work without a session — the relay rides the anon
      // key, the map is tiles and local state, Okay Drop is two phones and
      // a radio, and Alerts is built from local activity — so none of them
      // is phone-gated.
      for (final path in [
        'lib/tabs/chats_tab.dart',
        'lib/screens/chat_screen.dart',
        'lib/tabs/calls_tab.dart',
        'lib/screens/marketplace_screen.dart',
        'lib/screens/explore_map_screen.dart',
        'lib/screens/nearby_share_screen.dart',
        'lib/tabs/activity_tab.dart',
      ]) {
        expect(File(path).readAsStringSync().contains('PhoneGate('), isFalse,
            reason: '$path works without a phone number');
      }
      // Okay Drop's ID check opens for a numberless account too — it cannot
      // verify (no session), so holding that gate would lock the feature
      // forever rather than until verification.
      expect(
          File('lib/screens/nearby_share_screen.dart')
              .readAsStringSync()
              .contains('numberlessMayPass: true'),
          isTrue,
          reason: 'Okay Drop must open for a numberless account');
      // But the marketplace withholds selling from a numberless account —
      // listing needs the wallet and the ID check. Browse + message only.
      final market =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(market.contains('browseOnly: true'), isTrue,
          reason: 'a numberless account gets the browse-only marketplace');
      expect(market.contains('if (Session.instance.isNumberless)'), isTrue,
          reason: 'selling is refused for a numberless account');
      // Sending money from a chat is the wallet's own capability reached
      // another way — guarding one screen and not this is guarding the door
      // and leaving the window.
      expect(
          File('lib/screens/chat_screen.dart')
              .readAsStringSync()
              .contains('IdentityVerification.instance.allowsTrusted'),
          isTrue);
    });

    test('the verdict survives a launch with no network', () async {
      // It lives on the server and asking needs one — but "send this to the
      // person next to you" is the feature whose whole point is not having
      // one.
      SharedPreferences.setMockInitialValues({});
      IdentityVerification.instance.debugSetStatus(IdentityStatus.verified);
      await Future<void>.delayed(const Duration(milliseconds: 20));

      IdentityVerification.instance.resetForTest();
      expect(IdentityVerification.instance.isVerified, isFalse);
      await IdentityVerification.instance.load();
      expect(IdentityVerification.instance.isVerified, isTrue,
          reason: 'a verified account read as unverified offline');
    });
  });

  group('The two timelines are one timeline', () {
    /// Every accented, tappable run in a rendered [FeedBodyText] — the
    /// #tags, @mentions and links that are live rather than just words.
    List<String> liveTokens(WidgetTester t) {
      final text = t.widget<Text>(find
          .descendant(of: find.byType(FeedBodyText), matching: find.byType(Text))
          .first);
      final out = <String>[];
      text.textSpan?.visitChildren((span) {
        if (span is TextSpan && span.recognizer != null && span.text != null) {
          out.add(span.text!);
        }
        return true;
      });
      return out;
    }

    testWidgets('the same post reads the same on either timeline', (t) async {
      // The two drifted for a long time: different avatars for the same
      // person, "40d" against "22 Jun", a name that fit on one and truncated
      // on the other, a URL live on one and dead text on the other.
      SharedPreferences.setMockInitialValues({});
      AppState.resetForTest();
      Session.instance.signInForTest();
      ChatStore.instance.reset();
      FeedStore.instance.resetForTest();
      PublicFeedStore.instance.resetForTest();

      final when = DateTime.now().subtract(const Duration(days: 40));
      const body = 'Notes on #polls for @ada — https://okaymessaging.com/x';

      FeedStore.instance.addRemote(FeedPost(
        id: 'srv1',
        communityId: 'c1',
        authorName: 'Ada Lovelace',
        authorUsername: 'ada',
        time: when,
        text: body,
      ));
      PublicFeedStore.debugLoadOverride = () async => [
            PublicPost(
              id: 'pub1',
              authorUsername: 'ada',
              authorName: 'Ada Lovelace',
              body: body,
              createdAt: when,
            ),
          ];
      addTearDown(() => PublicFeedStore.debugLoadOverride = null);

      final seen = <String, List<String>>{};
      for (final (name, screen) in <(String, Widget)>[
        ('server', const FeedScreen(communityId: 'c1', communityName: 'HQ')),
        ('public', const PublicFeedScreen()),
      ]) {
        await t.pumpWidget(MaterialApp(home: screen));
        await t.pumpAndSettle();

        // Drawn from the shared parts, not each screen's own copy.
        expect(find.byType(FeedAvatar), findsWidgets, reason: name);
        expect(find.byType(FeedPostHeader), findsWidgets, reason: name);
        expect(find.byType(FeedBodyText), findsWidgets, reason: name);
        expect(find.byType(FeedPostActions), findsWidgets, reason: name);

        // The whole name, not "Ada Lovel…" — the handle gives way first.
        expect(find.text('Ada Lovelace'), findsOneWidget, reason: name);
        seen['$name-age'] = [
          for (final w in t
              .widgetList<Text>(find.descendant(
                  of: find.byType(FeedPostHeader), matching: find.byType(Text)))
              .toList())
            if (w.data != null && w.data!.startsWith('· ')) w.data!
        ];
        seen['$name-live'] = liveTokens(t);
      }

      // One age format. A post from six weeks ago said "40d" on a server feed
      // and "22 Jun" on the public one.
      expect(seen['server-age'], seen['public-age']);
      expect(seen['server-age']!.single, contains('·'));

      // And the same three things are tappable in the body, including the
      // link, which the public feed used to render as plain text.
      expect(seen['server-live'], seen['public-live']);
      expect(seen['server-live'],
          ['#polls', '@ada', 'https://okaymessaging.com/x']);
    });

    testWidgets('answering a post is the same gesture on either timeline',
