  group('Colour that survives both themes', () {
    /// WCAG contrast between two opaque colours.
    double ratio(Color a, Color b) {
      final l1 = a.computeLuminance(), l2 = b.computeLuminance();
      final hi = l1 > l2 ? l1 : l2, lo = l1 > l2 ? l2 : l1;
      return (hi + 0.05) / (lo + 0.05);
    }

    test('nothing in either scheme is a colour nobody chose', () {
      // ColorScheme.fromSeed builds the container tones from a tonal palette
      // and raises the chroma while it does. From a seed that is very nearly
      // black it still handed back #CDE5FF, #D4E4F6 and #EDDCFF in light and
      // #004E5C, #334A50 and #3E4565 in dark — all at full saturation. Every
      // widget that asked for a container colour got one, which is how a
      // greyscale app ended up with a teal card on its first screen, a teal
      // chip on Alerts and a teal panel in Cloud storage.
      for (final (name, scheme) in [
        ('light', AppTheme.light.colorScheme),
        ('dark', AppTheme.dark.colorScheme),
      ]) {
        for (final (label, colour) in [
          ('primaryContainer', scheme.primaryContainer),
          ('secondaryContainer', scheme.secondaryContainer),
          ('tertiaryContainer', scheme.tertiaryContainer),
        ]) {
          expect(HSLColor.fromColor(colour).saturation, lessThan(0.25),
              reason: '$name $label is saturated');
          // And readable, since things get written on them.
          final on = switch (label) {
            'primaryContainer' => scheme.onPrimaryContainer,
            'secondaryContainer' => scheme.onSecondaryContainer,
            _ => scheme.onTertiaryContainer,
          };
          expect(ratio(on, colour), greaterThan(4.5),
              reason: '$name $label cannot be written on');
        }
        // Error keeps its red. That one is saying something.
        expect(HSLColor.fromColor(scheme.errorContainer).saturation,
            greaterThan(0.5),
            reason: '$name lost the one colour that carries meaning');
      }
    });

    test('a selected chip does not look like an unselected one', () {
      // With the container tones neutralised, a selected chip fell through to
      // the same grey as an unselected one and the filter row stopped saying
      // which filter was on.
      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        final chip = theme.chipTheme;
        expect(chip.selectedColor, isNotNull, reason: name);
        expect(chip.selectedColor, isNot(chip.backgroundColor), reason: name);
        expect(ratio(chip.selectedColor!, chip.backgroundColor!),
            greaterThan(3.0),
            reason: '$name: selected and unselected are the same to look at');
        // And the label flips with it.
        expect(ratio(chip.secondaryLabelStyle!.color!, chip.selectedColor!),
            greaterThan(4.5),
            reason: '$name: the selected label is unreadable on its own chip');
        expect(ratio(chip.labelStyle!.color!, chip.backgroundColor!),
            greaterThan(4.5),
            reason: '$name: the unselected label is unreadable on its chip');
      }
    });

    testWidgets('an unread chat is the loudest row, not the quietest',
        (t) async {
      // The timestamp and the count on an unread row were painted in a fixed
      // #536471, which is 3.2:1 on the dark background — so the row asking to
      // be read was the dimmest one on the screen. The badge on Alerts was
      // worse: the accent, which flips to near-white in dark, with white
      // written on it.
      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        final scheme = theme.colorScheme;
        expect(ratio(scheme.primary, scheme.surface), greaterThan(4.5),
            reason: '$name: an unread row does not stand out');
        expect(ratio(scheme.onPrimary, scheme.primary), greaterThan(4.5),
            reason: '$name: the count on the badge cannot be read');
      }

      // And nothing on the row hard-codes a colour that only works in one of
      // them.
      final src = File('lib/widgets/chat_list_tile.dart').readAsStringSync();
      expect(src.contains('AppColors.lightGreen'), isFalse,
          reason: 'a fixed grey cannot pass both themes');
      final alerts = File('lib/tabs/activity_tab.dart').readAsStringSync();
      expect(alerts.contains('color: Colors.white,\n'), isFalse,
          reason: 'white on the accent is white on white in dark mode');
    });

    testWidgets('no screen in the app is a slab of one colour', (t) async {
      // The sweep, applied to the screens that had a big coloured block on
      // them. Each one shipped as a gradient somebody liked in isolation, and
      // together they were four different loud colours in an app whose whole
      // identity is black and white.
      t.view.physicalSize = const Size(430, 2600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      SharedPreferences.setMockInitialValues({});
      ScoreStore.instance.resetForTest();
      addTearDown(ScoreStore.instance.resetForTest);
      ScoreStore.instance.award(117);

      for (final (name, screen) in <(String, Widget)>[
        ('Okay Score', const ScoreScreen()),
        ('Settings', const SettingsScreen()),
        ('Cloud storage', const CloudSyncScreen()),
      ]) {
        await t.pumpWidget(
            MaterialApp(theme: AppTheme.dark, home: screen));
        await t.pumpAndSettle();

        for (final box in t.widgetList<Container>(find.byType(Container))) {
          final decoration = box.decoration;
          if (decoration is! BoxDecoration) continue;
          // A gradient across a whole card is the shape this keeps coming
          // back in.
          expect(decoration.gradient, isNull,
              reason: '$name has a gradient block on it again');
          final colour = decoration.color;
          if (colour == null || colour.a < 0.5) continue;
          final rect = t.getRect(find.byWidget(box));
          // Small things may be as loud as they like — the flame on the score
          // card is the point of it. A block is what this is about.
          if (rect.width < 120 || rect.height < 60) continue;
          expect(HSLColor.fromColor(colour).saturation, lessThan(0.25),
              reason: '$name draws a saturated block '
                  '${rect.width.round()}x${rect.height.round()}');
        }
      }
    });

    test('the tip row is a row, not a billboard', () {
      // A full-bleed violet gradient in the middle of Settings, in an app
      // that is greyscale everywhere else. Now an ordinary InfoTile under a
      // section named what people actually look for; the heart keeps the
      // colour and stays the findable mark.
      final src = File('lib/screens/settings_screen.dart').readAsStringSync();
      expect(src.contains('LinearGradient'), isFalse,
          reason: 'the tip jar is a gradient slab again');
      expect(src.contains("'Tips & subscriptions'"), isTrue,
          reason: 'the section must be named what people search the screen '
              'for');
      expect(src.contains('Icons.favorite'), isTrue,
          reason: 'the heart is what makes it findable');
      expect(src.contains("'Support the developer'"), isTrue);
      expect(src.contains("'Cloud storage subscription'"), isTrue,
          reason: 'the subscription must be visible AS a subscription');
    });

    test('no fixed grey can pass both themes, which is why subtle exists', () {
      // The measurement the sweep came out of. Each of the two greys the app
      // reached for fails in one theme, and not the same one — so there is no
      // shade to pick, only a theme colour to ask for.
      final light = AppTheme.light.colorScheme;
      final dark = AppTheme.dark.colorScheme;

      expect(ratio(Colors.grey.shade600, dark.surface), lessThan(4.5),
          reason: 'shade600 is the one that fails on dark');
      expect(ratio(Colors.grey.shade500, light.surface), lessThan(4.5),
          reason: 'and shade500 is the one that fails on light');

      // What replaced them, in both.
      for (final (name, scheme) in [('light', light), ('dark', dark)]) {
        expect(ratio(scheme.onSurfaceVariant, scheme.surface),
            greaterThanOrEqualTo(4.5),
            reason: 'secondary text is unreadable on $name');
        // And the ordinary text colour, while we are here.
        expect(ratio(scheme.onSurface, scheme.surface),
            greaterThanOrEqualTo(7.0),
            reason: 'body text should be comfortable on $name, not just legal');
      }
    });

    test('nothing outside the theme picks a colour the theme should pick', () {
      // The whole of lib/, not a list of files that goes stale. There were
      // 300 fixed greys and 67 hard-coded light accents; what is left is
      // named below, with the reason, and nothing else may join them.
      const allowed = {
        // The themes' own definitions. A light-only grey inside AppTheme.light
        // is not a bug — that theme knows which one it is.
        'lib/theme/app_theme.dart',
        // Avatar swatch fallbacks: a colour painted BEHIND initials, judged
        // against the initials rather than against the page.
        'lib/screens/group_info_screen.dart',
        'lib/screens/edit_group_screen.dart',
      };
      final offenders = <String>[];
      for (final f in Directory('lib').listSync(recursive: true)) {
        if (f is! File || !f.path.endsWith('.dart')) continue;
        if (allowed.contains(f.path)) continue;
        final src = f.readAsStringSync();
        for (final banned in [
          'Colors.grey.shade500',
          'Colors.grey.shade600',
          'Colors.grey.shade700',
          // The trap app_theme.dart documents in so many words: "hard-coding
          // it paints a near-black button onto a near-black screen".
          'AppColors.tealGreenDark',
        ]) {
          if (src.contains(banned)) offenders.add('${f.path} → $banned');
        }
      }
      expect(offenders, isEmpty,
          reason: 'these pick a fixed colour where the theme has one:\n'
              '${offenders.join('\n')}');
    });

    testWidgets('the same screen is readable in both themes', (t) async {
      // Measured on what is actually painted, not on the palette. A colour
      // that passes in the abstract is still wrong if the widget draws it on
      // something other than the surface it was checked against.
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);

      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        await t.pumpWidget(MaterialApp(
          theme: theme,
          home: const Scaffold(
            body: EmptyState(
              icon: Icons.chat_bubble_outline,
              title: 'No chats yet',
              caption: 'Start a private, end-to-end encrypted conversation.',
            ),
          ),
        ));
        await t.pumpAndSettle();

        final surface = theme.colorScheme.surface;
        for (final finder in [
          find.text('No chats yet'),
          find.text('Start a private, end-to-end encrypted conversation.'),
        ]) {
          final colour = t.widget<Text>(finder).style?.color ??
              theme.textTheme.bodyMedium!.color!;
          expect(ratio(colour, surface), greaterThanOrEqualTo(4.5),
              reason: 'an empty state is unreadable on $name');
        }
      }
    });
  });

  group('Getting around', () {
    Future<void> home(WidgetTester t,
        {double width = 390, double height = 844}) async {
      t.view.physicalSize = Size(width, height);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
    }

    /// The pill in the floating bar, named rather than found by icon: the
    /// Servers empty state draws `Icons.groups_outlined` too, so finding the
    /// pill by its glyph can land on the illustration instead.
    Finder navPill(String label) => find.byKey(HomeScreen.debugNavPillKey(label));

    testWidgets('back leaves the tab you are on before it leaves the app',
        (t) async {
      // Android's back gesture and the browser's back button both closed the
      // app outright from a tab nobody had navigated *to*. The bar is
      // navigation; back has to undo it first.
      await home(t);
      await t.tap(navPill('Alerts'));
      await t.pumpAndSettle();
      expect(find.text('Notifications'), findsWidgets);

      final popped =
          await t.binding.handlePopRoute(); // the system back button
      await t.pumpAndSettle();
      expect(popped, isTrue, reason: 'the app handled it rather than exiting');
      expect(find.text('OkayMessenger'), findsOneWidget,
          reason: 'back from a tab lands on Chats');

      // And from Chats it is a real pop again, so the app can still be left.
      expect(await t.binding.handlePopRoute(), isFalse);
    });

    testWidgets('tapping the tab you are on scrolls it back to the top',
        (t) async {
      // Short enough that the conversation list actually overflows — at
      // 390x844 the sample chats fit, and a list with nowhere to go proves
      // nothing about coming back.
      await home(t, height: 460);
      // The conversation list itself, not whichever Scrollable happens to be
      // first in the tree — a horizontal chip row would answer to that. Held
      // by reference: the row it was found through scrolls out of the tree.
      final list = t.state<ScrollableState>(find
          .ancestor(
              of: find.text('Alice Bennett'), matching: find.byType(Scrollable))
          .first);
      await t.drag(find.text('Alice Bennett'), const Offset(0, -200));
      await t.pumpAndSettle();
      expect(list.position.pixels, greaterThan(0), reason: 'the list moved');

      await t.tap(navPill('Chats')); // already selected
      await t.pumpAndSettle();
      expect(list.position.pixels, 0,
          reason: 'a second tap on the current tab returns to the top');
    });

    testWidgets('a re-tap is safe on a tab that is not a plain list',
        (t) async {
      // The profile tab carries its own tab bar and a grid, so it is the one
      // most likely to hand its controller a number of positions other than
      // one — which is what the guard in _scrollTabToTop is for. As it stands
      // it attaches exactly one, so this covers the re-tap rather than the
      // guard; the guard is belt and braces and says so.
      await home(t);
      await t.tap(navPill('You'));
      await t.pumpAndSettle();
      await t.tap(navPill('You'));
      await t.pumpAndSettle();
      expect(t.takeException(), isNull);
    });

    testWidgets('the brand name is never cut off, on any phone', (t) async {
      // At 20pt with three actions beside it, "OkayMessenger" ellipsised to
      // "OkayMessen…" on a 390pt iPhone and "OkayMe…" on a 320pt one.
      for (final width in [320.0, 375.0, 390.0, 430.0]) {
        await home(t, width: width);
        final title =
            t.renderObject<RenderParagraph>(find.text('OkayMessenger').first);
        // Every letter is laid out — an ellipsis shows up as a laid-out width
        // narrower than the text wants to be.
        expect(title.size.width,
            greaterThanOrEqualTo(title.getMaxIntrinsicWidth(double.infinity)),
            reason: 'the brand name is truncated at $width');
        // And it is painted where it fits. Laying every letter out is not the
        // same as showing them: scaling the title to fit is the fix, and a
        // FittedBox lays its child out unconstrained whether it fits or not,
        // so without this the check passes over a name running under the
        // buttons.
        expect(t.getRect(find.text('OkayMessenger').first).right,
            lessThanOrEqualTo(t.getRect(find.byTooltip('New chat')).left),
            reason: 'the brand name runs into the actions at $width');
      }
    });

    testWidgets('the notification filters are readable, not clipped',
        (t) async {
      // "Mark all read" shared the row and left the chips 240pt, so "Servers"
      // rendered as "Ser" underneath the button's own text.
      for (final width in [320.0, 390.0]) {
        await home(t, width: width);
        await t.tap(navPill('Alerts'));
        await t.pumpAndSettle();
        // The row the chips scroll in has to be the whole row. Measuring the
        // labels instead would measure the test font, which is a fixed-width
        // box per glyph and far wider than the Roboto they ship in — every
        // chip "overflows" here and none of them does on a phone. What went
        // wrong was never the chips' width, it was being given 240pt of a
        // 320pt screen and clipped without a hint that there was more.
        final viewport = t.getRect(find
            .ancestor(of: find.text('All'), matching: find.byType(Scrollable))
            .first);
        expect(viewport.width, closeTo(width, 1),
            reason: 'the filters do not get the full row at $width');
        expect(find.byTooltip('Mark all read'), findsOneWidget,
            reason: 'the action lives in the app bar now');
      }
    });

    testWidgets('mark all read clears every unread chat', (t) async {
      await home(t);
      expect(ChatStore.instance.chats.any((c) => c.unreadCount > 0), isTrue);
      await t.tap(navPill('Alerts'));
      await t.pumpAndSettle();
      await t.tap(find.byTooltip('Mark all read'));
      await t.pumpAndSettle();
      expect(ChatStore.instance.chats.every((c) => c.unreadCount == 0), isTrue);
      expect(find.byTooltip('Mark all read'), findsNothing,
          reason: 'nothing left to mark, so no button');
    });

    testWidgets('the sidebar says which tab you are on, and switches to it',
        (t) async {
      await home(t);
      ListTile serversRow() => t.widget<ListTile>(find
          .ancestor(of: find.text('Servers'), matching: find.byType(ListTile))
          .first);

      await t.tap(find.byTooltip('Open navigation menu'));
      await t.pumpAndSettle();
      expect(serversRow().selected, isFalse, reason: 'Chats is showing');

      await t.tap(find.text('Servers'));
      await t.pumpAndSettle();
      // Switched the bar rather than pushing a second copy on top of it: a
      // pushed screen would have a back arrow and hide the menu button.
      expect(find.byTooltip('Open navigation menu'), findsOneWidget);
      expect(find.byType(BackButton), findsNothing);

      await t.tap(find.byTooltip('Open navigation menu'));
      await t.pumpAndSettle();
      expect(serversRow().selected, isTrue,
          reason: 'the row for the tab you are on says so');
    });

    testWidgets('an empty Servers tab offers the thing it asks for', (t) async {
      // Debug builds seed sample servers, so empty it first — the empty state
      // is what a real new account sees (a release build seeds nothing) and
      // what nothing else exercises.
      addTearDown(CommunityStore.instance.resetForTest);
      for (final c in [...CommunityStore.instance.communities]) {
        CommunityStore.instance.deleteCommunity(c.id);
      }
      await home(t);
      await t.tap(navPill('Servers'));
      await t.pumpAndSettle();
      expect(find.text('No servers yet'), findsOneWidget);
      // It said "Create a server to organise channels" and left people to
      // find the small + in the corner by themselves.
      await t.tap(find.widgetWithText(FilledButton, 'Create a server'));
      await t.pumpAndSettle();
      expect(t.takeException(), isNull);
      expect(find.text('No servers yet'), findsNothing,
          reason: 'the button starts the create flow');
    });

    testWidgets('no app-bar action is cut off by the edge of the screen',
        (t) async {
      // A guard, not a fix: the Calls tab carries three actions and the last
      // one sits hard against the right edge, close enough that a screenshot
      // reads as clipped. Measured, it fits — but there is no room left for a
      // fourth, and this is what will say so.
      for (final width in [320.0, 390.0]) {
        for (final label in ['Chats', 'Servers', 'Calls', 'Alerts', 'You']) {
          await home(t, width: width);
          await t.tap(navPill(label));
          await t.pumpAndSettle();
          final glyphs = find.descendant(
              of: find.byType(AppBar), matching: find.byType(Icon));
          for (var i = 0; i < glyphs.evaluate().length; i++) {
            final r = t.getRect(glyphs.at(i));
            expect(r.right, lessThanOrEqualTo(width),
                reason: 'an action on $label is off the right at $width');
            expect(r.left, greaterThanOrEqualTo(0.0),
                reason: 'an action on $label is off the left at $width');
          }
        }
      }
    });

    testWidgets('search is reachable from every tab', (t) async {
      // It looks through people, messages, servers, channels, calls and links
      // — none of which is a Chats-tab idea — and it was in the bar on one of
      // the five destinations.
      await home(t);
      for (final label in ['Chats', 'Servers', 'Calls', 'Alerts', 'You']) {
        await t.tap(navPill(label));
        await t.pumpAndSettle();
        expect(find.byTooltip('Search'), findsOneWidget,
            reason: 'no way to search from $label');
      }

      // And the Calls tab no longer carries a SECOND magnifying glass that
      // opened something else — the directory rather than this device.
      await t.tap(navPill('Calls'));
      await t.pumpAndSettle();
      expect(find.byIcon(Icons.search), findsOneWidget,
          reason: 'one magnifier, one meaning');
    });

    testWidgets('a search that finds nobody offers the directory', (t) async {
      // This search only ever looked at what is already on the device, so
      // looking for somebody you have not met said "No results" and stopped.
      // The directory lookup existed the whole time, on another tab, behind
      // the icon that meant something different.
      await home(t);
      await t.tap(find.byTooltip('Search'));
      await t.pumpAndSettle();
      await t.enterText(find.byType(TextField).first, 'nobodyhere');
      await t.pumpAndSettle();

      expect(find.textContaining('No results'), findsOneWidget);
      final lookUp = find.widgetWithText(FilledButton, 'Look up @nobodyhere');
      expect(lookUp, findsOneWidget, reason: 'the way out is offered');

      await t.tap(lookUp);
      await t.pumpAndSettle();
      // And it arrives with the handle already typed, rather than asking for
      // it a second time.
      expect(find.widgetWithText(TextField, 'nobodyhere'), findsWidgets);
    });

    testWidgets('a blank screen carries the action it names', (t) async {
      // "Tap the compose button to start a conversation" pointed at an icon in
      // the corner. EmptyState has always taken a button; four screens told
      // people what to do and made them go and find it.
      addTearDown(ChatStore.instance.reset);
      for (final c in [...ChatStore.instance.chats]) {
        ChatStore.instance.deleteChat(c.id);
      }
      await home(t);
      expect(find.text('No chats yet'), findsOneWidget);
      await t.tap(find.widgetWithText(FilledButton, 'Start a chat'));
      await t.pumpAndSettle();
      expect(t.takeException(), isNull);
      expect(find.text('No chats yet'), findsNothing,
          reason: 'the button opens the compose screen');
    });

    testWidgets('every themed text style is drawn in the app\'s own type',
        (t) async {
      // A component theme's textStyle does NOT inherit the textTheme's family,
      // so the app bar title and every filled button were being drawn in
      // whatever the platform picked instead of Roboto. Invisible on iOS,
      // where the fallback happens to look similar; not on the web.
      // Comments stripped first: the explanations for exactly this are long
      // enough to push `fontFamily` out of any fixed window after the match.
      final theme = File('lib/theme/app_theme.dart')
          .readAsStringSync()
          .split('\n')
          .where((l) => !l.trimLeft().startsWith('//'))
          .join('\n');
      final styles =
          RegExp(r'(?:title)?[tT]extStyle:\s*(?:const\s*)?TextStyle\(')
              .allMatches(theme);
      expect(styles.length, greaterThan(3),
          reason: 'the regex stopped matching the component themes');
      for (final m in styles) {
        final body =
            theme.substring(m.end, math.min(m.end + 200, theme.length));
        expect(body.contains("fontFamily: 'Roboto'"), isTrue,
            reason: 'a themed style at offset ${m.start} names no font family');
      }
    });
  });

  group('Suggested replies', () {
    setUp(() => SmartReplies.instance.resetForTest());
    tearDown(() => SmartReplies.instance.resetForTest());

    test('nothing is suggested until the other person has spoken', () {
      DateTime t(int m) => DateTime.now().subtract(Duration(minutes: m));
      Message msg(String id, String text, bool mine) =>
          Message(id: id, text: text, time: t(1), isMe: mine);

      // Answering yourself, or starting the conversation for somebody.
      expect(SmartReplies.worthSuggesting(const []), isFalse);
      expect(SmartReplies.worthSuggesting([msg('a', 'hi', true)]), isFalse);
      expect(SmartReplies.worthSuggesting([msg('a', 'hi', false)]), isTrue);
      expect(
          SmartReplies.worthSuggesting(
              [msg('a', 'hi', false), msg('b', 'hello', true)]),
          isFalse,
          reason: 'you spoke last');
    });

    test('the transcript stays inside the model\'s context window', () {
      // The on-device model has about 4,000 tokens for the prompt AND the
      // answer together. A long conversation must not be able to overrun it —
      // this is the check that the cap is real rather than aspirational.
      final many = [
        for (var i = 0; i < 500; i++)
          Message(
              id: 'm$i',
              text: 'A message of some length, number $i, with words in it.',
              time: DateTime.now().subtract(Duration(minutes: 500 - i)),
              isMe: i.isEven),
      ];
      final transcript = SmartReplies.transcriptFor(many, 'Bob');
      expect(transcript.length, lessThanOrEqualTo(4000));
      expect(transcript.split('\n').length, lessThanOrEqualTo(20));
      // And it keeps the RECENT end — the old end is what may be dropped.
      expect(transcript, contains('number 499'));
      expect(transcript, isNot(contains('number 0,')));
    });

    test('one long message cannot eat the whole budget', () {
      final wall = Message(
          id: 'w',
          text: 'x' * 20000,
          time: DateTime.now(),
          isMe: false);
      final transcript = SmartReplies.transcriptFor([wall], 'Bob');
      expect(transcript.length, lessThan(600),
          reason: 'a pasted wall of text is trimmed, not passed whole');
    });

    test('the transcript says who wrote each line', () {
      final messages = [
        Message(
            id: 'a',
            text: 'are you free tomorrow',
            time: DateTime.now(),
            isMe: false),
      ];
      expect(SmartReplies.transcriptFor(messages, 'Bob'),
          'Bob: are you free tomorrow');
      expect(SmartReplies.transcriptFor(messages, ''), 'Them: are you free tomorrow',
          reason: 'a nameless contact still needs a label');
    });

    testWidgets('a device that cannot generate suggests nothing at all',
        (t) async {
      // THE RULE THIS PROTECTS. Most iPhones have no Apple Intelligence, and
      // the web build has no channel. On those, the honest answer is silence —
      // a canned suggestion would be invented words attributed to nobody.
      SmartReplies.debugAvailableOverride = false;
      final replies = await SmartReplies.instance.suggest(
        messages: [
          Message(id: 'a', text: 'hi', time: DateTime.now(), isMe: false),
        ],
        contactName: 'Bob',
      );
      expect(replies, isEmpty);
    });

    testWidgets('blank and duplicate suggestions are dropped', (t) async {
      SmartReplies.debugAvailableOverride = true;
      SmartReplies.debugSuggestOverride = (_, __) async => [
            'Sounds good',
            '   ',
            'sounds good',
            'Can we do Friday?',
          ];
      final replies = await SmartReplies.instance.suggest(
        messages: [
          Message(id: 'a', text: 'hi', time: DateTime.now(), isMe: false),
        ],
        contactName: 'Bob',
      );
      expect(replies, ['Sounds good', 'Can we do Friday?'],
          reason: 'the model is asked for three, not promised three distinct');
    });

    testWidgets('a suggestion fills the composer and is not sent', (tester) async {
      // Tapping a guess must never put it in somebody else's chat on its own.
      final sent = <String>[];
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: Column(children: [
            const Spacer(),
            ChatInputBar(
              onSend: sent.add,
              suggestedReplies: const ['Sounds good', 'Can we do Friday?'],
            ),
          ]),
        ),
      ));
      await tester.pumpAndSettle();

      await tester.tap(find.text('Sounds good'));
      await tester.pumpAndSettle();

      expect(sent, isEmpty, reason: 'a tapped suggestion is a draft, not a send');
      expect(find.widgetWithText(TextField, 'Sounds good'), findsOneWidget);
      // And once there is text, the alternatives get out of the way.
      expect(find.text('Can we do Friday?'), findsNothing);
    });
  });

  group('A channel is not a one-way street', () {
    // Posting was the only channel action that ever left the device. Deleting,
    // editing, reacting and pinning all stopped at the phone that did them —
    // so "Delete" removed a message for its author and nobody else, and a
    // moderator had no way to remove anyone else's at all.

    /// A server whose creator is the owner, with one text channel holding one
    /// message from somebody else.
    (Community, Channel) seedServer({String name = 'Guild'}) {
      final community = CommunityStore.instance.createCommunity(name);
      final channel = CommunityStore.instance
          .byId(community.id)!
          .channels
          .firstWhere((c) => c.type == ChannelType.text);
      return (CommunityStore.instance.byId(community.id)!, channel);
    }

    setUp(() {
      SharedPreferences.setMockInitialValues({});
      CommunityStore.instance.resetForTest();
    });
    tearDown(CommunityStore.instance.resetForTest);

    test('a toggle reports which way it went, because a relay cannot guess',
        () {
      final (community, channel) = seedServer();
      CommunityStore.instance.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'hello',
              time: DateTime.now(),
              isMe: true,
              status: MessageStatus.sent));

      final store = CommunityStore.instance;
      expect(store.toggleChannelReaction(community.id, channel.id, 'm1', '👍'),
          isTrue,
          reason: 'a reaction that was not there is now on');
      expect(store.toggleChannelReaction(community.id, channel.id, 'm1', '👍'),
          isFalse);
      expect(store.togglePinChannelMessage(community.id, channel.id, 'm1'),
          isTrue);
      expect(store.togglePinChannelMessage(community.id, channel.id, 'm1'),
          isFalse);
    });

    test('setting a reaction is idempotent, so two arrivals are one reaction',
        () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'hi',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered));

      store.setChannelReaction(community.id, channel.id, 'm1', '🔥', add: true);
      store.setChannelReaction(community.id, channel.id, 'm1', '🔥', add: true);
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          ['🔥'],
          reason: 'a redelivered event must not double the emoji');

      store.setChannelReaction(community.id, channel.id, 'm1', '🔥',
          add: false);
      store.setChannelReaction(community.id, channel.id, 'm1', '🔥',
          add: false);
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          isEmpty);
    });

    test('a relayed edit rewrites somebody else\'s message; a local one cannot',
        () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'theirs',
              text: 'original',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered,
              senderName: 'Ada'));

      // The local path refuses: nobody rewrites another member's words from
      // their own device.
      store.editChannelMessage(community.id, channel.id, 'theirs', 'tampered');
      expect(store.messageInChannel(community.id, channel.id, 'theirs')!.text,
          'original');

      // The relayed path is the author's own edit arriving here, so it lands.
      store.applyRemoteChannelEdit(
          community.id, channel.id, 'theirs', 'second thoughts');
      final edited =
          store.messageInChannel(community.id, channel.id, 'theirs')!;
      expect(edited.text, 'second thoughts');
      expect(edited.edited, isTrue);
      expect(edited.originalText, 'original');
    });

    test('a received chdel/chedt/chrxn/chpin actually changes the channel',
        () {
      // Through the real routing — a switch with no case for an event is
      // exactly the bug this is here to catch.
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      final secret = store.byId(community.id)!.secretBytes!;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'first',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered,
              senderName: 'Ada'));

      Map<String, dynamic> sealed(Map<String, dynamic> body) => {
            'from': '+15550102222',
            'communityId': community.id,
            'data': E2eCrypto.encrypt(secret, jsonEncode(body)),
          };
      void deliver(String event, Map<String, dynamic> body) =>
          RelayService.instance
              .debugApplyCommunityEvent(event, sealed(body), '+15550101111');

      deliver('chrxn', {
        'channelId': channel.id,
        'id': 'm1',
        'emoji': '🎉',
        'add': true,
      });
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          ['🎉']);

      deliver('chedt', {
        'channelId': channel.id,
        'id': 'm1',
        'text': 'first, actually',
      });
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.text,
          'first, actually');

      deliver('chpin', {
        'channelId': channel.id,
        'id': 'm1',
        'pinned': true,
      });
      expect(
          store
              .byId(community.id)!
              .channels
              .firstWhere((c) => c.id == channel.id)
              .pinnedMessageIds,
          contains('m1'));

      deliver('chdel', {'channelId': channel.id, 'id': 'm1'});
      expect(store.messageInChannel(community.id, channel.id, 'm1'), isNull);
      expect(
          store
              .byId(community.id)!
              .channels
              .firstWhere((c) => c.id == channel.id)
              .pinnedMessageIds,
          isEmpty,
          reason: 'a deleted message must not stay on the pin banner');
    });

    testWidgets('a moderator can remove a message that is not theirs',
        (tester) async {
      final (community, channel) = seedServer();
      CommunityStore.instance.postMessage(
