  group('Okay Score, with a shape to it', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      ScoreStore.instance.resetForTest();
    });
    tearDown(ScoreStore.instance.resetForTest);

    test('points are remembered by the day they were earned', () {
      final store = ScoreStore.instance;
      final today = DateTime(2026, 8, 1);
      store.award(10, now: today.subtract(const Duration(days: 3)));
      store.award(5, now: today.subtract(const Duration(days: 3)));
      store.award(7, now: today);

      final days = store.recentDays(now: today);
      expect(days.length, ScoreStore.historyDays);
      expect(days.last, 7, reason: 'today is the last column');
      expect(days[ScoreStore.historyDays - 4], 15, reason: 'summed per day');
      // Zeros for days nothing happened — a chart with the gaps missing lies
      // about how long the gap was.
      expect(days[ScoreStore.historyDays - 2], 0);
      expect(days.fold(0, (a, b) => a + b), 22);
      expect(store.points, 22);
    });

    test('the history does not grow forever', () {
      final store = ScoreStore.instance;
      final today = DateTime(2026, 8, 1);
      for (var i = 0; i < 100; i++) {
        store.award(1, now: today.subtract(Duration(days: i)));
      }
      expect(store.history.length, lessThanOrEqualTo(ScoreStore.historyDays),
          reason: 'a device left running must not carry a year of days');
      // And the total is untouched by forgetting the shape of it.
      expect(store.points, 100);
    });

    test('this week is the last seven days, not everything', () {
      final store = ScoreStore.instance;
      final today = DateTime(2026, 8, 1);
      store.award(50, now: today.subtract(const Duration(days: 10)));
      store.award(3, now: today.subtract(const Duration(days: 2)));
      store.award(4, now: today);
      expect(store.thisWeek, 7);
      expect(store.points, 57);
    });

    test('the new badges exist and are earned by doing the thing', () {
      final store = ScoreStore.instance;
      for (final id in ['nearby', 'relay', 'forwarder']) {
        final badge = ScoreStore.badgeById(id);
        expect(badge, isNotNull, reason: id);
        expect(store.isEarned(id), isFalse, reason: id);
      }
      store.recordFlag('sent_mesh');
      store.recordFlag('relayed_mesh');
      store.recordFlag('forwarded');
      for (final id in ['nearby', 'relay', 'forwarder']) {
        expect(store.isEarned(id), isTrue, reason: id);
      }
    });

    testWidgets('the score screen draws the fortnight', (t) async {
      t.view.physicalSize = const Size(430, 1400);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const MaterialApp(home: ScoreScreen()));
      await t.pumpAndSettle();
      expect(find.text('Last two weeks'), findsOneWidget);
      // Nothing yet rather than fourteen empty columns, which look like a
      // chart that failed to load.
      expect(find.text('Nothing yet this fortnight.'), findsOneWidget);

      ScoreStore.instance.award(12);
      await t.pumpAndSettle();
      expect(find.text('Nothing yet this fortnight.'), findsNothing);
      expect(find.textContaining('12 this week'), findsOneWidget);
    });
  });

  group('More to decide about Bluetooth and what leaves with a message', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      ScoreStore.instance.resetForTest();
    });
    tearDown(() {
      MeshService.instance.resetForTest();
      ScoreStore.instance.resetForTest();
      AppState.resetForTest();
      MeshService.debugSendOverride = null;
      MeshService.debugAvailableOverride = null;
    });

    test('a phone that will not relay still sends and receives', () {
      final sent = <String>[];
      MeshService.debugSendOverride = sent.add;
      final mesh = MeshService.instance;

      // Somebody else's packet, passing through.
      const theirs = MeshPacket(
          id: 'm1', to: '15550109999', ttl: 3, payload: {'enc': 'x'});
      mesh.debugReceive(theirs);
      expect(sent, isNotEmpty, reason: 'relaying is on by default');

      sent.clear();
      mesh.setRelayForOthers(false);
      mesh.router.reset();
      mesh.debugReceive(theirs);
      expect(sent, isEmpty, reason: 'their traffic stops here now');
    });

    test('turning off nearby discovery empties the list and keeps it empty',
        () {
      final mesh = MeshService.instance;
      const beacon = MeshPacket(
          id: 'b1', to: '', ttl: 3, kind: MeshPacket.kindServer,
          payload: {'id': 'c1', 'name': 'Cafe', 'members': 2});
      mesh.debugDeliver(beacon);
      expect(NearbyServers.instance.servers, isNotEmpty);

      mesh.setFindServers(false);
      expect(NearbyServers.instance.servers, isEmpty,
          reason: 'what was listed goes when you say stop listening');
      mesh.router.reset();
      mesh.debugDeliver(beacon);
      expect(NearbyServers.instance.servers, isEmpty);
    });

    test('a withheld score never leaves, rather than being zeroed later',
        () async {
      // Round-tripped rather than grepped: the score travels INSIDE the
      // sealed blob, so looking for it in the JSON on the wire finds nothing
      // whether it was sent or not — which is a test that passes for the
      // wrong reason.
      ChatStore.instance.reset();
      addTearDown(ChatStore.instance.reset);
      ScoreStore.instance.award(90);

      Map<String, dynamic> envelope({required bool share}) =>
          RelayService.encode(
            message: Message(
                id: 'm${share ? 1 : 2}',
                text: 'hi',
                time: DateTime(2026),
                isMe: true,
                status: MessageStatus.sent),
            fromPhone: '+15550101111',
            fromName: 'Ada',
            fromScore: share ? ScoreStore.instance.points : 0,
            toPhone: '+15550102222',
          );

      RelayService.applyIncoming(envelope(share: true),
          myPhone: '+15550102222');
      final shared = ChatStore.instance.chatWithContact('+15550101111');
      expect(shared?.contact.score, 90, reason: 'it arrives when shared');

      ChatStore.instance.reset();
      RelayService.applyIncoming(envelope(share: false),
          myPhone: '+15550102222');
      final withheld = ChatStore.instance.chatWithContact('+15550101111');
      expect(withheld?.contact.score, 0,
          reason: 'the far end never received a number to ignore');
    });

    test('the send path is the one that reads the switch', () {
      // The check has to be at the point the envelope is built, not at the
      // far end — a field that never leaves is one nobody has to be trusted
      // with.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(src.contains('AppState.shareScore.value ? ScoreStore'), isTrue);
      expect(src.contains('AppState.shareStreak.value ? streak : 0'), isTrue);
    });

    testWidgets('the Bluetooth switches appear only once it is on',
        (t) async {
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      MeshService.debugAvailableOverride = true;

      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();
      await t.scrollUntilVisible(find.text('Message people nearby'), 200);
      // Nothing to decide about a radio that is off.
      expect(find.text('Pass on other people\'s messages'), findsNothing);
      expect(find.text('Find servers nearby'), findsNothing);

      // NOT awaited: turning the mesh on talks to a method channel, and a
      // channel reply is delivered by the pump — awaiting it inside
      // testWidgets waits for a message that only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      // pump, not pumpAndSettle: the mesh beacons on a periodic timer while
      // it is on, and a tree with a repeating timer in it never settles.
      await t.pump();
      await t.pump();
      expect(find.text('Pass on other people\'s messages'), findsOneWidget);
      expect(find.text('Find servers nearby'), findsOneWidget);
      unawaited(MeshService.instance.stop());
      await t.pump();
    });

    testWidgets('signing out closes the screens above it too', (t) async {
      // The auth gate swaps its child the moment the session clears — but
      // Settings is PUSHED on top of that gate, and so is whatever opened
      // it, so the login screen appeared underneath a stack nobody had
      // closed. It looked like sign-out did nothing until the app was killed.
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await Session.instance
          .signIn(phone: '+15550101111', name: 'Ada');
      addTearDown(Session.instance.signOut);

      await t.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: Center(
              child: TextButton(
                onPressed: () => Navigator.of(context).push(MaterialPageRoute(
                    builder: (_) => const SettingsScreen())),
                child: const Text('open settings'),
              ),
            ),
          ),
        ),
      ));
      await t.tap(find.text('open settings'));
      await t.pumpAndSettle();
      expect(find.byType(SettingsScreen), findsOneWidget);

      // Two more tiles above it pushed Sign out past the bottom of even this
      // tall surface, so scrolling to it is no longer enough on its own.
      await t.scrollUntilVisible(find.text('Sign out'), 250);
      await t.ensureVisible(find.text('Sign out'));
      await t.pumpAndSettle();
      await t.tap(find.text('Sign out'));
      await t.pumpAndSettle();

      expect(Session.instance.isSignedIn, isFalse);
      expect(find.byType(SettingsScreen), findsNothing,
          reason: 'the pushed screens have to come down with the session');
      expect(find.text('open settings'), findsOneWidget,
          reason: 'back at the root, where the gate can show sign-in');
    });

    testWidgets('what rides along with a message can be turned off',
        (t) async {
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();
      await t.scrollUntilVisible(find.text('Share my Okay Score'), 200);
      expect(find.text('Share our streak'), findsOneWidget);

      await t.tap(find.text('Share my Okay Score'));
      await t.pumpAndSettle();
      expect(AppState.shareScore.value, isFalse);
    });
  });

  group('Both timelines, with more in them', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      FeedDrafts.instance.resetForTest();
      FeedStore.instance.resetForTest();
      PublicFeedStore.instance.resetForTest();
    });
    tearDown(() {
      FeedDrafts.instance.resetForTest();
      FeedStore.instance.resetForTest();
      PublicFeedStore.instance.resetForTest();
      PublicFeedStore.debugLoadOverride = null;
    });

    // --- A long post folds -------------------------------------------------

    testWidgets('a wall of text folds, and opens when asked', (t) async {
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final long = List.generate(40, (i) => 'Line $i of a very long post.')
          .join('\n');

      var maxLinesSeen = -1;
      // In a scroll view, as it is in both timelines — opened out, the text
      // is taller than the screen, which is the point of folding it.
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: SingleChildScrollView(
            child: CollapsibleText(
              text: long,
              style: const TextStyle(fontSize: 15),
              builder: (context, maxLines) {
                maxLinesSeen = maxLines ?? -1;
                return Text(long, maxLines: maxLines);
              },
            ),
          ),
        ),
      ));
      await t.pumpAndSettle();

      expect(maxLinesSeen, 10, reason: 'folded to ten lines');
      expect(find.text('Show more'), findsOneWidget);

      await t.tap(find.text('Show more'));
      await t.pumpAndSettle();
      expect(maxLinesSeen, -1, reason: 'all of it now');
      expect(find.text('Show less'), findsOneWidget);
    });

    testWidgets('a short post is not folded, and offers nothing to open',
        (t) async {
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      const short = 'Two words.';
      int? seen = 99;
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: CollapsibleText(
            text: short,
            style: const TextStyle(fontSize: 15),
            builder: (context, maxLines) {
              seen = maxLines;
              return const Text(short);
            },
          ),
        ),
      ));
      await t.pumpAndSettle();
      expect(seen, isNull, reason: 'nothing to clip');
      expect(find.text('Show more'), findsNothing,
          reason: 'a button under every short post is noise');
    });

    testWidgets('a recycled row does not inherit the last post\'s state',
        (t) async {
      // A list reuses its widgets. Without resetting, scrolling an opened
      // post off screen leaves the next one that lands in that slot opened
      // too — which reads as the app deciding what you wanted to read.
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final long = List.generate(40, (i) => 'Line $i.').join('\n');
      final other = List.generate(40, (i) => 'Other $i.').join('\n');

      Widget frame(String text) => MaterialApp(
            home: Scaffold(
              body: SingleChildScrollView(
                child: CollapsibleText(
                  key: const ValueKey('same-slot'),
                  text: text,
                  style: const TextStyle(fontSize: 15),
                  builder: (context, maxLines) =>
                      Text(text, maxLines: maxLines),
                ),
              ),
            ),
          );

      await t.pumpWidget(frame(long));
      await t.pumpAndSettle();
      await t.tap(find.text('Show more'));
      await t.pumpAndSettle();
      expect(find.text('Show less'), findsOneWidget);

      await t.pumpWidget(frame(other));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsOneWidget,
          reason: 'a different post starts folded');
    });

    testWidgets('a body is measured in the font it is drawn in', (t) async {
      // The style handed in carries a size and no family, because the family
      // — and the letter spacing, and the rest — come from the ambient
      // DefaultTextStyle, which is what Text.rich merges against when it
      // draws. Measuring the bare style measured a different typeface from
      // the one on screen, so the SAME body folded on one timeline and not
      // the other: the server feed showed "Show more" under five lines.
      Widget frame(double spacing) => MaterialApp(
            home: Scaffold(
              body: DefaultTextStyle(
                style: TextStyle(fontSize: 15, letterSpacing: spacing),
                child: SizedBox(
                  width: 300,
                  child: CollapsibleText(
                    text: 'One short line of a post, and then a second.',
                    style: const TextStyle(fontSize: 15),
                    maxLines: 4,
                    builder: (context, maxLines) => Text(
                        'One short line of a post, and then a second.',
                        maxLines: maxLines),
                  ),
                ),
              ),
            ),
          );

      await t.pumpWidget(frame(0));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsNothing,
          reason: 'it fits, so there is nothing to unfold');

      // Same text, same passed style, ambient type that makes it far wider.
      await t.pumpWidget(frame(20));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsOneWidget,
          reason: 'it no longer fits, and the measurement has to know that');
    });

    test('both feeds fold through the same widget', () {
      // Two feeds that drifted apart is the thing this is here to stop; they
      // render their bodies through different tag-highlighting widgets, so
      // without one shared piece the fold would only ever be on one of them.
      for (final path in [
        'lib/screens/feed_screen.dart',
        'lib/screens/public_feed_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src.contains('FeedBodyText('), isTrue, reason: path);
      }
      expect(
          File('lib/widgets/feed_post_parts.dart')
              .readAsStringSync()
              .contains('CollapsibleText('),
          isTrue);
    });

    // --- A draft survives leaving -----------------------------------------

    test('what you typed and did not post is still there', () {
      final drafts = FeedDrafts.instance;
      expect(drafts.read(FeedDrafts.publicKey), '');

      drafts.write(FeedDrafts.publicKey, 'half a thought');
      expect(drafts.read(FeedDrafts.publicKey), 'half a thought');
      expect(drafts.has(FeedDrafts.publicKey), isTrue);

      // Emptying the box is not a draft to tidy up later.
      drafts.write(FeedDrafts.publicKey, '   ');
      expect(drafts.has(FeedDrafts.publicKey), isFalse);
    });

    test('a reply draft does not turn up in somebody else\'s box', () {
      final drafts = FeedDrafts.instance;
      drafts.write(FeedDrafts.replyKey('p1'), 'to Ada');
      drafts.write(FeedDrafts.replyKey('p2'), 'to Grace');
      drafts.write(FeedDrafts.serverKey('c1'), 'to the server');
      drafts.write(FeedDrafts.publicKey, 'to everyone');

      expect(drafts.read(FeedDrafts.replyKey('p1')), 'to Ada');
      expect(drafts.read(FeedDrafts.replyKey('p2')), 'to Grace');
      expect(drafts.read(FeedDrafts.serverKey('c1')), 'to the server');
      expect(drafts.read(FeedDrafts.publicKey), 'to everyone');
      expect(drafts.read(FeedDrafts.serverKey('c2')), '');
    });

    test('abandoned drafts do not pile up forever', () {
      final drafts = FeedDrafts.instance;
      for (var i = 0; i < FeedDrafts.maxDrafts + 30; i++) {
        drafts.write(FeedDrafts.replyKey('p$i'), 'draft $i');
      }
      expect(drafts.count, FeedDrafts.maxDrafts);
      // Oldest out first: the newest is kept, the first is gone.
      expect(drafts.has(FeedDrafts.replyKey('p0')), isFalse);
      expect(
          drafts.read(
              FeedDrafts.replyKey('p${FeedDrafts.maxDrafts + 29}')),
          'draft ${FeedDrafts.maxDrafts + 29}');
    });

    testWidgets('the public composer opens with what you left in it',
        (t) async {
      t.view.physicalSize = const Size(430, 1000);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      PublicFeedStore.debugLoadOverride = () async => [];
      FeedDrafts.instance.write(FeedDrafts.publicKey, 'left half-written');

      await t.pumpWidget(const MaterialApp(home: PublicFeedScreen()));
      await t.pumpAndSettle();
      await t.tap(find.byTooltip('New post'));
      await t.pumpAndSettle();

      expect(find.text('left half-written'), findsOneWidget,
          reason: 'backing out of a composer should not cost you the text');

      // And typing more keeps it.
      await t.enterText(find.byType(TextField).first, 'left half-written more');
      await t.pump();
      expect(FeedDrafts.instance.read(FeedDrafts.publicKey),
          'left half-written more');
    });

    test('both composers keep a draft', () {
      for (final path in [
        'lib/screens/feed_screen.dart',
        'lib/screens/public_feed_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src.contains('FeedDrafts.instance.read('), isTrue,
            reason: '$path opens without what was left in it');
        expect(src.contains('FeedDrafts.instance.clear('), isTrue,
            reason: '$path keeps the draft after posting it');
      }
    });
  });

  group('Handing a photo to somebody in the room', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      ScoreStore.instance.resetForTest();
      Session.instance.signInForTest();
    });
    tearDown(() {
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyPeople.instance.clear();
      ScoreStore.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      MeshService.debugSendOverride = null;
      MeshService.debugAvailableOverride = null;
    });

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    /// A stand-in for the radio: records what went out, and lets a test play
    /// the other phone.
    List<(String, String, Map<String, dynamic>)> wireTap() {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, payload) async {
        sent.add((to, kind, payload));
        return true;
      };
      return sent;
    }

    MeshPacket asPacket(String kind, Map<String, dynamic> payload) =>
        MeshPacket(
            id: MeshPacket.randomId(),
            to: '15550101111',
            ttl: 0,
            kind: kind,
            payload: payload);

    test('a file is never passed on through anybody else', () {
      // The whole reason this is separate from the message path. A message
      // floods because nobody knows the way; a photo is a hundred kilobytes
      // going to one person who agreed to receive it, and relaying that
      // through every phone in the room would pin four radios.
      final router = MeshRouter(myDigits: '15550109999');
      for (final kind in MeshPacket.directOnly) {
        final notMine = MeshPacket(
            id: 'x$kind',
            to: '15550102222',
            ttl: 5,
            kind: kind,
            payload: const {'id': 't1'});
        expect(router.accept(notMine), MeshAction.drop,
            reason: '$kind was relayed');
      }
      // Addressed here, it is delivered — and still not relayed.
      const mine = MeshPacket(
          id: 'mine',
          to: '15550109999',
          ttl: 5,
          kind: MeshPacket.kindChunk,
          payload: {'id': 't1'});
      expect(router.accept(mine), MeshAction.deliver);
    });

    test('an offer carries who it is from, or it cannot be answered', () async {
      final sent = wireTap();
      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,${'A' * 200}', fileName: 'Photo');
      final (to, kind, payload) = sent.single;
      expect(to, '15550102222');
      expect(kind, MeshPacket.kindOffer);
      expect(payload['d'], isNotEmpty,
          reason: 'a packet says who it is FOR, not who it is from');
      expect(payload['c'], greaterThan(0), reason: 'how many chunks');
      // And none of the photo itself: an offer is a question.
      expect(jsonEncode(payload).contains('A' * 100), isFalse);
    });

    test('nothing moves until the far end says yes', () async {
      final sent = wireTap();
      final data = 'data:image/png;base64,${'B' * 7000}';
      final t = (await NearbyShare.instance
          .offer(ada(), data, fileName: 'Photo'))!;
      expect(t.state, TransferState.offered);
      expect(sent.where((e) => e.$2 == MeshPacket.kindChunk), isEmpty);

      // They say no.
      NearbyShare.instance.handle(
          asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': false}));
      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.declined);
      expect(sent.where((e) => e.$2 == MeshPacket.kindChunk), isEmpty,
          reason: 'not one byte to somebody who refused');
    });

    test('yes sends every chunk, and the far end can rebuild it', () async {
      final sent = wireTap();
      final data = 'data:image/png;base64,${'C' * 7000}';
      final t = (await NearbyShare.instance
          .offer(ada(), data, fileName: 'Photo'))!;
      expect(t.totalChunks, greaterThan(1), reason: 'this needs chunking');

      NearbyShare.instance.handle(
          asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': true}));
      await Future<void>.delayed(Duration.zero);

      final chunks =
          sent.where((e) => e.$2 == MeshPacket.kindChunk).toList();
      expect(chunks.length, t.totalChunks);
      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.done);

      final assembler = TransferAssembler(t.totalChunks);
      for (final c in chunks) {
        assembler.add(c.$3['i'] as int, c.$3['p'] as String);
      }
      expect(assembler.assemble(), data,
          reason: 'what arrives has to be what was sent');
    });

    test('a photo that arrives lands in the chat with whoever sent it',
        () async {
      wireTap();
      const data = 'data:image/png;base64,ABCD';
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 't1',
        'n': 'Photo',
        'c': 1,
        'k': 'image',
        'd': '15550102222',
        'w': 'Ada',
      }));
      final pending = NearbyShare.instance.pendingIncoming!;
      expect(pending.peerName, 'Ada');

      await NearbyShare.instance.accept('t1');
      NearbyShare.instance.handle(asPacket(
          MeshPacket.kindChunk, {'id': 't1', 'i': 0, 'c': 1, 'p': data}));

      expect(NearbyShare.instance.byId('t1')!.state, TransferState.done);
      final chat = ChatStore.instance.chatWithContact('15550102222');
      expect(chat, isNotNull, reason: 'a photo from somebody is from them');
      expect(chat!.messages.last.isImage, isTrue);
      expect(chat.messages.last.imageUrl, data);
      expect(ScoreStore.instance.isEarned('handoff'), isTrue);
    });

    test('an offer off the air is not trusted about anything', () {
      wireTap();
      for (final bad in <Map<String, dynamic>>[
        {'n': 'Photo', 'c': 1},
        {'id': '', 'n': 'Photo', 'c': 1},
        {'id': 'a', 'n': 'Photo', 'c': 0},
        {'id': 'b', 'n': 'Photo', 'c': -1},
        // More chunks than the ceiling allows, before a buffer is made.
        {'id': 'c', 'n': 'Photo', 'c': 100000},
      ]) {
        NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, bad));
      }
      expect(NearbyShare.instance.pendingIncoming, isNull);
      expect(NearbyShare.instance.transfers, isEmpty);
    });

    test('chunks for something never accepted are ignored', () {
      wireTap();
      NearbyShare.instance.handle(asPacket(MeshPacket.kindChunk,
          {'id': 'never-offered', 'i': 0, 'c': 1, 'p': 'x'}));
      expect(NearbyShare.instance.transfers, isEmpty,
          reason: 'a chunk cannot conjure a transfer nobody agreed to');
    });

    test('a file too big for this radio is refused at the sender', () async {
      wireTap();
      final huge = 'x' * (TransferChunks.maxLength + 1);
      expect(await NearbyShare.instance.offer(ada(), huge, fileName: 'Big'),
          isNull);
    });

    test('chunks out of order still rebuild the file', () {
      // Packets do not necessarily land in the order they were sent.
      final assembler = TransferAssembler(3);
      expect(assembler.add(2, 'ccc'), isTrue);
      expect(assembler.add(0, 'aaa'), isTrue);
      expect(assembler.assemble(), isNull, reason: 'one still missing');
      expect(assembler.add(1, 'bbb'), isTrue);
      expect(assembler.assemble(), 'aaabbbccc');
      // A retried chunk is not a second copy.
      expect(assembler.add(1, 'zzz'), isFalse);
      expect(assembler.add(9, 'out of range'), isFalse);
    });

    test('who can see you is off until you say otherwise', () async {
      expect(MeshService.instance.findable, Findable.off);
      final sent = <String>[];
      MeshService.debugSendOverride = sent.add;
      MeshService.instance.debugHelloNow();
      expect(sent, isEmpty, reason: 'a name in the air is a decision');

      await MeshService.instance.setFindable(Findable.everyone);
      sent.clear();
      MeshService.instance.debugHelloNow();
      expect(sent, isNotEmpty);
    });

    test('a hello from a stranger is ignored on "people I chat with"',
        () async {
      await MeshService.instance.setFindable(Findable.contacts);
      const stranger = MeshPacket(
          id: 'h1',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindHello,
          payload: {'d': '15550109999', 'n': 'A Stranger'});
      MeshService.instance.debugDeliver(stranger);
      expect(NearbyPeople.instance.people, isEmpty,
          reason: 'enforced here as well as at the sender — a modified app '
              'that announces itself to everyone still cannot make you list '
              'it');

      // Somebody already in a chat is listed.
      ChatStore.instance.upsert(const Chat(
        id: 'chat_15550108888',
        contact: AppUser(
            id: '15550108888',
            name: 'Ada',
            avatarColor: '#2E7D32',
            phone: '15550108888'),
        messages: [],
      ));
      MeshService.instance.debugDeliver(const MeshPacket(
          id: 'h2',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindHello,
          payload: {'d': '15550108888', 'n': 'Ada'}));
      expect(NearbyPeople.instance.people.map((p) => p.name), ['Ada']);
    });

    test('who was nearby stops being nearby', () {
      final now = DateTime(2026, 8, 1, 12);
      NearbyPeople.instance.heard(NearbyPerson(
          digits: '1', name: 'Ada', avatarColor: '#fff', heardAt: now));
      expect(NearbyPeople.instance.people, hasLength(1));
      NearbyPeople.instance.expire(now.add(NearbyPeople.linger * 2));
      expect(NearbyPeople.instance.people, isEmpty);
    });

    testWidgets('nothing lands without being asked about first', (t) async {
      wireTap();
      await t.pumpWidget(const MaterialApp(
          home: NearbyOfferHost(child: Scaffold(body: Text('home')))));
      await t.pumpAndSettle();

      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 't9',
        'n': 'Holiday.jpg',
        'c': 1,
        'k': 'image',
        'b': 240000,
        'd': '15550102222',
        'w': 'Ada',
      }));
      await t.pumpAndSettle();

      expect(find.textContaining('Ada wants to send you a photo'),
          findsOneWidget);
      // What it is and how big, because "a file" is not enough to say yes to.
      expect(find.textContaining('Holiday.jpg · 234 KB'), findsOneWidget);
      await t.tap(find.text('No thanks'));
      await t.pumpAndSettle();
      expect(NearbyShare.instance.byId('t9')!.state, TransferState.declined);
    });
  });

  group('Handing over a file or a video', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyFast.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      FileModeration.resetForTest();
      Session.instance.signInForTest();
    });
    tearDown(() {
      NearbyShare.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      NearbyFast.instance.resetForTest();
      MeshService.instance.resetForTest();
      MeshService.debugSendOverride = null;
      FileModeration.resetForTest();
    });

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    MeshPacket asPacket(String kind, Map<String, dynamic> payload) =>
        MeshPacket(
            id: MeshPacket.randomId(),
            to: '15550100',
            ttl: 0,
            kind: kind,
            payload: payload);

    var sentId = '';

    Uint8List mp4() => Uint8List.fromList([
          0, 0, 0, 24, 0x66, 0x74, 0x79, 0x70, // ....ftyp
          0x69, 0x73, 0x6F, 0x6D, // isom — a movie brand, not a HEIC one
          ...List<int>.filled(64, 7),
        ]);

    test('a video may be handed over, and still may not be uploaded', () {
      // The block everywhere else is a statement about what this app is
      // willing to STORE. Nothing is stored here — the bytes cross a link
      // between two devices that both agreed — so the reason for it does not
      // exist on this path.
      final video = mp4();
      expect(FileModeration.sniff(video), 'video');
      expect(FileModeration.inspectImage(video).allowed, isFalse);
      expect(FileModeration.inspectFile(video).allowed, isFalse);
      expect(
          FileModeration.inspectNearby(video, limit: 1 << 20).allowed, isTrue,
          reason: 'a video handed to the phone next to you uploads nothing');

      // What was never about storage still applies.
      final exe = Uint8List.fromList([0x4D, 0x5A, 1, 2, 3, 4, 5, 6]);
      expect(FileModeration.inspectNearby(exe, limit: 1 << 20).allowed, isFalse);
      final script = Uint8List.fromList([0x23, 0x21, 0x2F, 0x62, 0x69, 0x6E]);
      expect(
          FileModeration.inspectNearby(script, limit: 1 << 20).allowed, isFalse);
      FileModeration.blockHash(FileModeration.hashOf(video));
      expect(
          FileModeration.inspectNearby(video, limit: 1 << 20).allowed, isFalse,
          reason: 'a blocked hash is blocked on every path');
    });

    testWidgets('a send that could only fail is not offered', (t) async {
      // Two people in the room can be on different links. Choosing a video
      // and tapping Send at the one on Bluetooth alone used to spend a tap
      // to learn that — `offer` returned null and a snackbar explained
      // afterwards. The row says so instead, and the button is dead.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      // NOT awaited: turning the mesh on talks to a method channel, and the
      // reply is delivered by the pump — awaiting it here waits for a message
      // only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      // Bigger than Bluetooth carries, well inside the fast link — the same
      // boundary `offer` enforces.
      final big = 'data:video/mp4;base64,${'A' * 400000}';
      await t.pumpWidget(MaterialApp(
          home: NearbyShareScreen(
              dataUri: big, kind: 'video', key: const ValueKey('bt'))));
      await t.pump();

      expect(find.text('Ada'), findsOneWidget);
      expect(find.textContaining('Too big for Bluetooth'), findsOneWidget,
          reason: 'the bubble never said the file cannot cross this link');
      // No send arrow: the bubble stays an initial, visibly not a button.
      expect(find.byIcon(Icons.arrow_upward_rounded), findsNothing,
          reason: 'send was offered for a transfer that cannot happen');
    });

    testWidgets('and is offered once the link that can carry it exists',
        (t) async {
      // The other half of the same fact: nothing about the file changed, only
      // the way it would travel.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      // runAsync, not a bare await: bringing the fast link up crosses a
      // method channel, and inside testWidgets a channel reply only arrives
      // while something is pumping. Awaiting it directly waits forever.
      await t.runAsync(() async {
        NearbyFast.instance.debugMarkRunning();
        await NearbyFast.instance.notePeers(['tok-ada']);
        NearbyFast.instance.noteBody('tok-ada',
            jsonEncode({'k': 'hi', 'd': '15550102222', 'n': 'Ada'}));
      });
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue,
          reason: 'the fast link never came up, so the rest proves nothing');

      final big = 'data:video/mp4;base64,${'A' * 400000}';
      await t.pumpWidget(MaterialApp(
          home: NearbyShareScreen(
              dataUri: big, kind: 'video', key: const ValueKey('fast'))));
      await t.pump();

      expect(find.textContaining('Too big'), findsNothing);
      // Sendable: the person's bubble shows the send arrow instead of their
      // initial — the avatar IS the send button now.
      expect(find.byIcon(Icons.arrow_upward_rounded), findsOneWidget,
          reason: 'the fast link can carry this and the bubble should offer '
              'to send');
    });

    testWidgets('opening the screen shows the room, not a photo picker',
        (t) async {
      // It used to fire the system picker from a post-frame callback, so the
      // first thing between you and "has Ada appeared yet" was a full-screen
      // modal to dismiss.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      // NOT awaited: turning the mesh on talks to a method channel, and the
      // reply is delivered by the pump — awaiting it here waits for a message
      // only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      var pickerOpened = false;
      // BOTH pickers. The screen's photo path goes through PhotoPrep and its
      // file path through NearbyPick, so hooking one and not the other
      // watches a door the auto-open never used.
      PhotoPrep.debugPickOverride = () async {
        pickerOpened = true;
        return null;
      };
      NearbyPick.debugPickOverride = () async {
        pickerOpened = true;
        return null;
      };
      addTearDown(() {
        PhotoPrep.debugPickOverride = null;
        NearbyPick.debugPickOverride = null;
      });

      await t.pumpWidget(const MaterialApp(home: NearbyShareScreen()));
      await t.pump();
      await t.pump(const Duration(milliseconds: 50));

