    test('either end can stop a transfer that is already moving', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        return true;
      };

      // Receiving: accepted, then thought better of it.
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'r1',
        'n': 'Clip.mp4',
        'c': 40,
        'k': 'video',
        'd': '15550102222',
      }));
      await NearbyShare.instance.accept('r1');
      expect(NearbyShare.instance.byId('r1')!.state, TransferState.receiving);
      await NearbyShare.instance.cancel('r1');
      expect(NearbyShare.instance.byId('r1')!.state, TransferState.cancelled);
      // The other end is told, or it keeps pushing at a phone that stopped
      // listening.
      final no = sent.lastWhere((e) => e.$2 == MeshPacket.kindAnswer);
      expect(no.$3['ok'], false);
      // And what had arrived is LET GO OF, not merely ignored — a cancelled
      // 12 MB video whose slices stay in a map is a cancel that freed
      // nothing.
      expect(NearbyShare.instance.heldBuffers, 0);
      NearbyShare.instance.handle(asPacket(MeshPacket.kindChunk,
          {'id': 'r1', 'i': 0, 'c': 40, 'p': 'xxxx'}));
      expect(NearbyShare.instance.byId('r1')!.received, 0);
      expect(NearbyShare.instance.heldBuffers, 0);
    });

    test('a change of mind mid-transfer actually stops the sending', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        // The receiver says no partway through, exactly as it would arrive.
        if (p['i'] == 2) {
          NearbyShare.instance.handle(asPacket(
              MeshPacket.kindAnswer, {'id': sentId, 'ok': false}));
        }
        return true;
      };
      final data = 'data:image/png;base64,${'Z' * 30000}';
      final t = (await NearbyShare.instance
          .offer(ada(), data, fileName: 'Big.png', kind: 'image'))!;
      sentId = t.id;
      NearbyShare.instance.handle(
          asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': true}));
      await Future<void>.delayed(const Duration(milliseconds: 20));

      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.cancelled,
          reason: 'a no arriving mid-transfer used to be ignored entirely');
      final chunks = sent.where((e) => e.$2 == MeshPacket.kindChunk).length;
      expect(chunks, lessThan(t.totalChunks),
          reason: 'it kept sending after they said stop');
    });

    testWidgets('what is moving is visible wherever you are', (t) async {
      // The transfer list lives on the screen you would have SENT from, which
      // is exactly the screen a receiver is not on. Accepting a video used to
      // be the last thing that happened on screen.
      NearbyShare.debugSendOverride = (to, kind, p) async => true;
      await t.pumpWidget(const MaterialApp(
          home: NearbyOfferHost(child: Scaffold(body: Text('home')))));
      // Settle the route transition first — a half-open route absorbs
      // pointers, so a tap on the banner lands on nothing.
      await t.pumpAndSettle();
      expect(find.byType(NearbyTransferBanner), findsOneWidget);
      expect(find.textContaining('Clip.mp4'), findsNothing);

      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'b1',
        'n': 'Clip.mp4',
        'c': 10,
        'k': 'video',
        'd': '15550102222',
      }));
      await t.pumpAndSettle();
      // Through the dialog, as a person would — its barrier is part of the
      // screen the banner has to appear on.
      await t.tap(find.text('Accept'));
      await t.pumpAndSettle();
      NearbyShare.instance.handle(asPacket(
          MeshPacket.kindChunk, {'id': 'b1', 'i': 0, 'c': 10, 'p': 'aaaa'}));
      await t.pump();

      expect(find.textContaining('Clip.mp4 · Receiving 10%'), findsOneWidget);
      // And a way out of it from right there.
      await t.tap(find.text('Stop'));
      await t.pump();
      expect(NearbyShare.instance.byId('b1')!.state, TransferState.cancelled);
      expect(find.textContaining('Stopped'), findsOneWidget);
    });

    test('what the banner says about a transfer', () {
      NearbyTransfer at(TransferState state, {int received = 0}) =>
          NearbyTransfer(
              id: 'x',
              peerDigits: '1',
              peerName: 'Ada',
              fileName: 'Clip.mp4',
              totalChunks: 4,
              state: state,
              received: received);
      expect(
          NearbyTransferBanner.statusLine(
              at(TransferState.receiving, received: 1)),
          'Receiving 25%');
      expect(NearbyTransferBanner.statusLine(at(TransferState.done)), 'Done');
      expect(NearbyTransferBanner.statusLine(at(TransferState.cancelled)),
          'Stopped');
      // Every state says something — an unhandled one would be a blank pill.
      for (final state in TransferState.values) {
        expect(NearbyTransferBanner.statusLine(at(state)), isNotEmpty,
            reason: '$state');
      }
    });

    test('a picture is still shrunk to fit, so it goes either way', () {
      // The photo path resizes into the relay's budget; the file path does
      // not touch the bytes. Both exist on the screen on purpose — a photo
      // has to survive a Bluetooth-only room.
      final src = File('lib/screens/nearby_share_screen.dart').readAsStringSync();
      expect(src.contains('PhotoPrep.pickPhoto()'), isTrue);
      expect(src.contains('NearbyPick.pick(limit: _limit)'), isTrue);
    });
  });

  group('The fast link between two phones', () {
    const channel = MethodChannel('okay/nearbyfast');
    late List<MethodCall> platform;

    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyFast.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      Session.instance.signInForTest();
      AppState.resetForTest();
      platform = [];
      NearbyFast.debugAvailableOverride = true;
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (call) async {
        platform.add(call);
        return call.method == 'send' ? true : null;
      });
    });

    tearDown(() {
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, null);
      NearbyFast.debugAvailableOverride = null;
      NearbyFast.debugSendOverride = null;
      NearbyFast.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      MeshService.instance.resetForTest();
      MeshService.debugSendOverride = null;
    });

    /// The digits [Session.signInForTest] signs in as.
    const me = '15550100';

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    String hello(String digits, String name) =>
        jsonEncode({'k': 'hi', 'd': digits, 'n': name});

    /// Brings the link up with one peer already connected and named.
    Future<void> linkTo(String token, String digits, String name) async {
      NearbyFast.instance.debugMarkRunning();
      await NearbyFast.instance.notePeers([token]);
      NearbyFast.instance.noteBody(token, hello(digits, name));
    }

    test('nothing about you is in the air before a link exists', () async {
      await NearbyFast.instance.start(advertise: true);
      final start = platform.singleWhere((c) => c.method == 'start');
      final token = (start.arguments as Map)['token'] as String;

      expect(token, matches(RegExp(r'^[0-9a-f]{16}$')));
      expect(token.contains(me), isFalse,
          reason: 'a phone number is not an advertising name');
      expect(jsonEncode(start.arguments).contains('You'), isFalse,
          reason: 'nor is a name');

      // And it is different next time, so it is not a handle that follows
      // somebody between rooms.
      await NearbyFast.instance.stop();
      platform.clear();
      await NearbyFast.instance.start(advertise: true);
      final second = (platform.singleWhere((c) => c.method == 'start')
          .arguments as Map)['token'] as String;
      expect(second, isNot(token));
    });

    test('a peer cannot be addressed until it says who it is', () async {
      final sent = <(String, String)>[];
      NearbyFast.debugSendOverride = (to, body) => sent.add((to, body));
      NearbyFast.instance.debugMarkRunning();

      await NearbyFast.instance.notePeers(['tok-ada']);
      expect(NearbyFast.instance.hasPeer('15550102222'), isFalse,
          reason: 'a token is not a person');
      expect(await NearbyFast.instance.send('15550102222', MeshPacket.kindOffer,
              const {'id': 'x'}),
          isFalse);

      NearbyFast.instance.noteBody('tok-ada', hello('15550102222', 'Ada'));
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue);
      expect(NearbyFast.instance.peerDigits, ['15550102222']);
    });

    test('a hello from a token with no link is ignored', () {
      NearbyFast.instance.debugMarkRunning();
      NearbyFast.instance.noteBody('never-linked', hello('15550109999', 'Mal'));
      expect(NearbyFast.instance.hasPeer('15550109999'), isFalse);
    });

    test('a hello has to look like a person, or it is dropped', () async {
      NearbyFast.instance.debugMarkRunning();
      await NearbyFast.instance.notePeers(['tok']);
      for (final body in [
        jsonEncode({'k': 'hi', 'd': '', 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': 'not-digits', 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': 12345, 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': '1' * 60, 'n': 'A'}),
        jsonEncode({'k': 'something-else', 'd': '15550102222'}),
        'not json at all',
      ]) {
        expect(NearbyFast.instance.noteBody('tok', body), isFalse,
            reason: 'accepted $body');
      }
      expect(NearbyFast.instance.peerDigits, isEmpty);
    });

    test('hiding stops the fast link volunteering who you are', () async {
      final sent = <(String, String)>[];
      NearbyFast.debugSendOverride = (to, body) => sent.add((to, body));

      NearbyFast.instance.debugMarkRunning(advertising: false);
      await NearbyFast.instance.notePeers(['tok']);
      expect(sent, isEmpty,
          reason: 'somebody who is not findable is not findable here either');

      NearbyFast.instance.resetForTest();
      NearbyFast.instance.debugMarkRunning(advertising: true);
      await NearbyFast.instance.notePeers(['tok']);
      expect(sent.single.$2.contains(me), isTrue);
    });

    test('a peer leaving takes its route with it', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue);
      await NearbyFast.instance.notePeers([]);
      expect(NearbyFast.instance.hasPeer('15550102222'), isFalse,
          reason: 'a route to somebody who walked out is a transfer that '
              'hangs');
    });

    test('a packet meant for somebody else is not opened', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      NearbyFast.instance.noteBody(
          'tok-ada',
          jsonEncode({
            'k': 'pkt',
            'kind': MeshPacket.kindOffer,
            'to': '15550109999',
            'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
          }));
      expect(NearbyShare.instance.transfers, isEmpty);
    });

    test('only a transfer may cross the fast link', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      for (final kind in [
        MeshPacket.kindMessage,
        MeshPacket.kindCommunity,
        MeshPacket.kindHello,
        MeshPacket.kindServer,
        'made-up',
      ]) {
        expect(
            NearbyFast.instance.noteBody(
                'tok-ada',
                jsonEncode({
                  'k': 'pkt',
                  'kind': kind,
                  'to': me,
                  'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
                })),
            isFalse,
            reason: '$kind crossed a link that carries files only');
      }
      expect(NearbyShare.instance.transfers, isEmpty,
          reason: 'this carries files, not the message bus');

      // The kinds it is for do get through.
      expect(
          NearbyFast.instance.noteBody(
              'tok-ada',
              jsonEncode({
                'k': 'pkt',
                'kind': MeshPacket.kindOffer,
                'to': me,
                'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
              })),
          isTrue);
      expect(NearbyShare.instance.pendingIncoming?.id, 't1');
    });

    test('a transfer over the fast link is cut into far bigger pieces',
        () async {
      final data = 'data:image/png;base64,${'D' * 90000}';
      NearbyShare.debugSendOverride = (to, kind, p) async => true;

      final slow =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(slow.fast, isFalse);

      NearbyShare.instance.resetForTest();
      await linkTo('tok-ada', '15550102222', 'Ada');
      final fast =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(fast.fast, isTrue);
      expect(fast.totalChunks, lessThan(slow.totalChunks ~/ 5),
          reason: 'the four-kilobyte ceiling is a Bluetooth ceiling');
    });

    test('a file sent in big pieces still rebuilds exactly', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        return true;
      };
      await linkTo('tok-ada', '15550102222', 'Ada');
      final data = 'data:image/png;base64,${'E' * 90000}';
      final t =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      NearbyShare.instance.handle(MeshPacket(
          id: 'a1',
          to: me,
          ttl: 0,
          kind: MeshPacket.kindAnswer,
          payload: {'id': t.id, 'ok': true}));
      await Future<void>.delayed(Duration.zero);

      final chunks = sent.where((e) => e.$2 == MeshPacket.kindChunk).toList();
      expect(chunks, hasLength(t.totalChunks));
      final assembler = TransferAssembler(t.totalChunks);
      for (final c in chunks) {
        assembler.add(c.$3['i'] as int, c.$3['p'] as String);
      }
      expect(assembler.assemble(), data);
    });

    test('the fast link is used when it is there, Bluetooth when it is not',
        () async {
      final fast = <(String, String)>[];
      final bluetooth = <String>[];
      NearbyFast.debugSendOverride = (to, body) => fast.add((to, body));
      MeshService.debugSendOverride = bluetooth.add;

      // Nobody linked: it goes over the radio.
      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(fast, isEmpty);
      expect(bluetooth, isNotEmpty);

      // Linked: it goes over the link, and not over the radio.
      NearbyShare.instance.resetForTest();
      bluetooth.clear();
      await linkTo('tok-ada', '15550102222', 'Ada');
      fast.clear();
      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(fast, hasLength(1));
      expect(bluetooth, isEmpty);
    });

    test('a link that refuses a packet falls back to Bluetooth', () async {
      final bluetooth = <String>[];
      MeshService.debugSendOverride = bluetooth.add;
      await linkTo('tok-ada', '15550102222', 'Ada');
      // The route is known, but the platform says no — a peer that dropped
      // between the peer list and the send.
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (call) async => false);

      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(bluetooth, isNotEmpty,
          reason: 'a transfer does not fail because the quick way did');
    });

    test('newer iOS APIs are guarded, because the app still ships to 13', () {
      // TWICE NOW. CXProviderConfiguration() and then
      // UNNotificationPresentationOptions.banner — both iOS 14, both compile
      // fine to read, both failed the archive on Codemagic minutes after a
      // green suite. There is no Xcode here, so this is the only place the
      // mistake can be caught before a build.
      final pbx =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      final target = RegExp(r'IPHONEOS_DEPLOYMENT_TARGET = ([0-9.]+);')
          .firstMatch(pbx)!
          .group(1)!;
      final major = int.parse(target.split('.').first);
      if (major >= 14) return; // the guards stop being necessary

      // Symbols that do not exist below iOS 14 (or, for setBadgeCount, 16).
      // Not exhaustive — it is the list of ones this codebase has actually
      // reached for.
      const needsFourteen = [
        '.banner',
        '.list',
        'CXProviderConfiguration()',
        'setBadgeCount(',
      ];

      for (final file in Directory('ios/Runner')
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.swift'))) {
        // Comments talk about these on purpose; only real code counts.
        final lines = [
          for (final line in file.readAsLinesSync())
            line.contains('//') ? line.substring(0, line.indexOf('//')) : line
        ];
        for (var i = 0; i < lines.length; i++) {
          for (final symbol in needsFourteen) {
            if (!lines[i].contains(symbol)) continue;
            final from = i - 10 < 0 ? 0 : i - 10;
            // Any #available(iOS …) counts: the symbols here span iOS 14
            // (.banner) to 16 (setBadgeCount), and each is guarded at its
            // own floor.
            final guarded = lines
                .sublist(from, i + 1)
                .any((l) => l.contains('#available(iOS 1'));
            expect(guarded, isTrue,
                reason: '${file.path}:${i + 1} uses $symbol with no '
                    '#available(iOS …) above it, and the target is $target');
          }
        }
      }
    });

    test('the Bonjour service the app browses is the one it declares', () {
      // iOS 14 and later refuses to browse a service that is not listed in
      // NSBonjourServices, silently — the peer list just stays empty.
      final swift = File('ios/Runner/NearbyFast.swift').readAsStringSync();
      final type = RegExp(r'serviceType = "([a-z0-9-]+)"')
          .firstMatch(swift)!
          .group(1)!;
      final plist = File('ios/Runner/Info.plist').readAsStringSync();
      for (final proto in ['tcp', 'udp']) {
        expect(plist.contains('<string>_$type._$proto</string>'), isTrue,
            reason: 'Info.plist does not declare _$type._$proto');
      }
      expect(plist.contains('NSLocalNetworkUsageDescription'), isTrue,
          reason: 'iOS shows this before the first browse, and refuses '
              'without it');
    });
  });
  group('push self-test', () {
    // A push that never arrives has six different causes and one appearance.
    // These lock down that the report names which one, because the whole
    // reason it exists is that a dashboard cannot tell anybody.

    PushCheck check({
      bool p8 = true,
      bool keyId = true,
      bool teamId = true,
      String bundleId = 'com.okaymessaging',
      bool sandbox = false,
      String keyError = '',
      String prodReason = 'BadDeviceToken',
      String sandboxReason = 'BadDeviceToken',
      bool registered = true,
    }) =>
        PushCheck.fromJson({
          'secrets': {
            'p8': p8,
            'keyId': keyId,
            'teamId': teamId,
            'bundleId': bundleId,
            'sandbox': sandbox,
          },
          'keyError': keyError,
          'production': {
            'host': 'api.push.apple.com',
            'status': 400,
            'reason': prodReason,
          },
          'sandbox': {
            'host': 'api.sandbox.push.apple.com',
            'status': 400,
            'reason': sandboxReason,
          },
          'device': {'registered': registered},
        })!;

    (String, bool) verdict(PushCheck? c,
            {bool releaseBuild = true,
            bool pushable = true,
            String? error,
            bool signedIn = true}) =>
        PushSelfTest.verdictFor(
          relayEnabled: true,
          signedIn: signedIn,
          releaseBuild: releaseBuild,
          pushablePlatform: pushable,
          check: c,
          error: error,
        );

    test('Apple accepting the made-up token is the pass', () {
      // BadDeviceToken is the *good* answer: Apple validates the provider
      // token, then the topic, then the device token, so rejecting only the
      // last one means it approved the key, the team and the app.
      final (text, faulty) = verdict(check());
      expect(faulty, isFalse);
      expect(text, contains('set up correctly'));
    });

    test('a rejected signing key names the three secrets that make it', () {
      final (text, faulty) = verdict(check(prodReason: 'InvalidProviderToken'));
      expect(faulty, isTrue);
      expect(text, contains('APNS_KEY_ID'));
      expect(text, contains('APNS_TEAM_ID'));
      expect(text, contains('APNS_P8'));
      // And must not send somebody after the bundle id, which Apple never
      // got as far as reading.
      expect(text, isNot(contains('APNS_BUNDLE_ID')));
    });

    test('a disallowed topic blames the bundle id and nothing else', () {
      final (text, faulty) =
          verdict(check(bundleId: 'com.wrong.app', prodReason: 'TopicDisallowed'));
      expect(faulty, isTrue);
      expect(text, contains('APNS_BUNDLE_ID'));
      expect(text, contains('com.wrong.app'));
      expect(text, isNot(contains('APNS_P8')));
    });

    test('a p8 that is set but unreadable is not reported as missing', () {
      // "Not set" would send somebody back to Apple for a key they already
      // have, when the fault is how it was pasted.
      final (text, _) = verdict(check(keyError: 'Invalid keyData'));
      expect(text, contains('cannot be read'));
      expect(text, contains('BEGIN'));
      expect(text, isNot(contains('is not set')));
    });

    test('missing secrets are named individually', () {
      expect(verdict(check(p8: false)).$1, contains('APNS_P8 is not set'));
      expect(verdict(check(keyId: false)).$1,
          allOf(contains('APNS_KEY_ID'), isNot(contains('APNS_TEAM_ID'))));
      expect(verdict(check(teamId: false)).$1,
          allOf(contains('APNS_TEAM_ID'), isNot(contains('APNS_KEY_ID'))));
    });

    test('an expired sign-in is named, not dumped as an exception', () {
      // The report used to say "Signed in ✓ This device has a session" one
      // line above "unauthorized ✗" — both true, together a contradiction
      // that dumped a raw FunctionException at whoever opened the screen.
      // A local session the server refuses is an EXPIRED sign-in, and the
      // fix worth saying is sign out, sign back in.
      final (text, faulty) = verdict(null, error: PushSelfTest.kSessionExpired);
      expect(faulty, isTrue);
      expect(text, contains('expired'));
      expect(text.toLowerCase(), contains('sign out'));
      expect(text, isNot(contains('FunctionException')));

      final steps = PushSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        releaseBuild: true,
        pushablePlatform: true,
        check: null,
        error: PushSelfTest.kSessionExpired,
      );
      final signedIn = steps.firstWhere((s) => s.title == 'Signed in');
      expect(signedIn.state, CheckState.fail,
          reason: 'a session the server refuses is not a green tick');
      expect(signedIn.detail, contains('expired'));

      // And the mapping recognises what the client actually throws.
      expect(PushSelfTest.isAuthFailure(StateError('the server answered 401')),
          isTrue);
      expect(PushSelfTest.isAuthFailure(StateError('the server answered 500')),
          isFalse);
    });

    test('sandbox is judged against the build that is asking', () {
      // The failure this exists for: every secret correct, APNS_SANDBOX left
      // on, and a TestFlight build receiving nothing for ever.
      final release = verdict(check(sandbox: true), releaseBuild: true);
      expect(release.$2, isTrue);
      expect(release.$1, contains('APNS_SANDBOX'));
      expect(release.$1, contains('production'));

      // The same setting is correct for a build installed from Xcode, so it
      // must not be reported as a fault there.
      expect(verdict(check(sandbox: true), releaseBuild: false).$2, isFalse);

      // And the mirror image: a debug build against production APNs is worth
      // saying, but it is not somebody's setup being wrong.
      final debugOnProd = verdict(check(), releaseBuild: false);
      expect(debugOnProd.$2, isFalse);
      expect(debugOnProd.$1, contains('Xcode'));
    });

    test('the sandbox flag decides which of Apple\'s answers counts', () {
      // Both hosts are asked, but only the one the server actually sends to
      // can decide the verdict.
      expect(check(sandbox: true, sandboxReason: 'InvalidProviderToken').active
          .reason, 'InvalidProviderToken');
      expect(verdict(check(
              sandbox: true,
              prodReason: 'BadDeviceToken',
              sandboxReason: 'InvalidProviderToken'),
          releaseBuild: false)
          .$2, isTrue);
    });

    test('a phone that never registered is separated from a bad secret', () {
      final (text, faulty) = verdict(check(registered: false));
      expect(faulty, isTrue);
      expect(text, contains('never uploaded'));
      // The secrets are fine, and saying otherwise would send somebody to
      // the wrong dashboard.
      expect(text, contains('secret is right'));

      // On a build that cannot receive one at all, that is not a fault.
      final web = verdict(check(registered: false), pushable: false);
      expect(web.$2, isFalse);
    });

    test('iOS refusing a token is told apart from permission never asked', () {
      (String, bool) v({String? regError, bool token = false, String? up}) =>
          PushSelfTest.verdictFor(
            relayEnabled: true,
            signedIn: true,
            releaseBuild: true,
            pushablePlatform: true,
            check: check(registered: false),
            error: null,
            tokenReceived: token,
            registrationError: regError,
            uploadError: up,
          );

      // The entitlement failure has exactly one fix and it is not on the
      // phone: the build was signed without push. Sending somebody to iOS
      // Settings for it wastes their toggle and their trust.
      final entitlement = v(
          regError: 'no valid \'aps-environment\' entitlement string found '
              'for application');
      expect(entitlement.$2, isTrue);
      expect(entitlement.$1, contains('entitlement'));
      expect(entitlement.$1.toLowerCase(), contains('build'));
      expect(entitlement.$1, isNot(contains('Allow notifications')),
          reason: 'Settings cannot fix a binary signed without push');

      // Any other refusal at least shows its reason instead of guessing.
      expect(v(regError: 'simulator').$1, contains('simulator'));

      // A token that arrived but never stuck server-side is an upload
      // fault, and the reason it failed is the whole diagnosis.
      final upload = v(token: true, up: 'row-level security');
      expect(upload.$2, isTrue);
      expect(upload.$1, contains('uploading'));
      expect(upload.$1, contains('row-level security'));

      // And the steps say the same thing the verdict does.
      List<DiagnosticStep> steps(
              {String? regError, bool token = false, String? up}) =>
          PushSelfTest.stepsFor(
            relayEnabled: true,
            signedIn: true,
            releaseBuild: true,
            pushablePlatform: true,
            check: check(registered: false),
            error: null,
            tokenReceived: token,
            registrationError: regError,
            uploadError: up,
          );
      DiagnosticStep tokenStep(List<DiagnosticStep> s) =>
          s.firstWhere((x) => x.title == 'This device\'s token');
      expect(tokenStep(steps(regError: 'aps-environment ...')).detail,
          contains('new build'));
      expect(tokenStep(steps(token: true, up: 'denied')).detail,
          contains('denied'));
      expect(tokenStep(steps()).detail, contains('Allow notifications'));

      // The native side reports the refusal at all — the failure used to be
      // swallowed, which left this screen guessing about permissions.
      final swift =
          File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift, contains('didFailToRegisterForRemoteNotificationsWithError'));
      expect(swift, contains('"tokenError"'));
      final dart = File('lib/state/push_service.dart').readAsStringSync();
      expect(dart, contains('tokenError'));
    });

    test('an old deployment is told apart from a broken one', () {
      // push-send before this change answers { sent: false } — a valid reply
      // that is not a self-test. Reading it as "no secrets set" would be a
      // confident wrong answer.
      expect(PushCheck.fromJson({'sent': false}), isNull);
      expect(PushCheck.fromJson(null), isNull);
      final (text, faulty) = verdict(null, error: 'old-deployment');
      expect(faulty, isTrue);
      expect(text, contains('push-send'));
      expect(text, contains('docs/edge_functions_paste/push-send.ts'));
    });

    test('the steps never carry a secret\'s value', () {
      // The report is written to be pasted into a message, so the server may
      // only ever say whether a secret is set — never what it is.
      final src =
          File('supabase/functions/push-send/index.ts').readAsStringSync();
      final body = src.substring(src.indexOf('async function checkSetup'),
          src.indexOf('Deno.serve'));
      for (final name in ['APNS_P8', 'APNS_KEY_ID', 'APNS_TEAM_ID']) {
        expect(body.contains('present("$name")'), isTrue,
            reason: '$name must be reported as a boolean');
        expect(RegExp('Deno\\.env\\.get\\("$name"\\)').hasMatch(body), isFalse,
            reason: '$name must never reach the response');
      }
      // And it must not deliver anything while checking: the device token is
      // one nobody owns.
      expect(body.contains('"0".repeat(64)'), isTrue);
    });

    testWidgets('the report says which link is broken', (t) async {
      addTearDown(() => PushSelfTest.debugCheckProbe = null);
      // Tall enough that the verdict below seven steps is built at all — a
      // ListView does not build what is off screen, and a finder cannot see
      // what was never built.
      t.view.physicalSize = const Size(1000, 2400);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.reset);
      PushSelfTest.debugCheckProbe = () async => {
            'secrets': {
              'p8': true,
              'keyId': true,
              'teamId': true,
              'bundleId': 'com.okaymessaging',
              'sandbox': false,
            },
            'keyError': '',
            'production': {
              'host': 'api.push.apple.com',
              'status': 403,
              'reason': 'InvalidProviderToken',
            },
            'sandbox': {
              'host': 'api.sandbox.push.apple.com',
              'status': 403,
              'reason': 'InvalidProviderToken',
            },
            'device': {'registered': true},
          };

      final steps = PushSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        releaseBuild: true,
        pushablePlatform: true,
        check: PushCheck.fromJson(await PushSelfTest.debugCheckProbe!()),
        error: null,
      );
      await t.pumpWidget(MaterialApp(
        home: SelfTestScreen(
          title: 'Check push setup',
          run: () async => SelfTestReport(
            title: 'Push self-test',
            steps: steps,
            verdict: PushSelfTest.verdictFor(
              relayEnabled: true,
              signedIn: true,
              releaseBuild: true,
              pushablePlatform: true,
              check: PushCheck.fromJson(await PushSelfTest.debugCheckProbe!()),
              error: null,
            ).$1,
            faulty: true,
          ),
        ),
      ));
      await t.pumpAndSettle();

      expect(find.text('What to change'), findsOneWidget);
      expect(find.text('Apple'), findsOneWidget);
      expect(find.textContaining('Rejected the signing key'), findsOneWidget);
      // The steps that are fine must still say so, or the one that is not
      // does not stand out.
      expect(find.textContaining('Set, and it signs.'), findsOneWidget);
    });

    test('a pasted report names the test it came from', () {
      const r = SelfTestReport(
          title: 'Push self-test',
          steps: [DiagnosticStep('Apple', 'accepted', CheckState.pass)],
          verdict: 'fine',
          faulty: false);
      expect(r.report.split('\n').first, 'Push self-test');
      expect(r.report, contains('[ok]   Apple: accepted'));
    });

    testWidgets('the plumbing checks exist for admins and for nobody else',
        (t) async {
      // The verdicts name Supabase secrets, APNs keys and TURN config —
      // operator vocabulary. A tester or user never sees the rows; the
      // same server-driven role that opens the moderation console (one
      // rank stricter) is what reveals them.
      PlatformModeration.instance.debugSet(role: PlatformRole.admin);
      addTearDown(PlatformModeration.instance.resetForTest);
      await t.pumpWidget(const MaterialApp(home: SettingsScreen()));
      await t.pump(const Duration(milliseconds: 100));
      await t.scrollUntilVisible(find.text('Check push setup'), 240,
          scrollable: find.byType(Scrollable).first);
      expect(find.text('Check push setup'), findsOneWidget);
      expect(find.text('Check call setup'), findsOneWidget);
      expect(find.text('Check live delivery'), findsOneWidget);

      // And the gate really is the admin one: the three rows live inside
      // the canAdminister branch, after the plain notification tiles.
      final src = File('lib/screens/settings_screen.dart').readAsStringSync();
      final gate = src.indexOf('canAdminister');
      expect(gate, greaterThan(-1));
      for (final title in [
        "'Check call setup'",
        "'Check push setup'",
        "'Check live delivery'",
      ]) {
        expect(src.indexOf(title), greaterThan(gate),
            reason: '$title must sit behind the admin gate');
      }
    });
  });
  group('the ID check does not depend on a page of ours', () {
    // What this is about: identity.html is a static file on GitHub Pages, and
    // GitHub's own branch build republishes the repository's README over the
    // app for minutes after every push. A check started in that window showed
    // GitHub's "File not found" page under the words "Verify your identity",
    // with no way forward. Stripe hosts the same check itself, so the app
    // stopped needing a page of its own.

    test('by default nothing of ours is in the path at all', () {
      // No secret means the screen loads Stripe's hosted flow. Asserted
      // against the shipped constant rather than a literal, so turning the
      // default around would fail here rather than silently reinstate the
      // dependency.
      expect(preferHostedIdentity, isTrue);
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: true,
              preferHosted: preferHostedIdentity),
          isEmpty,
          reason: 'even a page that IS being served is not used by default');
    });

    test('a missing page falls back to Stripe\'s hosted flow', () {
      // The opt-in embedded path still checks. Dropping the secret is the
      // fallback: the screen runs Stripe.js only when it has one.
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: false,
              preferHosted: false),
          isEmpty);
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: true,
              preferHosted: false),
          'vs_secret',
          reason: 'opted in, and the page is there — run the themed flow');
    });

    test('with nothing to fall back to, the secret is kept', () {
      // Stripe returned no hosted URL. Dropping the secret here would turn a
      // check that works into no check at all, which is worse than an
      // unthemed one — so this outranks even preferring the hosted flow.
      for (final prefer in [true, false]) {
        expect(
            IdentityVerification.secretFor(
                secret: 'vs_secret',
                hostedUrl: '',
                pageServed: false,
                preferHosted: prefer),
            'vs_secret');
      }
    });

    test('the page probe decides, and an unanswered probe fails closed', () async {
      addTearDown(() => IdentityVerification.debugPageProbe = null);
      var asked = '';
      IdentityVerification.debugPageProbe = (url) async {
        asked = url;
        return true;
      };
      expect(await IdentityVerification.pageIsServed(), isTrue);
      expect(asked, IdentityVerification.pageUrl,
          reason: 'it must probe the page it is deciding about');

      // Unreachable is not "fine": the cost of being wrong the other way is a
      // dead end inside the check.
      IdentityVerification.debugPageProbe = (_) async => false;
      expect(await IdentityVerification.pageIsServed(), isFalse);
    });

    test('there is no page of ours to point at by default', () {
      // The embedded page is a web-build artifact: it only exists wherever
      // that build is deployed, and defaulting to one particular deployment
      // is how the GitHub dependency got here in the first place. A build
      // that wants it has to say where its own copy is served from.
      expect(IdentityVerification.pageUrl, isEmpty);

      // And with no page named, the probe cannot report one as available —
      // so opting in without supplying a URL still lands on Stripe's flow
      // rather than on an empty address.
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: IdentityVerification.pageUrl.isNotEmpty,
              preferHosted: false),
          isEmpty);
    });
  });
  group('the app does not depend on GitHub', () {
    // The site those URLs pointed at republishes the repository README over
    // the app for minutes after every push, and one of them — the email
    // confirmation link — is opened in a browser on somebody else's device,
    // where the app cannot intervene at all. Everything now comes off the
    // Supabase project the app already cannot work without.

    test('nothing in the app or its functions names GitHub', () {
      // A regression test with teeth: this is the whole ask, and a single
      // pasted URL would quietly undo it.
      final offenders = <String>[];
      for (final dir in [Directory('lib'), Directory('supabase/functions')]) {
        for (final f in dir.listSync(recursive: true).whereType<File>()) {
          if (!f.path.endsWith('.dart') && !f.path.endsWith('.ts')) continue;
          if (f.readAsStringSync().contains('github.io')) {
            offenders.add(f.path);
          }
        }
      }
      expect(offenders, isEmpty,
          reason: 'these still point at GitHub Pages: $offenders');
    });

    test('the pages come off whichever Supabase project the build uses', () {
      // Derived rather than configured, so a build pointed at a different
      // project gets that project's pages without a second flag to forget.
      const project = 'https://abc.supabase.co';
      expect(AppPages.baseFor(project, ''),
          'https://abc.supabase.co/functions/v1/pages');
      expect(AppPages.subFor(AppPages.baseFor(project, ''), 'done'),
          'https://abc.supabase.co/functions/v1/pages/done');

      // A trailing slash on either side must not produce a double slash: the
      // function routes on the last path segment, and '' is not 'done'.
      expect(AppPages.baseFor('$project/', ''),
          'https://abc.supabase.co/functions/v1/pages');
      expect(AppPages.baseFor(project, 'https://okay.example/'),
          'https://okay.example');
    });

    test('SITE_URL wins, so a real domain can replace all of it', () {
      expect(AppPages.baseFor('https://abc.supabase.co', 'https://okay.example'),
          'https://okay.example');
    });

    test('with no backend there is no URL, and callers must cope', () {
      // Every test binary is this case, and so is a fully local build. An
      // empty string here is load-bearing: an empty completion prefix never
      // matches, and the share text drops the link rather than trailing off
      // after a colon.
      expect(AppPages.baseFor('', ''), isEmpty);
      expect(AppPages.subFor('', 'done'), isEmpty);
      expect(PaymentService.returnUrl, isEmpty);
      expect(IdentityVerification.returnUrl, isEmpty);
      expect(ConnectWebView.isCompletion('https://anything/', ''), isFalse,
          reason: 'an empty prefix must never swallow a navigation');
    });

    test('the server defaults to the same page the client watches for', () {
      // These are two codebases agreeing on a string. If they drift, Stripe's
      // hosted flow ends by navigating somewhere the WebView does not
      // recognise, and the user is left on a web page inside the app.
      const leaf = '/functions/v1/pages/done';
      for (final f in ['identity-start', 'payments-onboard']) {
        final src =
            File('supabase/functions/$f/index.ts').readAsStringSync();
        expect(src.contains(leaf), isTrue,
            reason: '$f no longer returns to the page the app watches for');
      }
      expect(AppPages.subFor(AppPages.baseFor('https://abc.supabase.co', ''),
          'done').endsWith(leaf), isTrue);
    });

    test('the pages function needs no session, because a browser has none', () {
      final src = File('supabase/functions/pages/index.ts').readAsStringSync();
      expect(src.contains('verify_jwt = false'), isTrue,
          reason: 'a confirmation link carries no Supabase JWT');
      // It must also read nothing and write nothing: it is the one function
      // anybody on the internet can call.
      expect(src.contains('createClient'), isFalse);
      expect(src.contains('SERVICE_ROLE'), isFalse);
    });
  });
  group('a username-only account is a chat account', () {
    // Signing up with no number is a real choice rather than a lesser one,
    // and it has one consequence that decides everything else: Supabase
    // authenticates a phone, so there is no session at all. Chat does not
    // need one — broadcast and the mailbox are both reachable with the anon
    // key — and everything that reads or writes the server does.

    setUp(Session.instance.resetForTest);
    tearDown(Session.instance.resetForTest);

    Widget gated() => const MaterialApp(
          home: PhoneGate(
            title: 'Wallet',
            reason: 'because money',
            child: Text('the real screen'),
          ),
        );

    testWidgets('an account with a number is not stopped', (t) async {
      Session.instance.signInForTest(phone: '15551230000', name: 'Ada');
      await t.pumpWidget(gated());
      await t.pumpAndSettle();
      expect(find.text('the real screen'), findsOneWidget);
      expect(find.textContaining('needs a phone number'), findsNothing);
    });

    testWidgets('an account with a code is, and is told why', (t) async {
      Session.instance
          .signInForTest(phone: AccountCode.mint(), name: 'ada', username: 'ada');
      await t.pumpWidget(gated());
      await t.pumpAndSettle();
      expect(find.text('the real screen'), findsNothing);
      expect(find.text('Wallet needs a phone number'), findsOneWidget);
      // The specific reason, not a generic one: eight screens are behind this
      // gate and each is shut for its own reason.
      expect(find.textContaining('because money'), findsOneWidget);
      // And a way forward. A gate with no way out is a dead end, and the
      // honest answer is that the number IS the account.
      expect(find.textContaining('Chats work as they are'), findsOneWidget);
    });

    testWidgets('the lock lifts the moment an account has a number',
        (t) async {
      // The gate listens rather than reading once: signing out of a
      // numberless account and into a real one must not leave the lock up.
      Session.instance.signInForTest(phone: AccountCode.mint(), name: 'ada');
      await t.pumpWidget(gated());
      await t.pumpAndSettle();
      expect(find.text('the real screen'), findsNothing);

      Session.instance.signInForTest(phone: '15551230000', name: 'Ada');
      await t.pumpAndSettle();
      expect(find.text('the real screen'), findsOneWidget);
    });

    testWidgets('as a tab body it brings no second app bar', (t) async {
      // The home screen already has one, and a bar with nothing to do
      // stacked under the real one is what scaffold: false is for.
      Session.instance.signInForTest(phone: AccountCode.mint(), name: 'ada');
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          appBar: AppBar(title: const Text('OkayMessenger')),
          body: const PhoneGate(
            title: 'Calls',
            reason: 'because ringing',
            scaffold: false,
            child: Text('the real screen'),
          ),
        ),
      ));
      await t.pumpAndSettle();
      expect(find.text('Calls needs a phone number'), findsOneWidget);
      expect(find.byType(AppBar), findsOneWidget);
      expect(find.text('OkayMessenger'), findsOneWidget);
    });

    testWidgets('the padlock on a row matches whether the row opens',
        (t) async {
      Session.instance.signInForTest(phone: AccountCode.mint(), name: 'ada');
      await t.pumpWidget(const MaterialApp(home: Scaffold(body: PhoneOnlyHint())));
      await t.pumpAndSettle();
      expect(find.byIcon(Icons.lock_outline), findsOneWidget);

      Session.instance.signInForTest(phone: '15551230000', name: 'Ada');
      await t.pumpAndSettle();
      expect(find.byIcon(Icons.lock_outline), findsNothing,
          reason: 'a padlock on a row that opens is worse than none');
    });

    testWidgets('calls and the marketplace open for a numberless account',
        (t) async {
      Session.instance.signInForTest(phone: AccountCode.mint(), name: 'ada');
      addTearDown(Session.instance.signOut);

      // Calls: no gate — a call rides the same anon-key relay as chat.
      await t.pumpWidget(
          const MaterialApp(home: Scaffold(body: CallsTab())));
      await t.pumpAndSettle();
      expect(find.text('Calls needs a phone number'), findsNothing);

      // Marketplace: opens browse-only — the grid loads, but the Sell action
      // is withheld (listing needs the wallet and the ID check).
      await t.pumpWidget(const MaterialApp(home: MarketplaceScreen()));
      await t.pumpAndSettle();
      expect(find.text('Marketplace needs a phone number'), findsNothing);
      expect(find.text('Marketplace needs a verified account'), findsNothing);
      expect(find.widgetWithText(FloatingActionButton, 'Sell'), findsNothing,
          reason: 'a numberless account browses and messages, never lists');
    });

    test('the username is the account, so it is normalised and kept', () async {
      // With no number in anybody's contacts there is nothing to match on, so
      // the handle is the only thing another person can be told and can type.
      await Session.instance.signInWithoutNumber(username: '  @Ada.Lovelace ');
      expect(Session.instance.user.value!.username, 'ada.lovelace');
      expect(Session.instance.isNumberless, isTrue);

      // And it stands in for a display name, because the account code is one
      // nobody would choose and nobody would recognise.
      expect(Session.instance.user.value!.name, 'ada.lovelace');
      expect(AccountCode.isCode(Session.instance.user.value!.phone), isTrue);

      // A name typed is still a name kept.
      await Session.instance
          .signInWithoutNumber(name: 'Ada', username: 'ada2');
      expect(Session.instance.user.value!.name, 'Ada');
    });

    test('a real number is never mistaken for one of these', () {
      Session.instance.signInForTest(phone: '15551230000', name: 'Ada');
      expect(Session.instance.isNumberless, isFalse);
      // Nor is a signed-out app, which would otherwise lock every screen
      // behind a gate nobody could pass.
      Session.instance.resetForTest();
      expect(Session.instance.isNumberless, isFalse);
    });
  });
  group('a lock on one chat', () {
    // Two things, and they are not the same thing. A LOCKED chat still has a
    // row: you can see who it is with, and not what was said. A HIDDEN one
    // has no row at all, and the only way back is its password — there is no
    // folder, no count and nothing in settings, because any of those would
    // announce that hidden chats exist, which is most of what hiding is for.

    setUp(() {
      ChatLock.instance.resetForTest();
      ChatStore.instance.reset();
      SharedPreferences.setMockInitialValues({});
    });
    tearDown(ChatLock.instance.resetForTest);

    Chat chatWith(String id, String name) => Chat(
          id: id,
          contact: AppUser(id: name, name: name, avatarColor: '#2E7D32'),
          messages: [
            Message(
                id: '${id}_m1',
                text: 'the secret',
                isMe: false,
                time: DateTime(2026, 1, 1)),
          ],
        );

    test('each chat has its own password, and one does not open another',
        () async {
      ChatStore.instance.setChats([chatWith('a', 'Ada'), chatWith('b', 'Bo')]);
      await ChatLock.instance.lock('a', 'alpha1');
      await ChatLock.instance.lock('b', 'bravo1');

      // The whole point of per-chat: knowing one tells you nothing about the
      // other, so there is no single answer that opens everything.
      expect(await ChatLock.instance.verify('a', 'alpha1'), isTrue);
      expect(await ChatLock.instance.verify('b', 'alpha1'), isFalse);
      expect(await ChatLock.instance.verify('a', 'bravo1'), isFalse);
    });

    test('the password is never stored, and two chats never share a hash',
        () async {
      ChatStore.instance.setChats([chatWith('a', 'Ada'), chatWith('b', 'Bo')]);
      await ChatLock.instance.lock('a', 'same-password');
      await ChatLock.instance.lock('b', 'same-password');
      final raw =
          (await SharedPreferences.getInstance()).getString('chat_locks_v1')!;
      expect(raw.contains('same-password'), isFalse,
          reason: 'the password itself reached the disk');

      // Per-chat salts: the same password on two chats must not produce the
      // same stored value, or the file says which locks share an answer.
      final map = jsonDecode(raw) as Map<String, dynamic>;
      expect(map['a']['hash'], isNot(map['b']['hash']));
      expect(map['a']['salt'], isNot(map['b']['salt']));
    });

    test('locking is not hiding, and the store draws the line', () async {
      ChatStore.instance.setChats([chatWith('a', 'Ada'), chatWith('b', 'Bo')]);
      await ChatLock.instance.lock('a', 'alpha1');
      ChatLock.instance.closeAll();

      // Locked but not hidden: still in the list. Somebody can see there is a
      // conversation with Ada — that is what "hidden" is a separate answer to.
      expect(ChatStore.instance.chats.map((c) => c.id), containsAll(['a', 'b']));

      await ChatLock.instance.lock('a', 'alpha1', hidden: true);
      ChatLock.instance.closeAll();
      expect(ChatStore.instance.chats.map((c) => c.id), ['b']);
      // Still there, still receiving — just not on a list.
      expect(ChatStore.instance.allChats.map((c) => c.id), containsAll(['a', 'b']));
    });

    test('archiving is not a way round hiding', () async {
      // Somebody who archived a chat and then hid it did not mean "unless you
      // look in the archive".
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      ChatStore.instance.setArchived('a', true);
      await ChatLock.instance.lock('a', 'alpha1', hidden: true);
      ChatLock.instance.closeAll();
      expect(ChatStore.instance.archivedChats, isEmpty);
      expect(ChatStore.instance.archivedCount, 0);
    });

    test('a hidden chat comes back only for its own password', () async {
      ChatStore.instance.setChats(
          [chatWith('a', 'Ada'), chatWith('b', 'Bo'), chatWith('c', 'Cy')]);
      await ChatLock.instance.lock('a', 'alpha1', hidden: true);
      await ChatLock.instance.lock('b', 'bravo1', hidden: true);
      // Locked but NOT hidden, and it matters below.
      await ChatLock.instance.lock('c', 'chuck1');
      ChatLock.instance.closeAll();

      expect(await ChatLock.instance.revealHidden('nope-nope'), isEmpty);
      expect(await ChatLock.instance.revealHidden(''), isEmpty);
      expect(ChatStore.instance.chats.map((c) => c.id), ['c'],
          reason: 'only the chat that was never hidden should be listed');

      expect(await ChatLock.instance.revealHidden('alpha1'), ['a']);
      expect(ChatStore.instance.chats.map((c) => c.id), containsAll(['a', 'c']));
      expect(ChatStore.instance.chats.map((c) => c.id), isNot(contains('b')),
          reason: 'the wrong hidden chat came back too');

      // The search path opens HIDDEN chats only. A locked-but-visible chat
      // already has a row to tap, and letting its password work here too
      // would be a second door that skips the row's own prompt.
      ChatLock.instance.closeAll();
      expect(await ChatLock.instance.revealHidden('chuck1'), isEmpty);
      expect(ChatLock.instance.isOpen('c'), isFalse);
    });

    test('the unlock lasts the session and no longer', () async {
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1');
      // Locking opens it: being asked to prove who you are immediately after
      // setting the password is the lock arguing with the person who set it.
      expect(ChatLock.instance.isOpen('a'), isTrue);

      ChatLock.instance.closeAll();
      expect(ChatLock.instance.isOpen('a'), isFalse);
      expect(await ChatLock.instance.open('a', 'wrong-one'), isFalse);
      expect(ChatLock.instance.isOpen('a'), isFalse);
      expect(await ChatLock.instance.open('a', 'alpha1'), isTrue);
      expect(ChatLock.instance.isOpen('a'), isTrue);
    });

    test('a chat with no lock is open, so callers ask one question', () {
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      expect(ChatLock.instance.isLocked('a'), isFalse);
      expect(ChatLock.instance.isOpen('a'), isTrue);
      expect(ChatLock.instance.isConcealed('a'), isFalse);
    });

    test('taking the lock off needs the password', () async {
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1');
      expect(await ChatLock.instance.removeLock('a', 'guessing'), isFalse);
      expect(ChatLock.instance.isLocked('a'), isTrue,
          reason: '"unlock" must be a use of the lock, not a way past it');
      expect(await ChatLock.instance.removeLock('a', 'alpha1'), isTrue);
      expect(ChatLock.instance.isLocked('a'), isFalse);
    });

    test('hiding an open chat needs no password, and a shut one cannot',
        () async {
      // Being asked to prove you may look at the conversation you are looking
      // at is friction with nothing behind it — the session unlock IS that
      // proof. Without it, there is nothing to go on.
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1');
      expect(await ChatLock.instance.setHidden('a', true), isTrue);
      expect(ChatLock.instance.isHidden('a'), isTrue);

      ChatLock.instance.closeAll();
      expect(await ChatLock.instance.setHidden('a', false), isFalse);
      expect(ChatLock.instance.isHidden('a'), isTrue);
    });

    test('a deleted chat does not leave a lock behind it', () async {
      // Otherwise a chat recreated with the same id arrives already locked,
      // with a password nobody remembers setting.
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1');
      await ChatLock.instance.forget('a');
      expect(ChatLock.instance.isLocked('a'), isFalse);
      expect(ChatLock.instance.lockedCount, 0);
    });

    test('unreadable stored state means no locks, never all locks', () async {
      // A corrupt blob must not be a way to lose every conversation at once.
      SharedPreferences.setMockInitialValues(
          {'chat_locks_v1': 'not json at all'});
      await ChatLock.instance.load();
      expect(ChatLock.instance.lockedCount, 0);
      expect(ChatLock.instance.isOpen('anything'), isTrue);
    });

    testWidgets('a locked row shows who, never what', (t) async {
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1');
      ChatLock.instance.closeAll();
      await t.pumpWidget(MaterialApp(
          home: Scaffold(
              body: ChatListTile(
                  chat: ChatStore.instance.allChats.first, onTap: () {}))));
      await t.pumpAndSettle();
      expect(find.text('Ada'), findsOneWidget);
      expect(find.text('Locked'), findsOneWidget);
      expect(find.text('the secret'), findsNothing,
          reason: 'a preview is the message, and it was on the locked row');
    });

    testWidgets('a hidden row is not drawn at all', (t) async {
      ChatStore.instance.setChats([chatWith('a', 'Ada')]);
      await ChatLock.instance.lock('a', 'alpha1', hidden: true);
      ChatLock.instance.closeAll();
      await t.pumpWidget(MaterialApp(
          home: Scaffold(
              body: ChatListTile(
                  chat: ChatStore.instance.allChats.first, onTap: () {}))));
      await t.pumpAndSettle();
      expect(find.text('Ada'), findsNothing);
      expect(find.text('Locked'), findsNothing,
          reason: 'even the word gives away that there is something there');
    });

    test('search cannot read what the lock is for', () async {
      // The messages of a locked chat are exactly what the password protects.
      // Search reading them would be a way round the lock that never asks.
      ChatStore.instance
          .setChats([chatWith('a', 'Ada'), chatWith('b', 'Bo')]);
      expect(ChatStore.instance.searchableChats.map((c) => c.id),
          containsAll(['a', 'b']));

      await ChatLock.instance.lock('a', 'alpha1');
      ChatLock.instance.closeAll();
      expect(ChatStore.instance.searchableChats.map((c) => c.id), ['b']);

      // And it comes back the moment the password is given, because search
      // over a chat you have open is just search.
      await ChatLock.instance.open('a', 'alpha1');
      expect(ChatStore.instance.searchableChats.map((c) => c.id),
          containsAll(['a', 'b']));
    });

    test('the search screen goes through that and not round it', () {
      final src =
          File('lib/screens/chat_search_delegate.dart').readAsStringSync();
      expect(src.contains('ChatStore.instance.searchableChats'), isTrue);
      expect(src.contains('ChatStore.instance.allChats'), isFalse,
          reason: 'search went back to reading every chat, locked ones too');
    });

    test('backgrounding shuts every chat that was opened', () {
      // A chat opened an hour ago and left on the screen is one the password
      // stopped protecting.
      //
      // Comments are stripped first: the earlier version of this test read a
      // commented-out call as a live one, which is exactly the change it
      // exists to catch.
      final live = File('lib/main.dart')
          .readAsLinesSync()
          .where((l) => !l.trimLeft().startsWith('//'))
          .join('\n');
      final paused = live.substring(live.indexOf('AppLifecycleState.paused'));
      expect(paused.contains('ChatLock.instance.closeAll()'), isTrue);
    });
  });
  group('screenshot and forward protection', () {
    setUp(() {
      ChatStore.instance.reset();
      ChatLock.instance.resetForTest();
    });

    Chat chatWith(String id) => Chat(
          id: id,
          contact: const AppUser(
              id: '15551230000',
              name: 'Ada',
              avatarColor: '#2E7D32',
              phone: '15551230000'),
          messages: const [],
        );

    test('the flag rides out with the message, and survives the envelope', () {
      // The setting belongs to whoever wrote the words. Reading it from the
      // recipient's own chat instead would mean turning your copy off
      // unlocked what somebody else sent you under theirs.
      final m = Message(
          id: 'm1',
          text: 'hi',
          isMe: true,
          time: DateTime(2026, 1, 1),
          protected: true);
      expect(m.toJson()['protected'], isTrue);
      expect(Message.fromJson(m.toJson()).protected, isTrue);

      // And an old sender who never heard of the flag is not protected by
      // accident, which would make their messages unforwardable for ever.
      final old = Map<String, dynamic>.from(m.toJson())..remove('protected');
      expect(Message.fromJson(old).protected, isFalse);
    });

    test('the chat setting persists, so protection is not a session', () {
      final chat = chatWith('a').copyWith(protectContent: true);
      expect(chat.toJson()['protectContent'], isTrue);
      expect(Chat.fromJson(chat.toJson()).protectContent, isTrue);
      // Absent means off: an existing chat must not become protected by an
      // upgrade nobody asked for.
      final old = Map<String, dynamic>.from(chat.toJson())
        ..remove('protectContent');
      expect(Chat.fromJson(old).protectContent, isFalse);
    });

    test('every send path is stamped, because one funnel does it', () {
      // Stamped in _deliver rather than at each of the places a message is
      // built, so a send path added later cannot forget.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final deliver = src.substring(src.indexOf('void _deliver('));
      expect(deliver.contains('copyWith(protected: true)'), isTrue);
      expect(RegExp(r'_store\.isProtected\(_chatId\)').hasMatch(deliver), isTrue);
    });

    test('a protected message cannot leave, whichever side protected it', () {
      // Two independent reasons, and either is enough.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final fn = src.substring(src.indexOf('bool _mayLeaveChat('),
          src.indexOf('bool get _selectionMayLeave'));
      final collapsed = fn.replaceAll(RegExp(r'\s+'), ' ');
      expect(
          collapsed.contains(
              '!_store.isProtected(_chatId) && !message.protected'),
          isTrue,
          reason: 'the received-message half is what stops somebody turning '
              'their own setting off to unlock what you sent them');

      // Forward and Copy are both behind it: blocking one and leaving the
      // other is a lock next to an open window.
      for (final guard in [
        "if ((message.isImage || message.text.trim().isNotEmpty) &&\n                    _mayLeaveChat(message))",
        "if (message.text.trim().isNotEmpty && _mayLeaveChat(message))",
      ]) {
        expect(src.contains(guard), isTrue, reason: guard);
      }
      expect(src.contains('if (_selectionMayLeave)'), isTrue);
    });

    test('a screenshot notice is itself unforwardable', () {
      ChatStore.instance.setChats([chatWith('a')]);
      ChatStore.instance.noteScreenshot('a', byMe: true);
      final m = ChatStore.instance.chatById('a')!.messages.last;
      expect(m.text, contains('You took a screenshot'));
      expect(m.isMe, isTrue);
      // It is about this conversation and means nothing outside it — and it
      // must stay unforwardable even if protection is later switched off.
      expect(m.protected, isTrue);

      ChatStore.instance.noteScreenshot('a', byMe: false);
      final theirs = ChatStore.instance.chatById('a')!.messages.last;
      expect(theirs.text, contains('They took a screenshot'));
      expect(theirs.isMe, isFalse);
    });

    test('the notice carries nothing but who took it', () {
      // No image, no message id, nothing about what was on the screen. It
      // rides the same fire-and-forget ping as typing.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(src.contains("_ping(contactPhone, 'shot')"), isTrue);
      expect(src.contains("event: 'shot'"), isTrue,
          reason: 'sent but never subscribed to is a notice nobody receives');
    });

    testWidgets('a screenshot on another screen is not attributed to a chat',
        (t) async {
      // The notifier fires app-wide. A chat that acted on it while buried
      // would announce a screenshot of the chat list as one of itself.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final fn = src.substring(src.indexOf('void _onScreenshot()'),
          src.indexOf('void _onRemoteScreenshot()'));
      expect(fn.contains('ModalRoute.of(context)!.isCurrent'), isTrue);
      expect(fn.contains('_store.isProtected(_chatId)'), isTrue,
          reason: 'an unprotected chat announces nothing');
    });

    test('the native side is registered and needs no availability guard', () {
      // iOS gives no way to BLOCK a screenshot, only this notification.
      // userDidTakeScreenshotNotification is iOS 7+, so unlike the two APIs
      // that have broken the archive before, it needs no #available.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift.contains('okay/screenshot'), isTrue);
      expect(swift.contains('UIApplication.userDidTakeScreenshotNotification'),
          isTrue);
      // Registered once: a second observer reports every screenshot twice,
      // which reads as two screenshots.
      expect(swift.contains('watchingScreenshots'), isTrue);
      // And the Dart side has to ask for it, or the observer never exists.
      expect(
          File('lib/state/screenshot_watch.dart')
              .readAsStringSync()
              .contains("invokeMethod<bool>('watch')"),
          isTrue);
    });

    test('a recording is announced as a recording, not a screenshot', () {
      ChatStore.instance.setChats([chatWith('a')]);
      ChatStore.instance.noteScreenshot('a', byMe: true, recording: true);
      final mine = ChatStore.instance.chatById('a')!.messages.last;
      expect(mine.text, contains('recording or mirroring'));
      expect(mine.text, isNot(contains('screenshot')),
          reason: 'announcing a recording as a screenshot is a wrong sentence');

      ChatStore.instance.noteScreenshot('a', byMe: false, recording: true);
      expect(ChatStore.instance.chatById('a')!.messages.last.text,
          startsWith('They'));
    });

    test('a recording has its own event, because it is its own sentence', () {
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(src.contains("_ping(contactPhone, 'cap')"), isTrue);
      expect(src.contains("event: 'cap'"), isTrue,
          reason: 'sent but never subscribed to is a notice nobody receives');
    });

    testWidgets('a protected chat blanks itself while the screen is captured',
        (t) async {
      // A screenshot can only be announced afterwards. A recording is still
      // going, so announcing and carrying on would be telling somebody their
      // messages are being filmed while filming them.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final collapsed = src.replaceAll(RegExp(r'\s+'), ' ');
      expect(
          collapsed.contains('body: _store.isProtected(_chatId) && '
              'ScreenshotWatch.instance.capturing.value ? '
              '_capturedNotice(context)'),
          isTrue,
          reason: 'the conversation is drawn while it is being recorded');
    });

    test('recording state is read at startup, not only on the next change',
        () {
      // A recording already running when the app opens has fired its
      // notification already; waiting for the next one misses the session.
      final src =
          File('lib/state/screenshot_watch.dart').readAsStringSync();
      expect(
          src.contains(
              "capturing.value = await _channel.invokeMethod<bool>('watch')"),
          isTrue);
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift.contains('result(UIScreen.main.isCaptured)'), isTrue);
      expect(swift.contains('UIScreen.capturedDidChangeNotification'), isTrue);
    });

    test('the app switcher snapshot is covered, for every screen', () {
      // The leak people mistake for screenshot blocking in banking apps, and
      // unlike a screenshot it really is preventable — the snapshot is
      // written to disk and outlives the session.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift.contains('UIApplication.willResignActiveNotification'),
