  group('the Signal double ratchet', () {
    // Two devices in one process: Alice (111, the fixed initiator — smaller
    // digits) and Bob (222, the responder). Each holds its own identity and
    // the other's public key, exactly the state the in-band exchange leaves.
    late SecureKeyExchange kxA, kxB;
    late DoubleRatchet a, b;

    setUp(() {
      kxA = SecureKeyExchange.freshForTest();
      kxB = SecureKeyExchange.freshForTest();
      kxA.rememberPeer('222', kxB.myPublicKey!);
      kxB.rememberPeer('111', kxA.myPublicKey!);
      a = DoubleRatchet.freshForTest(kxA);
      b = DoubleRatchet.freshForTest(kxB);
    });

    test('messages round-trip, each under its own key', () {
      final m1 = a.encrypt('111', '222', 'first')!;
      final m2 = a.encrypt('111', '222', 'second')!;
      expect(m1.blob, isNot(m2.blob));
      expect(m1.header['n'], 0);
      expect(m2.header['n'], 1);
      expect(b.decrypt('222', '111', m1.header, m1.blob), 'first');
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'second');
    });

    test('the responder cannot start a session, only answer one', () {
      // Two sides that both spoke first would mint two incompatible
      // sessions and each lose the other's opener — so only Alice creates,
      // and Bob's messages ride the static path until she has.
      expect(b.encrypt('222', '111', 'too early'), isNull);
      final m = a.encrypt('111', '222', 'opener')!;
      expect(b.decrypt('222', '111', m.header, m.blob), 'opener');
      expect(b.encrypt('222', '111', 'now I can'), isNotNull);
    });

    test('a reply advances the DH ratchet on both ends', () {
      final m1 = a.encrypt('111', '222', 'hi')!;
      b.decrypt('222', '111', m1.header, m1.blob);
      final r1 = b.encrypt('222', '111', 'hi yourself')!;
      expect(r1.header['dh'], isNot(m1.header['dh']),
          reason: 'Bob replies under a ratchet key of his own');
      expect(a.decrypt('111', '222', r1.header, r1.blob), 'hi yourself');
      final m2 = a.encrypt('111', '222', 'again')!;
      expect(m2.header['dh'], isNot(m1.header['dh']),
          reason: 'receiving a new remote key turns Alice\'s crank too');
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'again');
    });

    test('out-of-order delivery is shelved, not lost', () {
      final m1 = a.encrypt('111', '222', 'one')!;
      final m2 = a.encrypt('111', '222', 'two')!;
      final m3 = a.encrypt('111', '222', 'three')!;
      expect(b.decrypt('222', '111', m3.header, m3.blob), 'three');
      expect(b.decrypt('222', '111', m1.header, m1.blob), 'one');
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'two');
    });

    test('a replayed message decrypts exactly once', () {
      final m = a.encrypt('111', '222', 'once only')!;
      expect(b.decrypt('222', '111', m.header, m.blob), 'once only');
      expect(b.decrypt('222', '111', m.header, m.blob), isNull,
          reason: 'the key was deleted on use — that is the whole point');
    });

    test('a failed replay burns nothing: the next genuine message still opens',
        () {
      // Delivery is broadcast + mailbox, so the same envelope routinely
      // arrives twice. The replay must fail (above) — but it used to advance
      // the receiving chain on its way to failing, leaving it one key ahead
      // of the sender, and every GENUINE message after it rendered as
      // "🔒 Couldn't unlock this message" until a heal buried the session.
      final m1 = a.encrypt('111', '222', 'one')!;
      expect(b.decrypt('222', '111', m1.header, m1.blob), 'one');
      expect(b.decrypt('222', '111', m1.header, m1.blob), isNull);
      final m2 = a.encrypt('111', '222', 'two')!;
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'two',
          reason: 'the failed replay must not have moved the chain');
      // And a forged/corrupt blob mid-conversation burns nothing either.
      expect(b.decrypt('222', '111', a.encrypt('111', '222', 'x')!.header,
          'not-even-base64'), isNull);
      final m3 = a.encrypt('111', '222', 'three')!;
      // The 'x' envelope (n=2) was never delivered readably; m3 (n=3) makes
      // the chain wind past it onto the shelf, which only works if the two
      // failures above really left the chain where it was.
      expect(b.decrypt('222', '111', m3.header, m3.blob), 'three');
    });

    test('a stale header from a buried session cannot displace the live one',
        () {
      // An old-world envelope held back (a mailbox row outliving its
      // session) arrives after the initiator reset and started over. The
      // responder rebuilds a half for the foreign sid, the decrypt fails —
      // and the LIVE session must come back out of that intact, where it
      // used to be overwritten by the freshly-minted wrong one.
      final w1 = a.encrypt('111', '222', 'old world')!;
      expect(b.decrypt('222', '111', w1.header, w1.blob), 'old world');
      // Bob replies so the live root advances past the static bootstrap —
      // the state a from-scratch rebuild can never reach.
      final r1 = b.encrypt('222', '111', 'reply')!;
      expect(a.decrypt('111', '222', r1.header, r1.blob), 'reply');
      final w2 = a.encrypt('111', '222', 'held back')!;
      a.resetPeer('222');
      final n1 = a.encrypt('111', '222', 'new world')!;
      expect(b.decrypt('222', '111', n1.header, n1.blob), 'new world');
      final r2 = b.encrypt('222', '111', 'new reply')!;
      expect(a.decrypt('111', '222', r2.header, r2.blob), 'new reply');
      // The stale envelope lands. Its sid is dead; the rebuild fails.
      expect(b.decrypt('222', '111', w2.header, w2.blob), isNull);
      // The live session survived it.
      final n2 = a.encrypt('111', '222', 'still here')!;
      expect(b.decrypt('222', '111', n2.header, n2.blob), 'still here');
    });

    test('replays are dropped before they ever reach the ratchet', () {
      // Belt to the transactional-decrypt braces: applyIncoming checks the
      // store for the message id BEFORE decrypting, so the mailbox replaying
      // what the broadcast already delivered never even knocks.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final body = src.substring(src.indexOf('static bool applyIncoming'));
      final dedup = body.indexOf('chatWithMessage(id, senderId: from)');
      final decode = body.indexOf('_decodeContent(');
      expect(dedup, greaterThan(-1));
      expect(decode, greaterThan(-1));
      expect(dedup, lessThan(decode),
          reason: 'dedup must run before decryption');
    });

    test('a touched header fails like touched ciphertext', () {
      final m = a.encrypt('111', '222', 'bound')!;
      final forged = Map<String, dynamic>.from(m.header);
      forged['n'] = (forged['n'] as int) + 1;
      expect(b.decrypt('222', '111', forged, m.blob), isNull);
    });

    test('a stolen session heals once a fresh key the thief never saw lands',
        () {
      // The property the static path never had — but healing has a precise
      // boundary worth pinning: a thief who copies Bob's state owns Bob's
      // CURRENT ratchet private key, so it can follow the conversation until
      // Bob next generates a pair (which happens as he receives Alice's next
      // new key) and that pair enters the root. Everything after that DH is
      // noise to the copy.
      final m1 = a.encrypt('111', '222', 'before')!;
      b.decrypt('222', '111', m1.header, m1.blob);
      final stolen = jsonDecode(jsonEncode(b.debugSessionJson('111')))
          as Map<String, dynamic>;
      final thief = DoubleRatchet.freshForTest(kxB);
      thief.debugRestoreSession('111', stolen);

      // The exchange that heals: Bob replies (under the stolen key — the
      // thief can still follow), Alice ratchets, Bob decrypts her message
      // and mints the pair the thief will never hold, replies under it,
      // Alice ratchets onto it.
      final r1 = b.encrypt('222', '111', 'reply one')!;
      a.decrypt('111', '222', r1.header, r1.blob);
      final m2 = a.encrypt('111', '222', 'mid-heal')!;
      expect(thief.decrypt('222', '111', m2.header, m2.blob), 'mid-heal',
          reason: 'honesty about the boundary: the thief still reads here — '
              'no fresh DH has entered the root yet');
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'mid-heal');
      final r2 = b.encrypt('222', '111', 'reply two')!;
      a.decrypt('111', '222', r2.header, r2.blob);

      // Healed: the root has stepped through Bob's post-theft key.
      final m3 = a.encrypt('111', '222', 'after the ratchet turned')!;
      expect(thief.decrypt('222', '111', m3.header, m3.blob), isNull);
      // The rightful Bob reads it fine.
      expect(b.decrypt('222', '111', m3.header, m3.blob),
          'after the ratchet turned');
    });

    test('a session survives being persisted mid-conversation', () {
      final m1 = a.encrypt('111', '222', 'pre-restart')!;
      b.decrypt('222', '111', m1.header, m1.blob);
      final saved = jsonDecode(jsonEncode(a.debugSessionJson('222')))
          as Map<String, dynamic>;
      final restarted = DoubleRatchet.freshForTest(kxA);
      restarted.debugRestoreSession('222', saved);
      final m2 = restarted.encrypt('111', '222', 'post-restart')!;
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'post-restart');
    });

    test('an identity change buries the old session', () {
      final m1 = a.encrypt('111', '222', 'old world')!;
      b.decrypt('222', '111', m1.header, m1.blob);
      a.resetPeer('222');
      final m2 = a.encrypt('111', '222', 'new world')!;
      expect(m2.header['sid'], isNot(m1.header['sid']),
          reason: 'a fresh session, not a resumed one');
      // Bob rebuilds his half from the new sid and reads on.
      expect(b.decrypt('222', '111', m2.header, m2.blob), 'new world');
    });

    test('a header wound past MAX_SKIP is refused, not ground through', () {
      final m = a.encrypt('111', '222', 'x')!;
      final forged = Map<String, dynamic>.from(m.header);
      forged['n'] = DoubleRatchet.maxSkip + 5;
      expect(b.decrypt('222', '111', forged, m.blob), isNull);
    });

    test('the relay actually uses it, on both sides', () {
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      // The one shared ladder every pairwise surface goes through.
      expect(src.contains("'enc': 3"), isTrue);
      expect(src.contains("'rh': sealed.header"), isTrue,
          reason: 'the ratchet header must ride the payload');
      expect(src.contains("encRaw == 3 || encRaw == '3'"), isTrue,
          reason: 'and be understood on arrival');
      expect(src.contains('static Map<String, dynamic> sealContent'), isTrue,
          reason: 'message content, group updates and signaling share it');
      expect(src.contains('r.resetPeer(from)'), isTrue,
          reason: 'a changed identity key must bury the old session');
      final main = File('lib/main.dart').readAsStringSync();
      expect(main.contains('DoubleRatchet.instance.load'), isTrue,
          reason: 'sessions must survive a restart');
    });

    test('call signaling and group updates ride the same ladder', () {
      // The point of the refactor: no pairwise surface gets its encryption
      // by accident of which method built its payload. Both route through
      // sealContent, so both inherit the ratchet.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      // Group updates:
      expect(src.contains('...sealContent(me.phone, phone, blob)'), isTrue,
          reason: 'sendGroupUpdate must seal through the shared ladder');
      // Call / file signaling:
      expect(src.contains('return sealContent(me?.phone ?? \'\', contactPhone'),
          isTrue,
          reason: '_sealSignal must seal through the shared ladder');
      expect(src.contains('return openContent(from, me.phone, fragment)'),
          isTrue,
          reason: '_openSignal must open through the shared ladder');
      // And the old bespoke ECDH-only ladders are gone from both.
      expect(src.contains("out['sspk'] = s.spk"), isFalse,
          reason: 'the hand-rolled signal seal should be retired');
    });
  });
  group('Signal sender keys (server broadcast)', () {
    // Three members of one server, each with its own store. 'aaa' sends;
    // 'bbb' and 'ccc' receive after taking aaa's distribution message.
    late SenderKeyStore aaa, bbb, ccc;
    const sid = 'srv1';

    setUp(() {
      aaa = SenderKeyStore.freshForTest();
      bbb = SenderKeyStore.freshForTest();
      ccc = SenderKeyStore.freshForTest();
    });

    void distribute(SenderKeyStore from, String fromId, List<SenderKeyStore> to) {
      final skdm = from.mySkdm(sid);
      for (final t in to) {
        t.acceptSkdm(sid, fromId, skdm.ck, skdm.n, skdm.sig);
      }
    }

    test('a broadcast reaches every member who has the sender key', () {
      distribute(aaa, 'aaa', [bbb, ccc]);
      final m = aaa.seal(sid, 'hello server');
      expect(bbb.open(sid, 'aaa', m.n, m.ct, m.sg), 'hello server');
      expect(ccc.open(sid, 'aaa', m.n, m.ct, m.sg), 'hello server');
    });

    test('a member without the sender key cannot read (must request it)', () {
      // The race the relay closes with an skreq: ccc never took aaa's SKDM.
      distribute(aaa, 'aaa', [bbb]);
      final m = aaa.seal(sid, 'members only');
      expect(bbb.open(sid, 'aaa', m.n, m.ct, m.sg), 'members only');
      expect(ccc.open(sid, 'aaa', m.n, m.ct, m.sg), isNull);
    });

    test('each message uses its own key; a replay reads once', () {
      distribute(aaa, 'aaa', [bbb]);
      final m1 = aaa.seal(sid, 'one');
      final m2 = aaa.seal(sid, 'two');
      expect(m1.ct, isNot(m2.ct));
      expect(bbb.open(sid, 'aaa', m1.n, m1.ct, m1.sg), 'one');
      expect(bbb.open(sid, 'aaa', m2.n, m2.ct, m2.sg), 'two');
      expect(bbb.open(sid, 'aaa', m1.n, m1.ct, m1.sg), isNull,
          reason: 'the key was deleted on use — forward secrecy at work');
    });

    test('out-of-order broadcasts are shelved, not lost', () {
      distribute(aaa, 'aaa', [bbb]);
      final m1 = aaa.seal(sid, 'first');
      final m2 = aaa.seal(sid, 'second');
      final m3 = aaa.seal(sid, 'third');
      expect(bbb.open(sid, 'aaa', m3.n, m3.ct, m3.sg), 'third');
      expect(bbb.open(sid, 'aaa', m1.n, m1.ct, m1.sg), 'first');
      expect(bbb.open(sid, 'aaa', m2.n, m2.ct, m2.sg), 'second');
    });

    test('a late joiner reads from when they joined, not before', () {
      distribute(aaa, 'aaa', [bbb]);
      final before = aaa.seal(sid, 'before ccc');
      // ccc joins now: takes aaa's CURRENT skdm, which is past `before`.
      final skdm = aaa.mySkdm(sid);
      ccc.acceptSkdm(sid, 'aaa', skdm.ck, skdm.n, skdm.sig);
      final after = aaa.seal(sid, 'after ccc');
      expect(ccc.open(sid, 'aaa', after.n, after.ct, after.sg), 'after ccc');
      expect(ccc.open(sid, 'aaa', before.n, before.ct, before.sg), isNull,
          reason: 'a joiner must not be handed keys to earlier messages');
    });

    test('rotation locks out a chain a departed member still holds', () {
      // ccc was a member and holds aaa's chain…
      distribute(aaa, 'aaa', [bbb, ccc]);
      final old = aaa.seal(sid, 'while ccc was in');
      expect(ccc.open(sid, 'aaa', old.n, old.ct, old.sg), 'while ccc was in');
      // …ccc leaves; aaa rotates to a fresh epoch and redistributes to bbb.
      aaa.rotate(sid);
      final skdm = aaa.mySkdm(sid);
      bbb.acceptSkdm(sid, 'aaa', skdm.ck, skdm.n, skdm.sig);
      final fresh = aaa.seal(sid, 'after ccc left');
      expect(bbb.open(sid, 'aaa', fresh.n, fresh.ct, fresh.sg), 'after ccc left');
      expect(ccc.open(sid, 'aaa', fresh.n, fresh.ct, fresh.sg), isNull,
          reason: 'the departed member\'s old chain reads nothing new');
    });

    test('a message wound past MAX_SKIP is refused', () {
      distribute(aaa, 'aaa', [bbb]);
      final m = aaa.seal(sid, 'x');
      // Forge an iteration far beyond the bound (re-sign so it clears the
      // signature check and the skip bound is what actually refuses it).
      expect(
          bbb.open(sid, 'aaa', SenderKeyStore.maxSkip + 10, m.ct, m.sg), isNull);
    });

    test('a first-ever chain triggers the feed re-ask, replacements do not',
        () {
      // The mailbox deletes what it cannot open, so a listing sealed while
      // the pairing was broken never existed on the receiving phone — and
      // no amount of chain repair brings the CONTENT back. The first SKDM
      // from a sender is the moment to ask for their feed again.
      final skdm = aaa.mySkdm(sid);
      expect(bbb.acceptSkdm(sid, 'aaa', skdm.ck, skdm.n, skdm.sig), isTrue,
          reason: 'no chain before = everything earlier was dropped unread');
      expect(bbb.acceptSkdm(sid, 'aaa', skdm.ck, skdm.n, skdm.sig), isFalse,
          reason: 'a re-delivery of the same chain misses nothing');
      aaa.rotate(sid);
      final rotated = aaa.mySkdm(sid);
      expect(
          bbb.acceptSkdm(sid, 'aaa', rotated.ck, rotated.n, rotated.sig),
          isFalse,
          reason: 'a rotation replaces a chain that was already readable');

      // And the wiring exists end to end: the SKDM handler asks, the ask is
      // routed live and from the mailbox, and the answer checks membership.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay.contains('_requestFeedBackfill(cid'), isTrue);
      expect(relay.contains("event: 'fbreq'"), isTrue);
      expect(
          relay.replaceAll(RegExp(r'\s+'), ' ').contains(
              "case 'fbreq': applyFbreq(payload, myPhone: me);"),
          isTrue,
          reason: 'a queued fbreq must drain from the mailbox too');
      expect(relay.contains('community.members.any((m) => m.id == wire)'),
          isTrue,
          reason: 'only members may be handed the feed');
    });

    test('a tampered server/iteration binding fails the tag', () {
      distribute(aaa, 'aaa', [bbb]);
      final m = aaa.seal(sid, 'bound to place');
      // Right ciphertext, wrong iteration claim → signature/AAD mismatch.
      expect(bbb.open(sid, 'aaa', m.n + 1, m.ct, m.sg), isNull);
    });

    test('two senders on one server do not collide', () {
      distribute(aaa, 'aaa', [ccc]);
      distribute(bbb, 'bbb', [ccc]);
      final fromA = aaa.seal(sid, 'from A');
      final fromB = bbb.seal(sid, 'from B');
      expect(ccc.open(sid, 'aaa', fromA.n, fromA.ct, fromA.sg), 'from A');
      expect(ccc.open(sid, 'bbb', fromB.n, fromB.ct, fromB.sg), 'from B');
    });

    test('one member cannot forge a message as another', () {
      // The signature gap this closes: bbb receives aaa's chain (must, to
      // decrypt) — but without aaa's signing key, bbb cannot write as aaa.
      distribute(aaa, 'aaa', [bbb, ccc]);
      // bbb holds aaa's chain key, so bbb can derive aaa's next message key
      // and forge a ciphertext… but bbb signs with ITS OWN key.
      final forged = bbb.seal(sid, 'pretending to be aaa');
      // ccc, verifying against aaa's signing key from the SKDM, rejects it.
      expect(ccc.open(sid, 'aaa', forged.n, forged.ct, forged.sg), isNull,
          reason: 'a message signed by bbb must not read as one from aaa');
    });

    test('a genuine message with a swapped signature is refused', () {
      distribute(aaa, 'aaa', [bbb, ccc]);
      final real = aaa.seal(sid, 'genuine');
      final other = bbb.seal(sid, 'other'); // some other valid signature
      expect(ccc.open(sid, 'aaa', real.n, real.ct, other.sg), isNull,
          reason: 'the signature must be aaa\'s over THIS ciphertext');
    });

    test('the relay wires it with a shared-secret fallback and rotation', () {
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(src.contains('SenderKeyStore'), isTrue);
      expect(src.contains("'skc'") || src.contains('skc'), isTrue,
          reason: 'sender-key ciphertext must ride the community payload');
      expect(src.contains('skreq') || src.contains('skdm'), isTrue,
          reason: 'the SKDM race needs a request/deliver path');
      expect(src.contains('.rotate('), isTrue,
          reason: 'membership change must rotate the epoch');
      expect(src.contains("'sg': sealed.sg"), isTrue,
          reason: 'the per-message signature must ride the broadcast');
      expect(src.contains("'sig': skdm.sig"), isTrue,
          reason: 'the SKDM must carry the signing public key');
    });
  });
  group('private notifications and forced-E2EE backups', () {
    test('the recipient\'s flag is enforced by the server, not the sender',
        () {
      // The push is composed on the SENDER's device, so a preference
      // protecting the RECIPIENT's lock screen has to be applied where the
      // recipient's row lives — push-send — or it protects nothing.
      final fn =
          File('supabase/functions/push-send/index.ts').readAsStringSync();
      expect(fn.contains('"token, private, voip_token"'), isTrue,
          reason: 'push-send must read the recipient\'s private flag '
              '(and the VoIP token, for ringing a closed app)');
      expect(fn.contains('row.private === true'), isTrue);
      expect(fn.contains('wantsPrivate ? "New message" : title'), isTrue,
          reason: 'a private alert says "New message" and nothing else');
      expect(fn.contains('category: "okay_msg"'), isTrue,
          reason: 'the category is what hides previews on a locked phone');

      final schema = File('supabase/schema.sql').readAsStringSync();
      expect(
          schema.contains(RegExp(
              r'alter table public\.push_tokens\s+add column if not exists private')),
          isTrue,
          reason: 'existing deployments must gain the column');
    });

    test('the app uploads its choice and can clear what was delivered', () {
      final push = File('lib/state/push_service.dart').readAsStringSync();
      expect(push.contains("'private': AppState.privateNotifications.value"),
          isTrue,
          reason: 'the flag rides up with the token');
      expect(push.contains('_onPrivateChanged'), isTrue,
          reason: 'flipping the toggle must re-upsert, not wait for a '
              'relaunch');
      // The Swift side is pinned by source, like the other never-compiled
      // native code: there is no Xcode here, so the test is what stops the
      // Dart call from pointing at a method that does not exist.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(swift.contains('"clearDelivered"'), isTrue);
      expect(swift.contains('removeAllDeliveredNotifications'), isTrue);
      expect(swift.contains('hiddenPreviewsBodyPlaceholder: "New message"'),
          isTrue,
          reason: 'a locked phone must show the placeholder, not the sender');
      final main = File('lib/main.dart').readAsStringSync();
      expect(main.contains('clearDelivered'), isTrue,
          reason: 'delivered alerts are cleared when the app comes forward');
    });

    testWidgets('the toggle exists and persists like every other setting',
        (t) async {
      addTearDown(AppState.resetForTest);
      expect(AppState.privateNotifications.value, isFalse,
          reason: 'off by default — hiding who writes to you is a choice');
      final persistence =
          File('lib/state/persistence.dart').readAsStringSync();
      expect(persistence.contains('_kPrivateNotifications'), isTrue);
      expect(persistence.contains('_savePrivateNotifications'), isTrue);
    });

    test('chat backups leave only as ciphertext, and come back whole',
        () async {
      // "Force E2EE backups" is not a switch — it is the absence of any
      // other path. This drives the real backup pipeline into the debug
      // server and reads what actually left the device.
      CloudSync.debugServerOverride = {};
      StorageStore.instance.debugSubscribe(1);
      ChatStore.instance.reset();
      addTearDown(() {
        CloudSync.debugServerOverride = null;
        CloudSync.instance.resetForTest();
        StorageStore.instance.resetForTest();
        ChatStore.instance.reset();
      });
      await CloudSync.instance
          .configure(passphrase: 'correct horse battery', on: false);
      ChatStore.instance.setChats([
        Chat(
            id: 'c',
            contact: const AppUser(
                id: 'p',
                name: 'Bosworth Fieldmarshal',
                avatarColor: '#2E7D32',
                phone: 'p'),
            messages: [
              Message(
                  id: 'm1',
                  text: 'the safe code is 4711',
                  time: DateTime(2026, 1, 1),
                  isMe: true)
            ])
      ]);

      expect(await CloudSync.instance.backUpChats(), isNull);
      final blob = CloudSync.debugServerOverride!.values.single;
      // Whole phrases, not short fragments — four characters of base64 can
      // collide with anything.
      expect(blob.contains('the safe code is 4711'), isFalse,
          reason: 'message content must never leave in the clear');
      expect(blob.contains('Bosworth Fieldmarshal'), isFalse,
          reason: 'names are content too');

      ChatStore.instance.reset();
      expect(await CloudSync.instance.restoreChats(), isNull);
      expect(
          ChatStore.instance
              .chatById('c')!
              .messages
              .single
              .text,
          'the safe code is 4711');
    });

    test('the backup screen says the guarantee, and cannot understate it',
        () {
      // Same pattern as the screenshot subtitle: the sentence is the
      // promise, and a test is what stops it being edited into something
      // weaker.
      // The sentence wraps across source lines, so match its rarest part.
      final src = File('lib/screens/backup_screen.dart').readAsStringSync();
      expect(src.contains('unencrypted backup'), isTrue);
    });
  });
  group('feed thread readability', () {
    testWidgets('the post a thread is about is set larger than its replies',
        (t) async {
      await t.pumpWidget(const MaterialApp(
        home: Scaffold(
          body: Column(children: [
            FeedBodyText(
                key: ValueKey('root'),
                text: 'the post',
                focused: true,
                collapse: false),
            FeedBodyText(
                key: ValueKey('child'), text: 'a reply', collapse: false),
          ]),
        ),
      ));
      await t.pumpAndSettle();

      double biggest(Key key) {
        double out = 0;
        void walk(InlineSpan s) {
          final f = s.style?.fontSize;
          if (f != null && f > out) out = f;
          if (s is TextSpan) {
            for (final c in s.children ?? const <InlineSpan>[]) {
              walk(c);
            }
          }
        }

        for (final r in t.widgetList<RichText>(find.descendant(
            of: find.byKey(key), matching: find.byType(RichText)))) {
          walk(r.text);
        }
        return out;
      }

      expect(biggest(const ValueKey('root')),
          greaterThan(biggest(const ValueKey('child'))),
          reason: 'nothing else on a thread screen says which one is the '
              'post and which are the replies');
    });
  });
