    Message form(String id) => Message(
          id: id,
          text: '',
          isMe: true,
          time: DateTime(2026, 1, 1),
          isForm: true,
          formTitle: 'Order',
          formFields: fields,
        );

    test('a form that cannot be answered is not sendable', () {
      // An unlabelled question or a choice with nothing to choose from is a
      // dead end at the other end, and finding out there is too late.
      expect(const FormFieldSpec(label: 'Name').isUsable, isTrue);
      expect(const FormFieldSpec(label: '  ').isUsable, isFalse);
      expect(
          const FormFieldSpec(
                  label: 'Size', kind: FormFieldKind.choice, options: ['S'])
              .isUsable,
          isFalse,
          reason: 'one choice is not a choice');
      expect(
          const FormFieldSpec(
                  label: 'Size',
                  kind: FormFieldKind.choice,
                  options: ['S', 'M'])
              .isUsable,
          isTrue);
    });

    test('only the required questions hold up a send', () {
      expect(FormResponse.isComplete(fields, ['Ada', '', '']), isTrue);
      expect(FormResponse.isComplete(fields, ['', 'S', 'x']), isFalse);
      expect(FormResponse.isComplete(fields, ['   ', 'S', 'x']), isFalse,
          reason: 'whitespace is not an answer');
      // Short lists must not read as answered — a missing entry is missing.
      expect(FormResponse.isComplete(fields, const []), isFalse);
    });

    test('the form travels but the answers do not travel back twice', () {
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      // Questions go out with the message...
      expect(src.contains("'formFields': [for (final f in message.formFields)"),
          isTrue);
      // ...and the response carries answers only, because the form is
      // already on the far device.
      final send = src.substring(src.indexOf('Future<void> sendFormResponse'),
          src.indexOf('Future<void> sendPollVote'));
      expect(send.contains("'answers': answers"), isTrue);
      expect(send.contains('formFields'), isFalse,
          reason: 'echoing the questions back sends the same content twice');
    });

    test('a form survives the envelope, and an old build sees no form', () {
      final m = form('f1');
      final round = Message.fromJson(m.toJson());
      expect(round.isForm, isTrue);
      expect(round.formTitle, 'Order');
      expect(round.formFields.length, 3);
      expect(round.formFields[1].options, ['S', 'M']);
      expect(round.formFields[0].required, isTrue);

      final old = Map<String, dynamic>.from(m.toJson())..remove('isForm');
      expect(Message.fromJson(old).isForm, isFalse);
    });

    test('answering twice corrects rather than duplicates', () {
      // Somebody filling a form again meant to fix it, and two rows under one
      // name is a worse answer than one.
      ChatStore.instance.setChats([
        Chat(
            id: 'c',
            contact: const AppUser(
                id: 'p', name: 'Bo', avatarColor: '#2E7D32', phone: 'p'),
            messages: [form('f1')])
      ]);
      void answer(String who, List<String> a) =>
          ChatStore.instance.applyFormResponse(
              'c',
              'f1',
              FormResponse(from: who, answers: a, at: DateTime(2026, 1, 2)));

      answer('Ada', ['Ada', 'S', '']);
      answer('Bo', ['Bo', 'M', '']);
      answer('Ada', ['Ada Lovelace', 'M', 'changed my mind']);

      final responses =
          ChatStore.instance.chatById('c')!.messages.first.formResponses;
      expect(responses.length, 2);
      final ada = responses.firstWhere((r) => r.from == 'Ada');
      expect(ada.answers.first, 'Ada Lovelace');
      expect(ada.answers.last, 'changed my mind');
      // And the correction goes last, so the list reads newest-answered.
      expect(responses.last.from, 'Ada');
    });

    test('a response never lands on the wrong message', () {
      ChatStore.instance.setChats([
        Chat(
            id: 'c',
            contact: const AppUser(
                id: 'p', name: 'Bo', avatarColor: '#2E7D32', phone: 'p'),
            messages: [form('f1'), form('f2')])
      ]);
      ChatStore.instance.applyFormResponse('c', 'f2',
          FormResponse(from: 'Ada', answers: const ['x'], at: DateTime(2026)));
      final messages = ChatStore.instance.chatById('c')!.messages;
      expect(messages[0].formResponses, isEmpty);
      expect(messages[1].formResponses.length, 1);
    });

    testWidgets('the sender sees responses, everyone else sees the form',
        (t) async {
      // The one thing each side is waiting for, and they are not the same
      // thing: the sender wants to know who answered, the recipient wants to
      // answer.
      final answered = [
        FormResponse(from: 'Ada', answers: const ['Ada'], at: DateTime(2026))
      ];

      Future<void> show({required bool mine}) async {
        await t.pumpWidget(MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'f1',
                text: '',
                isMe: mine,
                time: DateTime(2026, 1, 1),
                isForm: true,
                formTitle: 'Order',
                formFields: fields,
                formResponses: answered,
              ),
            ),
          ),
        ));
        await t.pumpAndSettle();
      }

      await show(mine: true);
      expect(find.text('Order'), findsOneWidget);
      expect(find.text('3 questions'), findsOneWidget);
      expect(find.text('View 1 response'), findsOneWidget);
      expect(find.text('Fill in this form'), findsNothing);

      await show(mine: false);
      expect(find.text('Fill in this form'), findsOneWidget);
      expect(find.textContaining('response'), findsNothing,
          reason: 'a recipient must not be shown who else answered');
    });

    test('every kind survives the envelope, help and conditions included', () {
      const f = FormFieldSpec(
        label: 'Day',
        kind: FormFieldKind.date,
        help: 'Any weekday works',
        showIfQ: 0,
        showIfIs: 'Yes',
      );
      final round = FormFieldSpec.fromJson(Map<String, dynamic>.from(
          jsonDecode(jsonEncode(f.toJson())) as Map));
      expect(round.kind, FormFieldKind.date);
      expect(round.help, 'Any weekday works');
      expect(round.showIfQ, 0);
      expect(round.showIfIs, 'Yes');
      for (final kind in FormFieldKind.values) {
        expect(
            FormFieldSpec.fromJson(
                    FormFieldSpec(label: 'x', kind: kind).toJson())
                .kind,
            kind,
            reason: 'a kind that does not round-trip arrives as short answer');
      }
    });

    test('a question is only asked when its condition is met', () {
      const branching = [
        FormFieldSpec(
            label: 'Coming?', kind: FormFieldKind.yesNo, required: true),
        FormFieldSpec(
            label: 'Why not?', required: true, showIfQ: 0, showIfIs: 'No'),
      ];
      expect(FormResponse.isShown(branching, ['Yes', ''], 1), isFalse);
      expect(FormResponse.isShown(branching, ['No', ''], 1), isTrue);
      // A required question nobody was asked cannot hold up the send…
      expect(FormResponse.isComplete(branching, ['Yes', '']), isTrue);
      // …and one that IS asked still does.
      expect(FormResponse.isComplete(branching, ['No', '']), isFalse);
      expect(FormResponse.isComplete(branching, ['No', 'travel']), isTrue);
    });

    test('a hidden question hides everything gated on it', () {
      const chain = [
        FormFieldSpec(label: 'Eating?', kind: FormFieldKind.yesNo),
        FormFieldSpec(
            label: 'Course',
            kind: FormFieldKind.choice,
            options: ['Meat', 'Veg'],
            showIfQ: 0,
            showIfIs: 'Yes'),
        FormFieldSpec(label: 'How done?', showIfQ: 1, showIfIs: 'Meat'),
      ];
      expect(FormResponse.isShown(chain, ['Yes', 'Meat', ''], 2), isTrue);
      // The middle answer can still be sitting there from before the switch;
      // its question being hidden must beat its stale answer.
      expect(FormResponse.isShown(chain, ['No', 'Meat', ''], 2), isFalse);
    });

    test('a choose-many gate matches any one of the picks', () {
      const f = [
        FormFieldSpec(
            label: 'Days',
            kind: FormFieldKind.chooseMany,
            options: ['Mon', 'Tue', 'Wed']),
        FormFieldSpec(label: 'Tuesday time', showIfQ: 0, showIfIs: 'Tue'),
      ];
      expect(FormResponse.isShown(f, ['Mon, Tue', ''], 1), isTrue);
      expect(FormResponse.isShown(f, ['Mon, Wed', ''], 1), isFalse);
    });

    test('a condition that cannot be evaluated is ignored, not obeyed', () {
      // Fail open: a mangled form should still be answerable — silently
      // unanswerable is the worse failure.
      const forward = [
        FormFieldSpec(label: 'A', showIfQ: 1, showIfIs: 'x'),
        FormFieldSpec(
            label: 'B', kind: FormFieldKind.choice, options: ['x', 'y']),
      ];
      expect(FormResponse.isShown(forward, ['', ''], 0), isTrue);
      const self = [FormFieldSpec(label: 'A', showIfQ: 0, showIfIs: 'x')];
      expect(FormResponse.isShown(self, [''], 0), isTrue);
    });

    testWidgets('a switched-away branch does not ride out with the response',
        (t) async {
      const branching = [
        FormFieldSpec(label: 'Coming?', kind: FormFieldKind.yesNo),
        FormFieldSpec(label: 'Why not?', showIfQ: 0, showIfIs: 'No'),
      ];
      await t.pumpWidget(const MaterialApp(
          home: FormFillScreen(title: 'RSVP', fields: branching)));
      await t.pumpAndSettle();
      expect(find.text('Why not?'), findsNothing,
          reason: 'the branch question waits for its answer');
      await t.tap(find.text('No'));
      await t.pumpAndSettle();
      expect(find.text('Why not?'), findsOneWidget);
      await t.enterText(find.byType(TextFormField), 'travel');
      await t.tap(find.text('Yes'));
      await t.pumpAndSettle();
      expect(find.text('Why not?'), findsNothing);
      // Back onto the branch: the abandoned answer did not survive the
      // switch — it would have gone out as an answer to a question that was
      // no longer being asked.
      await t.tap(find.text('No'));
      await t.pumpAndSettle();
      expect(find.text('travel'), findsNothing);
    });

    testWidgets('picks keep the form\'s order, and stars answer as N/5',
        (t) async {
      const f = [
        FormFieldSpec(
            label: 'Days',
            kind: FormFieldKind.chooseMany,
            options: ['Mon', 'Tue', 'Wed']),
        FormFieldSpec(label: 'Service', kind: FormFieldKind.rating),
        FormFieldSpec(label: 'Day', help: 'Any weekday works'),
      ];
      List<String>? sent;
      await t.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Center(
            child: ElevatedButton(
              onPressed: () async {
                sent = await Navigator.of(context).push<List<String>>(
                    MaterialPageRoute(
                        builder: (_) =>
                            const FormFillScreen(title: 'T', fields: f)));
              },
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await t.tap(find.text('open'));
      await t.pumpAndSettle();
      expect(find.text('Any weekday works'), findsOneWidget,
          reason: 'help text rides under its question');
      // Tapped out of order; the answer reads in the form's order, so the
      // same picks always come back as the same sentence.
      await t.tap(find.text('Wed'));
      await t.pump();
      await t.tap(find.text('Mon'));
      await t.pumpAndSettle();
      await t.tap(find.byIcon(Icons.star_outline_rounded).at(3));
      await t.pumpAndSettle();
      await t.tap(find.text('Send'));
      await t.pumpAndSettle();
      expect(sent, ['Mon, Wed', '4/5', '']);
    });

    testWidgets('nobody is shown declining a question they were never asked',
        (t) async {
      const branching = [
        FormFieldSpec(label: 'Coming?', kind: FormFieldKind.yesNo),
        FormFieldSpec(label: 'Why not?', showIfQ: 0, showIfIs: 'No'),
      ];
      await t.pumpWidget(MaterialApp(
        home: FormResponsesScreen(
          title: 'RSVP',
          fields: branching,
          responses: [
            FormResponse(
                from: 'Ada', answers: const ['Yes', ''], at: DateTime(2026))
          ],
        ),
      ));
      await t.pumpAndSettle();
      // In the response card and again in the summary — but never the
      // question this person was not asked.
      expect(find.text('Coming?'), findsWidgets);
      expect(find.text('Why not?'), findsNothing);
      expect(find.text('No answer'), findsNothing,
          reason: '"No answer" to a question never asked reads as declining');
    });

    testWidgets('the builder drops a condition its move made impossible',
        (t) async {
      t.view.physicalSize = const Size(500, 2200);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      (String, List<FormFieldSpec>)? sent;
      await t.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Center(
            child: ElevatedButton(
              onPressed: () async {
                sent = await Navigator.of(context)
                    .push<(String, List<FormFieldSpec>)>(MaterialPageRoute(
                        builder: (_) => const FormBuilderScreen()));
              },
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await t.tap(find.text('open'));
      await t.pumpAndSettle();

      await t.enterText(
          find.widgetWithText(TextField, 'What is this form for?'), 'RSVP');
      await t.enterText(find.byType(TextFormField).first, 'Coming?');
      await t.tap(find.text('Yes or no'));
      await t.pumpAndSettle();
      await t.ensureVisible(find.text('Add a question'));
      await t.tap(find.text('Add a question'));
      await t.pumpAndSettle();

      // The second question: label it, then gate it on the first.
      final labels = find.widgetWithText(TextFormField, 'Question 2');
      await t.enterText(labels.first, 'Why not?');
      await t.pumpAndSettle();
      await t.ensureVisible(find.text('Always asked'));
      await t.tap(find.text('Always asked'));
      await t.pumpAndSettle();
      await t.tap(find.text('Coming?').last); // the menu item, not the field
      await t.pumpAndSettle();

      // Move the gated question above the one that gates it. The condition
      // cannot point forwards, so it goes rather than silently inverting.
      await t.ensureVisible(find.byTooltip('Move up').last);
      await t.tap(find.byTooltip('Move up').last);
      await t.pumpAndSettle();

      await t.tap(find.text('Send'));
      await t.pumpAndSettle();
      expect(sent, isNotNull, reason: 'the reordered form still sends');
      expect(sent!.$2.first.label, 'Why not?');
      expect(sent!.$2.first.showIfQ, isNull,
          reason: 'a condition cannot point at a later question');
      expect(sent!.$2.last.label, 'Coming?');
    });

    test('the tally says its zeroes and skips the never-asked', () {
      const f = [
        FormFieldSpec(label: 'Coming?', kind: FormFieldKind.yesNo),
        FormFieldSpec(
            label: 'Course',
            kind: FormFieldKind.choice,
            options: ['Meat', 'Veg'],
            showIfQ: 0,
            showIfIs: 'Yes'),
      ];
      final rs = [
        FormResponse(
            from: 'Ada', answers: const ['Yes', 'Meat'], at: DateTime(2026)),
        // Bo said No, so Bo was never asked the course — a 'Meat' sitting in
        // the slot (stale, or crafted) is not an answer to it.
        FormResponse(
            from: 'Bo', answers: const ['No', 'Meat'], at: DateTime(2026)),
      ];
      expect(FormResponse.tally(f, rs, 0), {'Yes': 1, 'No': 1});
      expect(FormResponse.tally(f, rs, 1), {'Meat': 1, 'Veg': 0},
          reason: 'an option nobody picked is a said zero, not a gap');
    });

    test('choose-many picks each count, and stars average', () {
      const f = [
        FormFieldSpec(
            label: 'Days',
            kind: FormFieldKind.chooseMany,
            options: ['Mon', 'Tue']),
        FormFieldSpec(label: 'Service', kind: FormFieldKind.rating),
      ];
      final rs = [
        FormResponse(
            from: 'Ada', answers: const ['Mon, Tue', '5/5'], at: DateTime(2026)),
        FormResponse(
            from: 'Bo', answers: const ['Mon', '4/5'], at: DateTime(2026)),
      ];
      expect(FormResponse.tally(f, rs, 0), {'Mon': 2, 'Tue': 1});
      expect(FormResponse.ratingAverage(f, rs, 1), 4.5);
      expect(FormResponse.ratingAverage(f, const [], 1), isNull,
          reason: 'no ratings is no average, not zero stars');
      expect(FormResponse.ratingAverage(f, rs, 0), isNull,
          reason: 'only a rating question has one');
    });

    test('an answer the question refuses holds up the send', () {
      // Optional does not mean anything goes: an unanswered email question
      // is a choice, a malformed one is a typo about to go out.
      const f = [FormFieldSpec(label: 'Email', kind: FormFieldKind.email)];
      expect(FormResponse.isComplete(f, ['']), isTrue);
      expect(FormResponse.isComplete(f, ['ada@example.com']), isTrue);
      expect(FormResponse.isComplete(f, ['ada.example.com']), isFalse);
      expect(FormResponse.formatProblem(f.first, 'ada.example.com'),
          contains('email'));
      const p = [FormFieldSpec(label: 'Phone', kind: FormFieldKind.phone)];
      expect(FormResponse.isComplete(p, ['+1 555 0100']), isTrue);
      expect(FormResponse.isComplete(p, ['call me']), isFalse);
    });

    testWidgets('the sender gets the count without reading every card',
        (t) async {
      const f = [
        FormFieldSpec(
            label: 'Days',
            kind: FormFieldKind.chooseMany,
            options: ['Mon', 'Tue']),
        FormFieldSpec(label: 'Service', kind: FormFieldKind.rating),
        FormFieldSpec(label: 'Notes'),
      ];
      await t.pumpWidget(MaterialApp(
        home: FormResponsesScreen(
          title: 'Shifts',
          fields: f,
          responses: [
            FormResponse(
                from: 'Ada',
                answers: const ['Mon, Tue', '5/5', 'fine'],
                at: DateTime(2026)),
            FormResponse(
                from: 'Bo',
                answers: const ['Mon', '4/5', 'ok'],
                at: DateTime(2026)),
          ],
        ),
      ));
      await t.pumpAndSettle();
      expect(find.text('At a glance'), findsOneWidget);
      expect(find.text('Mon 2 · Tue 1'), findsOneWidget);
      expect(find.text('★ 4.5 average'), findsOneWidget);
      // Free text is left to the cards: a tally of sentences is nothing,
      // and the cards below still carry every word.
      expect(find.text('fine'), findsOneWidget);
    });

    testWidgets(
        'templates are offered never seeded, and a duplicate keeps its place',
        (t) async {
      t.view.physicalSize = const Size(500, 2400);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      (String, List<FormFieldSpec>)? sent;
      await t.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Center(
            child: ElevatedButton(
              onPressed: () async {
                sent = await Navigator.of(context)
                    .push<(String, List<FormFieldSpec>)>(MaterialPageRoute(
                        builder: (_) => const FormBuilderScreen()));
              },
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await t.tap(find.text('open'));
      await t.pumpAndSettle();

      // Offered: the chips are there, but the form itself starts blank.
      expect(find.text('RSVP'), findsOneWidget);
      expect(find.widgetWithText(TextFormField, 'Question 2'), findsNothing);
      await t.tap(find.text('RSVP'));
      await t.pumpAndSettle();
      // Taking one fills the form, and the offer leaves. The label shows in
      // its own card and in the two condition dropdowns naming it.
      expect(find.text('Coming?'), findsWidgets);
      expect(find.widgetWithText(ActionChip, 'Order'), findsNothing);

      // Duplicate the gating question: the conditions two cards down must
      // still name the original, not drift onto the copy or off the end.
      await t.tap(find.byTooltip('Duplicate question').first);
      await t.pumpAndSettle();
      await t.tap(find.text('Send'));
      await t.pumpAndSettle();
      expect(sent, isNotNull);
      expect(sent!.$1, 'RSVP');
      expect(sent!.$2.length, 4);
      expect(sent!.$2[1].label, 'Coming?');
      expect(sent!.$2[2].showIfQ, 0);
      expect(sent!.$2[3].showIfQ, 0);
    });

    test('nothing about a form reaches a server in the clear', () {
      // The rule this feature is most able to break: forms collect exactly
      // the kind of answer worth protecting, so they ride the encrypted
      // message path and never a table.
      final src = File('lib/state/chat_store.dart').readAsStringSync();
      expect(src.contains('applyFormResponse'), isTrue);
      for (final path in [
        'lib/models/form_spec.dart',
        'lib/screens/form_builder_screen.dart',
        'lib/screens/form_fill_screen.dart',
      ]) {
        final text = File(path).readAsStringSync();
        expect(text.contains('supabase'), isFalse, reason: path);
        expect(text.contains('http'), isFalse, reason: path);
      }
    });
  });
  group('quick replies', () {
    setUp(() {
      QuickReplies.instance.resetForTest();
      SharedPreferences.setMockInitialValues({});
    });
    tearDown(QuickReplies.instance.resetForTest);

    final store = QuickReplies.instance;

    test('newest first, and the same sentence is never saved twice', () async {
      expect(await store.add('On my way'), isTrue);
      expect(await store.add('Thanks'), isTrue);
      expect(store.all, ['Thanks', 'On my way'],
          reason: 'the one just saved is the one about to be used');

      // Duplicates make the picker longer without making it more useful, and
      // case is not a difference somebody means.
      expect(await store.add('thanks'), isFalse);
      expect(await store.add('  Thanks  '), isFalse);
      expect(store.all.length, 2);

      // Nothing is not a reply.
      expect(await store.add('   '), isFalse);
      expect(store.all.length, 2);
    });

    test('editing to nothing removes it rather than leaving a blank row',
        () async {
      await store.add('Thanks');
      await store.edit(0, '   ');
      expect(store.all, isEmpty,
          reason: 'a blank quick reply is a row that inserts nothing');
    });

    test('out-of-range edits and removes change nothing', () async {
      await store.add('Thanks');
      await store.edit(9, 'x');
      await store.removeAt(-1);
      await store.reorder(5, 0);
      // The destination is bounded too — a drop past the end would otherwise
      // throw out of insert() rather than being ignored.
      await store.reorder(0, 9);
      expect(store.all, ['Thanks']);
    });

    test('reordering puts the ones actually used at the top', () async {
      for (final r in ['third', 'second', 'first']) {
        await store.add(r);
      }
      expect(store.all, ['first', 'second', 'third']);
      // onReorderItem hands over the index AFTER the item is lifted out, so
      // there is no off-by-one to compensate for — doing it anyway swaps the
      // wrong pair and looks like the list ignoring the drag.
      await store.reorder(0, 2);
      expect(store.all, ['second', 'third', 'first']);
      await store.reorder(2, 0);
      expect(store.all, ['first', 'second', 'third']);
    });

    test('the list is capped, and says so before it is full', () async {
      for (var i = 0; i < QuickReplies.max; i++) {
        expect(await store.add('reply $i'), isTrue);
      }
      expect(store.isFull, isTrue);
      expect(await store.add('one more'), isFalse);
      expect(store.all.length, QuickReplies.max);
    });

    test('matching narrows on what has been typed', () async {
      await store.add('On my way');
      await store.add('Running late, sorry');
      expect(store.matching('').length, 2, reason: 'empty offers everything');
      expect(store.matching('LATE'), ['Running late, sorry']);
      expect(store.matching('nothing like this'), isEmpty);
    });

    test('they survive a restart, and blanks do not come back', () async {
      SharedPreferences.setMockInitialValues({
        'quick_replies_v1': ['Thanks', '   ', 'On my way'],
      });
      await store.load();
      expect(store.all, ['Thanks', 'On my way']);
    });

    test('nothing about them leaves the device', () {
      // The list of sentences somebody uses most is a fair description of
      // their life. It is not in the backup and not on a server.
      final src = File('lib/state/quick_replies.dart').readAsStringSync();
      expect(src.contains('supabase'), isFalse);
      expect(src.contains('RelayService'), isFalse);
      expect(File('lib/state/cloud_sync.dart').readAsStringSync()
          .contains('quick_replies'), isFalse,
          reason: 'they rode the cloud sync, which is not where they belong');
    });

    test('the suggestions are offered, never seeded', () {
      // Writing them in would be inventing content in somebody's own words,
      // which is the no-fake-data rule.
      expect(QuickReplies.suggestions, isNotEmpty);
      expect(store.all, isEmpty);
      final src = File('lib/screens/quick_replies_screen.dart')
          .readAsStringSync();
      expect(src.contains('onPressed: () => QuickReplies.instance.add(s)'),
          isTrue,
          reason: 'a suggestion has to be tapped to become a reply');
    });

    testWidgets('a saved reply is inserted, never sent', (t) async {
      // A canned reply that sends itself is a message nobody read before it
      // left.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final fn = src.substring(src.indexOf('Future<void> _handleQuickReply()'),
          src.indexOf('/// Builds a form and sends it as a message.'));
      expect(fn.contains('_store.setDraft'), isTrue);
      expect(fn.contains('_deliver('), isFalse,
          reason: 'the picker sent the message instead of typing it');
      // And it appends rather than replacing what is already typed.
      expect(fn.contains("existing.isEmpty ? reply : '\$existing \$reply'"),
          isTrue);
    });
  });
}
